  @override
  String get kratomSubtitleNotStarted =>
      'Zobacz, co się stanie, gdy odejdziesz.';

  @override
  String get kratomInfoBox =>
      'Kratom działa na receptory opioidowe, więc zaprzestanie stosowania leku może spowodować powstanie opioidów podobnych do opioidów. W przypadku intensywnego stosowania leku lub w połączeniu z innymi opioidami, należy zapytać lekarza prowadzącego o nadzór medyczny.';

  @override
  String get addictionKratom => 'Kratom';

  @override
  String get kratomMilestone1Title => 'Początek objawów odstawiennych';

  @override
  String get kratomMilestone1Description =>
      'Kratom działa na receptory opioidowe, dlatego w ciągu 6–12 godzin od ostatniej dawki mogą pojawić się niepokój, lęk, potliwość, katar i bóle mięśni. Układ nerwowy zaczyna się przystosowywać.';

  @override
  String get kratomMilestone3Title => 'Szczyt objawów odstawiennych';

  @override
  String get kratomMilestone3Description =>
      'Ostre objawy zwykle osiągają szczyt około 2.–3. dnia: nasilają się bóle, bezsenność, dolegliwości żołądkowe i obniżony nastrój. To najtrudniejsza faza, ale jest przejściowa.';

  @override
  String get kratomMilestone7Title => 'Ostre objawy słabną';

  @override
  String get kratomMilestone7Description =>
      'Po tygodniu najgorsze objawy fizyczne — bóle, dolegliwości żołądkowe i potliwość — w dużej mierze ustępują. Sen i energia nadal się regenerują.';

  @override
  String get kratomMilestone14Title => 'Sen i nastrój się poprawiają';

  @override
  String get kratomMilestone14Description =>
      'Po dwóch tygodniach sen staje się bardziej regularny, a nastrój stabilniejszy, gdy naturalny układ nagrody w mózgu zaczyna odzyskiwać równowagę.';

  @override
  String get kratomMilestone30Title => 'Miesiąc bez kratomu';

  @override
  String get kratomMilestone30Description =>
      'Po miesiącu organizm jest znacznie stabilniejszy: sen, apetyt i energia wyraźnie się poprawiają, a silna chęć sięgnięcia po kratom pojawia się rzadziej.';

  @override
  String get kratomMilestone90Title => 'Stabilna podstawa';

  @override
  String get kratomMilestone90Description =>
      'Trzy miesiące bez kratomu dają układom nagrody i stresu w mózgu więcej czasu na ponowną regulację. Nastrój, koncentracja i motywacja stają się zauważalnie stabilniejsze.';

  @override
  String get kratomMilestone365Title => 'Rok bez kratomu';

  @override
  String get kratomMilestone365Description =>
      'Pełny rok bez kratomu. Układ opioidowy miał dużo czasu na ponowną regulację, silna chęć użycia pojawia się rzadko, a nawyk nie organizuje już dnia.';

  @override
  String get kratomMilestone730Title => 'Dwa lata: Mocny fundament';

  @override
  String get kratomMilestone730Description =>
      'Dwa lata bez kratomu to długi okres trwałej zmiany. Rutyny i decyzje, które podtrzymywały ten kierunek, miały czas stać się częścią codzienności.';

  @override
  String get kratomMilestone1095Title => 'Trzy lata: Własny rozpęd';

  @override
  String get kratomMilestone1095Description =>
      'Trzy lata oznaczają kolejny pełny rok życia zbudowanego poza kratomem. Ta konsekwencja to rozpęd wypracowany przez długi czas.';

  @override
  String get kratomMilestone1460Title => 'Cztery lata: Trwała wolność';

  @override
  String get kratomMilestone1460Description =>
      'Cztery lata to trwała wolność wsparta tysiącami zwykłych codziennych decyzji. To, co kiedyś wymagało stałego wysiłku, może dziś pozostawać znacznie dalej w tle.';

  @override
  String get kratomMilestone1825Title => 'Pięć lat: Trwała zmiana';

  @override
  String get kratomMilestone1825Description =>
      'Pięć lat to ważna rocznica: 1825 dni utrzymywania tego samego kierunku. Życie zbudowane wokół tej decyzji jest właściwym osiągnięciem.';

  @override
  String get gabapentinoidsPageTitle => 'Gabapentynoidy';

  @override
  String get gabapentinoidsHeaderStarted =>
      'Twoja podróż po powrocie do zdrowia';

  @override
  String get gabapentinoidsHeaderNotStarted =>
