  @override
  String get gabapentinoidsSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get gabapentinoidsSubtitleNotStarted =>
      'Zobacz, co się stanie, gdy odejdziesz.';

  @override
  String get gabapentinoidsInfoBox =>
      'Nigdy nie należy przerywać leczenia gabapentyną lub pregabaliną. Nagłe przerwanie leczenia może wywołać napady padaczkowe, szczególnie jeśli pacjent przyjmuje je z powodu padaczki.';

  @override
  String get addictionGabapentinoid => 'Gabapentyna / pregabalina';

  @override
  String get ghbPageTitle => 'Odzyskiwanie GHB';

  @override
  String get ghbHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get ghbHeaderNotStarted => 'Korzyści wynikające z rezygnacji z GHB';

  @override
  String get ghbSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get ghbSubtitleNotStarted => 'Zobacz, co się stanie, gdy odejdziesz.';

  @override
  String get ghbInfoBox =>
      'Wycofanie GHB to nagły wypadek medyczny, ponieważ rywalizuje z alkoholem i benzodiazepiną i może powodować delirium i amfetaminy.';

  @override
  String get addictionGhb => 'GHB';

  @override
  String get ghbMilestone1Title => 'Skorzystaj z pomocy medycznej';

  @override
  String get ghbMilestone1Description =>
      'GHB ma bardzo krótki okres półtrwania, więc objawy odstawienia mogą zacząć się już 1–6 godzin po ostatniej dawce: lęk, drżenie, bezsenność i przyspieszone tętno. To jeden z najniebezpieczniejszych zespołów odstawiennych — skorzystaj z pomocy medycznej.';

  @override
  String get ghbMilestone3Title => 'Szczyt zagrożenia';

  @override
  String get ghbMilestone3Description =>
      'Objawy osiągają szczyt po około 48–72 godzinach i mogą nasilić się do silnego pobudzenia, omamów i majaczenia. Ten etap wymaga nadzoru medycznego.';

  @override
  String get ghbMilestone7Title => 'Ostra faza ustępuje';

  @override
  String get ghbMilestone7Description =>
      'Po około tygodniu ostry zespół zwykle zaczyna ustępować, choć w ciężkich przypadkach majaczenie może trwać dłużej. Najbardziej niebezpieczny etap jest już za Tobą.';

  @override
  String get ghbMilestone14Title => 'Najgorsze za Tobą';

  @override
  String get ghbMilestone14Description =>
      'Po dwóch tygodniach nawet ciężkie odstawienie zwykle ma już za sobą ostrą fazę. Sen i stabilność układu autonomicznego wracają, choć lęk może się jeszcze utrzymywać.';

  @override
  String get ghbMilestone30Title => 'Miesiąc stabilizacji';

  @override
  String get ghbMilestone30Description =>
      'Po miesiącu niebezpieczny wczesny okres odstawienia jest już daleko za Tobą. Utrzymujący się lęk, problemy ze snem i obniżony nastrój nadal się poprawiają.';

  @override
  String get ghbMilestone90Title => 'Pozostałe objawy słabną';

  @override
  String get ghbMilestone90Description =>
      'Po trzech miesiącach utrzymujące się objawy lęku, zaburzeń snu i nastroju słabną, gdy uspokajający układ GABA w mózgu dalej się stabilizuje.';

  @override
  String get ghbMilestone180Title => 'Pół roku bez GHB';

  @override
  String get ghbMilestone180Description =>
      'Sześć miesięcy bez GHB. Przedłużające się objawy odstawienia w dużej mierze ustąpiły, a nastrój, sen i jasność myślenia wróciły do normy.';

  @override
  String get ketaminePageTitle => 'Odzysk ketaminy';

  @override
  String get ketamineHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get ketamineHeaderNotStarted => 'Korzyści z rzucenia ketaminy';

  @override
  String get ketamineSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get ketamineSubtitleNotStarted =>
      'Zobacz, co się stanie, gdy odejdziesz.';

  @override
  String get ketamineInfoBox =>
      'Wycofanie ketaminy jest głównie rzemiosła, niski nastrój, i mgła mózgu, a nie choroby fizycznej. Największą szkodą fizyczną jest uszkodzenie pęcherza moczowego, a zatrzymanie jest istotnym pierwszym krokiem w kierunku odzyskania.';

  @override
  String get addictionKetamine => 'Ketamina';

  @override
  String get ketamineMilestone1Title => 'Ketamina opuszcza organizm';

  @override
  String get ketamineMilestone1Description =>
      'Ketamina rzadko wywołuje ciężki fizyczny zespół odstawienny. Pierwszego dnia, gdy lek jest usuwany z organizmu, mogą pojawić się wahania nastroju, głód ketaminy, potliwość lub kołatanie serca.';

  @override
  String get ketamineMilestone7Title => 'Nastrój i głód ketaminy';

  @override
  String get ketamineMilestone7Description =>
      'W pierwszym tygodniu większym wyzwaniem niż objawy fizyczne są zwykle głód ketaminy, obniżony lub zmienny nastrój i mgła mózgowa.';

  @override
  String get ketamineMilestone14Title => 'Mgła mózgowa ustępuje';

  @override
  String get ketamineMilestone14Description =>
      'Po dwóch tygodniach myślenie i pamięć zaczynają się poprawiać, a nastrój stabilizuje się wraz z pełnym ustępowaniem efektów dysocjacyjnych.';

  @override
  String get ketamineMilestone30Title => 'Miesiąc — regeneracja pęcherza';

  @override
  String get ketamineMilestone30Description =>
      'Po miesiącu wczesne uszkodzenia pęcherza często zaczynają się poprawiać po odstawieniu. Nastrój i myślenie są wyraźniejsze.';

  @override
  String get ketamineMilestone90Title => 'Trzy miesiące bez ketaminy';

  @override
  String get ketamineMilestone90Description =>
      'Trzy miesiące bez ketaminy dają pęcherzowi więcej czasu na gojenie, a myślenie i nastrój nadal się poprawiają. Głód ketaminy pojawia się rzadziej.';

  @override
  String get ketamineMilestone180Title => 'Pół roku bez ketaminy';

  @override
  String get ketamineMilestone180Description =>
      'Sześć miesięcy bez ketaminy. Objawy ze strony pęcherza miały więcej czasu na poprawę, a psychiczna potrzeba używania ketaminy znacznie osłabła.';

  @override
  String get ketamineMilestone365Title => 'Rok bez ketaminy';

  @override
  String get ketamineMilestone365Description =>
      'Rok bez ketaminy. Myślenie i nastrój, a przy wcześnie wykrytym uszkodzeniu także funkcja pęcherza, miały cały rok na regenerację.';

  @override
  String get ketamineMilestone730Title => 'Dwa lata: Mocniejszy grunt';

  @override
  String get ketamineMilestone730Description =>
      'Dwa lata bez ketaminy to trwały postęp. Dalsze nieużywanie zapobiega ponownej ekspozycji, a tempo zdrowienia po wcześniejszym używaniu może być różne.';

  @override
  String get ketamineMilestone1095Title => 'Trzy lata: Utrwalony impet';

  @override
  String get ketamineMilestone1095Description =>
      'Trzy lata oznaczają trwały postęp. Badania wskazują na poprawę po odstawieniu ketaminy, ale nie wyznaczają szczególnego biologicznego punktu po trzech latach.';

  @override
  String get ketamineMilestone1460Title => 'Cztery lata: Stała siła';

  @override
  String get ketamineMilestone1460Description =>
      'Cztery lata to kolejny rok z dala od ketaminy. Długoterminowa poprawa może trwać dalej, a wynik zależy od wcześniejszej ekspozycji i istniejących uszkodzeń.';

  @override
  String get ketamineMilestone1825Title => 'Pięć lat: Głębokie korzenie';

  @override
  String get ketamineMilestone1825Description =>
      'Pięć lat to ważny, długoterminowy kamień milowy. Utrzymywanie rutyn i wsparcia, które pomogły dojść tak daleko, wzmacnia zbudowane podstawy.';

  @override
  String get inhalantsPageTitle => 'Substancje wziewne';

  @override
  String get inhalantsHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get inhalantsHeaderNotStarted => 'Korzyści z odpuszczenia inhalantów';

  @override
  String get inhalantsSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get inhalantsSubtitleNotStarted =>
      'Zobacz, co się stanie, gdy odejdziesz.';

  @override
  String get inhalantsInfoBox =>
      'Wdychanie jest krótsze niż spożywanie alkoholu lub opioidów, ale może być intensywne, z ryzykiem drgawek u pacjentów z ciężkimi zapaleniami. regeneracja neurologiczna jest rzeczywista, ale powolna często rozwija się przez około dwa lata abstynencji.';

  @override
  String get addictionInhalants => 'Inhalanty';

  @override
  String get inhalantsMilestone1Title => 'Organizm zaczyna usuwać substancje';

  @override
  String get inhalantsMilestone1Description =>
      'Substancje wziewne szybko znikają z krwi, ale mogą dłużej pozostawać w tkance tłuszczowej. Pierwszego dnia mogą wystąpić ból głowy, drażliwość, nudności, lęk lub bezsenność.';

  @override
  String get inhalantsMilestone7Title => 'Ostre objawy słabną';

  @override
  String get inhalantsMilestone7Description =>
      'Ostre objawy odstawienne zwykle osiągają szczyt około 2.–5. dnia i w dużej mierze ustępują w ciągu jednego–dwóch tygodni. Po tygodniu najtrudniejszy okres zwykle zaczyna mijać.';

  @override
  String get inhalantsMilestone14Title => 'Koniec ostrej fazy';

  @override
  String get inhalantsMilestone14Description =>
      'Po dwóch tygodniach wczesna faza odstawienia zwykle jest już zakończona. Nastrój staje się stabilniejszy, choć zamglenie myślenia i zmęczenie mogą się utrzymywać.';

  @override
  String get inhalantsMilestone30Title => 'Miesiąc — mózg się regeneruje';

  @override
  String get inhalantsMilestone30Description =>
      'Po miesiącu najgorsze wczesne skutki są już za tobą, a myślenie i pamięć zaczynają się poprawiać. Rośnie jasność umysłu i poprawia się nastrój.';

  @override
  String get inhalantsMilestone90Title => 'Trzy miesiące postępu';

  @override
  String get inhalantsMilestone90Description =>
      'Trzy miesiące bez inhalantów wspierają dalszą poprawę pamięci, uwagi i funkcji motorycznych. Postęp jest stopniowy, ale rzeczywisty.';

  @override
  String get inhalantsMilestone365Title => 'Rok — wyraźna poprawa';

  @override
  String get inhalantsMilestone365Description =>
      'Rok abstynencji przynosi u większości osób znaczną poprawę neurologiczną, a dalszego postępu można oczekiwać w drugim roku.';

  @override
  String get inhalantsMilestone730Title => 'Dwa lata — długoterminowa poprawa';

  @override
  String get inhalantsMilestone730Description =>
      'Po dwóch latach abstynencji badania wykazały znaczną poprawę funkcji mózgu. Wyjątkiem są uszkodzenia po benzynie ołowiowej, które mogą się utrzymywać.';

  @override
  String get synthetic_cannabinoidsPageTitle => 'Synt. kannabinoidy';

  @override
  String get synthetic_cannabinoidsHeaderStarted =>
      'Twoja droga do regeneracji';

  @override
  String get synthetic_cannabinoidsHeaderNotStarted =>
      'Korzyści z odstawienia syntetycznych kannabinoidów';

  @override
  String get synthetic_cannabinoidsSubtitleStarted =>
      'Śledź postępy i świętuj każdy kamień milowy';

  @override
  String get synthetic_cannabinoidsSubtitleNotStarted =>
      'Zobacz, co dzieje się po odstawieniu';

  @override
  String get synthetic_cannabinoidsInfoBox =>
      'Syntetyczne kannabinoidy („Spice”, „K2”) mogą być znacznie silniejsze i bardziej nieprzewidywalne niż konopie. Odstawienie może być cięższe; opisywano drgawki, pobudzenie i przyspieszone tętno, a ostre zatrucie może również wywołać psychozę. Ciężkie objawy wymagają pilnej pomocy medycznej.';

  @override
  String get addictionSyntheticCannabinoids => 'Syntetyczne kannabinoidy';

  @override
  String get synthetic_cannabinoidsMilestone1Title => 'Początek odstawienia';

  @override
  String get synthetic_cannabinoidsMilestone1Description =>
      'Po częstym używaniu objawy odstawienia mogą pojawić się szybko. Opisywano problemy ze snem, drażliwość, obniżony nastrój, poty, kołatanie serca, pobudzenie i drżenie — ciężkie przypadki mogą obejmować nawracające drgawki albo problemy sercowo-naczyniowe lub oddechowe.';

  @override
  String get synthetic_cannabinoidsMilestone3Title => 'Trudny początek';

  @override
  String get synthetic_cannabinoidsMilestone3Description =>
      'Trzy dni bez używania. Odstawienie syntetycznych kannabinoidów może być cięższe niż odstawienie konopi o wysokiej mocy, więc ten początkowy etap jest poważny. Już tworzy Pan/Pani realny dystans od kolejnej dawki.';

  @override
  String get synthetic_cannabinoidsMilestone7Title => 'Mocny tydzień';

  @override
  String get synthetic_cannabinoidsMilestone7Description =>
      'Pełny tydzień. Odstawienie syntetycznych kannabinoidów może być ciężkie i bardziej fizyczne niż odstawienie konopi. Siedem dni bez kolejnej dawki to duże zwycięstwo.';

  @override
  String get synthetic_cannabinoidsMilestone14Title =>
      'Dwa tygodnie bez używania';

  @override
  String get synthetic_cannabinoidsMilestone14Description =>
      'Dwa tygodnie bez używania. Syntetyczne kannabinoidy to inna liga: czternaście dni bez ponownej ekspozycji na grupę substancji powiązaną z drgawkami, psychozą i problemami z sercem.';

  @override
  String get synthetic_cannabinoidsMilestone30Title => 'Miesiąc bez używania';

  @override
  String get synthetic_cannabinoidsMilestone30Description =>
      'Pełny miesiąc bez używania. Trzydzieści dni bez ponownej ekspozycji na nieprzewidywalną moc i ostrą toksyczność syntetycznych kannabinoidów. Ogromny kamień milowy.';

  @override
  String get synthetic_cannabinoidsMilestone90Title =>
      'Trzy miesiące bez używania';

  @override
  String get synthetic_cannabinoidsMilestone90Description =>
      'Trzy miesiące bez używania. Utrzymuje Pan/Pani duży dystans od grupy substancji związanej z ciężkim odstawieniem, drgawkami, problemami sercowo-naczyniowymi i psychozą. Tak trzymać.';

  @override
  String get synthetic_cannabinoidsMilestone180Title => 'Pół roku bez używania';

  @override
  String get synthetic_cannabinoidsMilestone180Description =>
      'Pół roku bez używania. Sześć miesięcy bez syntetycznych kannabinoidów to ogromne osiągnięcie — sześć miesięcy bez kolejnej rundy ich nieprzewidywalnych ostrych zagrożeń.';

  @override
  String get synthetic_cannabinoidsWithdrawalReference =>
      'Odstawienie syntetycznych kannabinoidów\n\nŹródło: Craft et al. (2022), Psychopharmacology, PMC\n\nWśród 284 osób, które w poprzednim roku używały syntetycznych agonistów receptorów kannabinoidowych ponad dziesięć razy i próbowały przestać, 82,7% zgłosiło co najmniej jeden objaw odstawienia po ponad jednej dobie bez używania. Najczęstsze były problemy ze snem (59,2%), drażliwość (55,6%) i obniżony nastrój (54,2%); zgłaszano też poty, kołatanie serca, głód substancji, pobudzenie i drżenie. Częstsze i większe używanie wiązało się z większą liczbą objawów. W bezpośrednim porównaniu odstawienie syntetycznych kannabinoidów oceniano jako cięższe niż odstawienie konopi o wysokiej mocy.';

  @override
  String get synthetic_cannabinoidsRiskReference =>
      'Odstawienie i ostre ryzyko syntetycznych kannabinoidów\n\nŹródło: Cooper (2016), Current Psychiatry Reports, PMC\n\nOpisy kliniczne wskazują, że po codziennym używaniu objawy odstawienia mogą pojawić się szybko po ostatniej dawce i obejmować silny lęk, bezsenność, nudności i wymioty, poty, kołatanie serca, drżenie, pobudzenie i głód substancji. W ciężkich przypadkach występowały nawracające drgawki oraz problemy sercowo-naczyniowe lub oddechowe. Przegląd opisuje też nieprzewidywalne i czasem ciężkie zatrucia, w tym psychozę, drgawki, incydenty sercowe i uszkodzenie nerek. Ciężkie lub nasilające się objawy wymagają szybkiej oceny medycznej.';

  @override
  String get synthetic_cannabinoidsMilestone730Title =>
      'Dwa lata — Mocny grunt';

  @override
  String get synthetic_cannabinoidsMilestone730Description =>
      'Dwa lata bez syntetycznych kannabinoidów. To 730 dni bez powrotu do nich. Taka konsekwencja zasługuje na prawdziwe świętowanie.';

  @override
  String get synthetic_cannabinoidsMilestone1095Title =>
      'Trzy lata — Wciąż mocno';

  @override
  String get synthetic_cannabinoidsMilestone1095Description =>
      'Trzy lata bez syntetycznych kannabinoidów. Zmianę liczysz już w latach, nie dniach. Nadal wybierasz życie z dala od nich.';

  @override
  String get synthetic_cannabinoidsMilestone1460Title =>
      'Cztery lata — Na trwałe';

  @override
  String get synthetic_cannabinoidsMilestone1460Description =>
      'Cztery lata bez syntetycznych kannabinoidów. To, co zaczęło się od odstawienia, stało się trwałe: 1460 dni z dala od nich.';

  @override
  String get synthetic_cannabinoidsMilestone1825Title =>
      'Pięć lat — Pół dekady';

  @override
  String get synthetic_cannabinoidsMilestone1825Description =>
      'Pięć lat bez syntetycznych kannabinoidów. Pół dekady to ogromne długoterminowe zwycięstwo. Ten postęp jest Twój.';

  @override
  String get synthetic_cannabinoidsLongTermReference =>
      'Syntetyczne kannabinoidy: co potwierdzają dowody\n\nŹródło: wytyczne konsensusowe British Association for Psychopharmacology dotyczące leczenia uzależnień (2026), PMC\n\nWytyczne wskazują, że syntetyczne kannabinoidy mogą powodować cięższy zespół odstawienny niż konopie i czasem wymagać detoksykacji szpitalnej. Stwierdzają też, że nie ma opartej na dowodach farmakoterapii podtrzymującej ani zapobiegającej nawrotom w przypadku syntetycznych kannabinoidów.\n\nWytyczne nie określają biologicznego progu zdrowienia po 2, 3, 4 ani 5 latach. Te rocznice celebrują więc trwały postęp bez przypisywania medycznego terminu, którego dowody nie potwierdzają.';

  @override
  String get mdmaPageTitle => 'MDMA';

  @override
  String get mdmaHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get mdmaHeaderNotStarted => 'Korzyści z rezygnacji z MDMA';

  @override
  String get mdmaSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get mdmaSubtitleNotStarted => 'Zobacz, co się stanie, gdy odejdziesz.';

  @override
  String get mdmaInfoBox =>
      'MDMA powodzi, a następnie uszczupla serotoniny, produkując wzrost i, po intensywnym użyciu, z drawal- jak niski nastrój. Poziom transportera serotoniny odzyskać z trwałym abstynencji, choć intensywne stosowanie może pozostawić długotrwałe skutki.';

  @override
  String get addictionMdma => 'MDMA';

  @override
  String get mdmaMilestone1Title => 'Zejście';

  @override
  String get mdmaMilestone1Description =>
      'Po MDMA spadek dostępnej serotoniny może wywołać „zejście”: obniżony nastrój, zmęczenie, drażliwość i gorszy sen przez dzień lub dwa. Pomagają nawodnienie, jedzenie i odpoczynek.';

  @override
  String get mdmaMilestone3Title => 'Nastrój wraca do równowagi';

  @override
  String get mdmaMilestone3Description =>
      'Po kilku dniach najostrzejsza część zejścia zwykle mija. Wraz z odbudową serotoniny nastrój i energia zaczynają się stabilizować.';

  @override
  String get mdmaMilestone7Title => 'Koniec ostrej fazy';

  @override
  String get mdmaMilestone7Description =>
      'Po intensywniejszym używaniu objawy podobne do odstawienia, takie jak obniżony nastrój, gorsza koncentracja i głód substancji, mogą utrzymywać się około tygodnia, zanim zaczną słabnąć.';

  @override
  String get mdmaMilestone14Title => 'Dwa tygodnie';

  @override
  String get mdmaMilestone14Description =>
      'Dwa tygodnie abstynencji zwykle przynoszą wyraźną poprawę nastroju, snu i koncentracji w miarę regeneracji układu serotoninowego.';

  @override
  String get mdmaMilestone30Title => 'Miesiąc bez MDMA';

  @override
  String get mdmaMilestone30Description =>
      'Po miesiącu nastrój i myślenie są znacznie stabilniejsze. Układ odpowiedzialny za wychwyt zwrotny serotoniny nadal się regeneruje, gdy pozostajesz bez MDMA.';

  @override
  String get mdmaMilestone90Title => 'Trzy miesiące';

  @override
  String get mdmaMilestone90Description =>
      'Trzy miesiące abstynencji wspierają dalszą regenerację układu serotoninowego. Nastrój i sen są stabilniejsze, a lęk zwykle słabnie w kolejnych miesiącach.';

  @override
  String get mdmaMilestone365Title => 'Rok bez MDMA';

  @override
  String get mdmaMilestone365Description =>
      'Rok bez MDMA. Funkcjonowanie układu serotoninowego i nastrój miały dużo czasu na poprawę, a lęk związany z używaniem zwykle do tego momentu ustępuje.';

  @override
  String get steroidsPageTitle => 'Sterydy anaboliczne';

  @override
  String get steroidsHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get steroidsHeaderNotStarted =>
      'Korzyści z rzucenia sterydów anabolicznych';

  @override
  String get steroidsSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get steroidsSubtitleNotStarted =>
      'Zobacz, co się stanie, gdy odejdziesz.';

  @override
  String get steroidsInfoBox =>
      'Zatrzymanie sterydów anabolicznych pozostawia testosteron niski, aż organizm ponownie rozpoczyna własną produkcję hormonów zwykle nad miesiącami, ale czasami dłużej. Depresja i niskie libido są powszechne w tym fazie; ciężka depresja lub myśli samobójcze wymagają pilnej opieki medycznej.';

  @override
  String get addictionSteroids => 'Sterydy anaboliczne';

  @override
  String get steroidsMilestone1Title => 'Początek niedoboru hormonów';

  @override
  String get steroidsMilestone1Description =>
      'Sterydy anaboliczne hamują własną produkcję testosteronu w organizmie. Po odstawieniu pojawia się niedobór hormonów, który może powodować zmęczenie, obniżony nastrój i spadek libido. Wskazana jest opieka medyczna.';

  @override
  String get steroidsMilestone14Title => 'Faza adaptacji';

  @override
  String get steroidsMilestone14Description =>
      'Pierwsze tygodnie bywają najtrudniejszą częścią spadku hormonów: energia, nastrój i libido mogą być obniżone. To okres, w którym część osób wraca do sterydów, by uniknąć objawów; wsparcie pomaga go przejść.';

  @override
  String get steroidsMilestone30Title => 'Miesiąc — oś hormonalna rusza';

  @override
  String get steroidsMilestone30Description =>
      'Po miesiącu układ hormonalny łączący mózg i jądra zaczyna ponownie działać. Hormony sterujące produkcją testosteronu oraz sam testosteron stopniowo rosną, choć obniżony nastrój, libido lub energia mogą nadal się utrzymywać.';

  @override
  String get steroidsMilestone90Title => 'Trzy miesiące — hormony rosną';

  @override
  String get steroidsMilestone90Description =>
      'Po trzech miesiącach u wielu osób testosteron i hormony sterujące jego produkcją rosną w kierunku normy. Wraz z nimi często poprawiają się nastrój i libido.';

  @override
  String get steroidsMilestone180Title => 'Sześć miesięcy — duży postęp';

  @override
  String get steroidsMilestone180Description =>
      'Po sześciu miesiącach u wielu osób regeneracja hormonalna jest już znacznie zaawansowana. Testosteron i hormony sterujące jego produkcją często wracają do zakresu normy, a objawy słabną.';

  @override
  String get steroidsMilestone365Title => 'Rok';

  @override
  String get steroidsMilestone365Description =>
      'Pełny rok bez sterydów to ogromny kamień milowy. Odbudowa hormonalna często trwa miesiącami, a wielkość jąder, produkcja plemników i libido mogą poprawiać się przez miesiące lub lata. Utrzymujące się objawy niskiego testosteronu warto skonsultować ze specjalistą.';

  @override
  String get steroidsMilestone730Title => 'Dwa lata w nowym standardzie';

  @override
  String get steroidsMilestone730Description =>
      'Dwa lata bez sterydów. Powrót do zdrowia po AAS jest bardzo indywidualny, ale własny układ hormonalny miał dużo czasu na regenerację. Jeśli objawy niskiego testosteronu nadal się utrzymują, warto je ocenić u specjalisty zamiast wracać do kolejnego cyklu.';

  @override
  String get appTitle => 'Quitter';

  @override
  String get start => 'Rozpocznij';

  @override
  String get tabQuitter => 'Quitter';

  @override
  String get adderallPageTitle => 'Adderall';

  @override
  String get adderallHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get adderallHeaderNotStarted => 'Gotowy do startu?';

  @override
  String get adderallSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy, jak twój mózg leczy';

  @override
  String get adderallSubtitleNotStarted =>
      'Zobacz, co się stanie, gdy odejdziesz z Adderall i rozpoczniesz podróż do powrotu do zdrowia.';

  @override
  String get adderallMilestone1Title =>
      'Pierwsze 24 godziny: początek odstawienia';

  @override
  String get adderallMilestone1Description =>
      'Możesz odczuwać większe zmęczenie, obniżony nastrój i zwiększony apetyt, gdy organizm zaczyna przystosowywać się do życia bez stymulantów. To normalne i przejściowe. Pij odpowiednio dużo płynów i odpoczywaj, gdy tego potrzebujesz.';

  @override
  String get adderallMilestone3Title => 'Dzień 3: szczyt objawów odstawiennych';

  @override
  String get adderallMilestone3Description =>
      'Objawy odstawienne osiągają największe nasilenie. Możesz odczuwać silne zmęczenie, drażliwość i trudności z koncentracją. To często najtrudniejszy etap, ale od tego momentu stopniowo robi się łatwiej. W razie potrzeby skorzystaj ze wsparcia bliskich lub specjalistów.';

  @override
  String get adderallMilestone7Title => 'Tydzień: objawy fizyczne słabną';

  @override
  String get adderallMilestone7Description =>
      'Najsilniejsze fizyczne objawy odstawienia zaczynają ustępować. Sen stopniowo się normalizuje, a poziom energii powoli rośnie. Organizm przyzwyczaja się do funkcjonowania bez stymulantów.';

  @override
  String get adderallMilestone14Title =>
      'Dwa tygodnie: wraca stabilność emocjonalna';

  @override
  String get adderallMilestone14Description =>
      'Wahania nastroju i drażliwość zmniejszają się. W miarę dalszego przystosowywania się mózgu odzyskujesz większą równowagę emocjonalną. Dla wielu osób ten okres jest ważnym punktem zwrotnym w zdrowieniu.';

  @override
  String get adderallMilestone30Title => 'Miesiąc: mózg odzyskuje równowagę';

  @override
  String get adderallMilestone30Description =>
      'Mózg nadal się regeneruje. Naturalne funkcjonowanie układu dopaminowego poprawia się, a koncentracja i motywacja bez leku mogą być coraz lepsze. Sen i apetyt wracają do bardziej typowego rytmu.';

  @override
  String get adderallMilestone60Title =>
      'Dwa miesiące: poprawa myślenia i pamięci';

  @override
  String get adderallMilestone60Description =>
      'Jasność myślenia, pamięć i stabilność nastroju mogą wyraźnie się poprawiać. Układ nagrody w mózgu regeneruje się, dzięki czemu zwykłe czynności znów mogą dawać naturalną satysfakcję. Wiele osób zaczyna czuć się bardziej sobą.';

  @override
  String get adderallMilestone90Title => 'Trzy miesiące: ważny etap zdrowienia';

  @override
  String get adderallMilestone90Description =>
      'Większość objawów odstawiennych ustąpiła. Mózg poczynił duże postępy w regeneracji. Naturalny poziom energii, koncentracja i regulacja emocji mogą być znacznie lepsze. To osiągnięcie warte świętowania.';

  @override
  String get adderallMilestone180Title =>
      'Sześć miesięcy: regeneracja mózgu trwa';

  @override
  String get adderallMilestone180Description =>
      'Sygnalizacja dopaminowa nadal się regeneruje. Koncentracja, pamięć, nastrój i codzienna jakość życia mogą dalej się poprawiać.';

  @override
  String get adderallMilestone365Title => 'Rok: daleko posunięta regeneracja';

  @override
  String get adderallMilestone365Description =>
      'Układ dopaminowy mózgu w dużej mierze odzyskał prawidłowe funkcjonowanie. Pokazujesz swoją odporność, budując życie bez zależności od stymulantów. Warto docenić, jak daleko udało Ci się dojść.';

  @override
  String get benzoPageTitle => 'Benzodiazepiny';

  @override
  String get benzoHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get benzoHeaderNotStarted => 'Korzyści z rzucenia benzodiazepin';

  @override
  String get benzoSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get benzoSubtitleNotStarted =>
      'Zobacz, co się stanie, gdy odejdziesz.';

  @override
  String get benzoMilestone7Title => 'Tydzień 1: początek objawów';

  @override
  String get benzoMilestone7Description =>
      'Do 7. dnia obejmujesz całe typowe okno początku objawów: po krótko działających benzodiazepinach odstawienie zwykle zaczyna się po 1–2 dniach, a po długo działających po 2–7 dniach. Stopniowe zmniejszanie dawki pomaga zapobiegać napadom drgawkowym.';

  @override
  String get benzoMilestone14Title => 'Dwa tygodnie: wraca głęboki sen';

  @override
  String get benzoMilestone14Description =>
      'Około dwóch tygodni po stopniowym odstawieniu benzodiazepin badanie kliniczne snu wykazało więcej snu wolnofalowego i lepszą zgłaszaną jakość snu. To konkretny, wczesny sygnał regeneracji snu.';

  @override
  String get benzoMilestone60Title => '8 tygodni: skupienie i równowaga';

  @override
  String get benzoMilestone60Description =>
      'W 8-tygodniowym badaniu starszych osób długo stosujących nasenne benzodiazepiny uczestnicy, którzy ukończyli stopniowe odstawianie, uzyskali lepsze wyniki pamięci bezpośredniej, uwagi, języka i stabilności ciała. To mierzalna poprawa funkcjonowania w dzień.';

  @override
  String get benzoMilestone90Title => '3 miesiące: szybciej, mniej sedacji';

  @override
  String get benzoMilestone90Description =>
      'Dwanaście tygodni po zakończeniu stopniowego odstawiania osoby długo stosujące benzodiazepiny, którym udało się je odstawić, szybciej wykonywały zadania poznawcze na czas i zgłaszały mniejszą sedację psychiczną i fizyczną niż osoby nadal przyjmujące benzodiazepiny. To mierzalna poprawa funkcjonowania w ciągu dnia.';

  @override
  String get benzoMilestone180Title => 'Myślenie i pamięć: poprawa';

  @override
  String get benzoMilestone180Description =>
      'Po sześciu miesiącach pamięć i uwaga wykazują mierzalną poprawę. Badania pokazują regenerację wielu funkcji poznawczych, a postęp może trwać także po tym okresie.';

  @override
  String get benzoMilestone365Title => 'Rok regeneracji';

  @override
  String get benzoMilestone365Description =>
      'Po roku widać znaczną poprawę samopoczucia psychicznego i fizycznego. Wiele osób zgłasza mniej lęku, lepszy sen i lepszy ogólny stan zdrowia niż podczas długotrwałego stosowania benzodiazepin. Regeneracja nadal trwa.';

  @override
  String get benzoMilestone540Title => 'Dalsza regeneracja mózgu';

  @override
  String get benzoMilestone540Description =>
      'Po 18 miesiącach pamięć, uwaga i jasność myślenia nadal się poprawiają. Układ GABA miał już dużo czasu na ponowne dostosowanie, a mózg nadal utrwala zdrowsze wzorce.';

  @override
  String get benzoMilestone730Title => 'Dwa lata: duży postęp';

  @override
  String get benzoMilestone730Description =>
      'Dwa lata oznaczają znaczny postęp. U większości osób myślenie jest znacznie jaśniejsze, emocje bardziej stabilne, a jakość życia dużo lepsza niż podczas długotrwałego stosowania benzodiazepin.';

  @override
  String get benzoMilestone1095Title => 'Trzy lata: trwała regeneracja';

  @override
  String get benzoMilestone1095Description =>
      'Po trzech latach długi okres odstawienia jest dla większości osób daleko w przeszłości. Sen, nastrój, pamięć i uwaga miały lata na regenerację, a codzienne życie jest zwykle znacznie lepsze niż podczas długotrwałego stosowania.';

  @override
  String get benzoMilestone1460Title => 'Cztery lata: Trwały postęp';

  @override
  String get benzoMilestone1460Description =>
      'Cztery lata bez benzodiazepin to długi odcinek zdrowienia budowany dzień po dniu. Ponieważ tempo zdrowienia jest różne, ta rocznica celebruje wzmocnioną stabilność, nawyki i odporność bez udawania, że istnieje jedna meta dla wszystkich.';

  @override
  String get benzoMilestone1825Title => 'Pięć lat: Mocne podstawy';

  @override
  String get benzoMilestone1825Description =>
      'Pięć lat to duże długoterminowe osiągnięcie. Zdrowienie nie ma jednego harmonogramu, ale pięć lat trwałej zmiany oznacza tysiące dni praktyki, wsparcia i życia budowanego poza benzodiazepinami.';

  @override
  String get addictionMeth => 'Meta';

  @override
  String get addictionBenzos => 'Benzodiazepiny';

  @override
  String get methPageTitle => 'Odzyskiwanie mety';

  @override
  String get methHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get methHeaderNotStarted => 'Rzuć szkło.';

  @override
  String get methSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get methSubtitleNotStarted => 'Wolność jest w twoim zasięgu.';

  @override
  String get methMilestone1Title => 'Pierwsze 24 h - początek zjazdu';

  @override
  String get methMilestone1Description =>
      'Początkowy zjazd przynosi głębokie zmęczenie i większy apetyt, gdy organizm zaczyna się regenerować. Może pojawić się obniżony nastrój i potrzeba długiego snu, kiedy ciało stabilizuje się po silnej stymulacji.';

  @override
  String get methMilestone3Title => 'Dzień 3 - szczyt odstawienia';

  @override
  String get methMilestone3Description =>
      'W tym okresie głód metamfetaminy może wyraźnie się nasilić, gdy organizm się przystosowuje. W porównaniu z fazą zjazdu możesz mieć więcej energii, co czasem sprawia, że chęć użycia jest silniejsza. To ważny moment na zapobieganie nawrotowi i korzystanie ze wsparcia.';

  @override
  String get methMilestone7Title => 'Tydzień - objawy fizyczne słabną';

  @override
  String get methMilestone7Description =>
      'Ostre objawy odstawienia zaczynają ustępować, choć trudności psychiczne mogą się utrzymywać. Sen stopniowo się normalizuje, a dyskomfort fizyczny maleje. To przejście z ostrej do podostrej fazy odstawienia.';

  @override
  String get methMilestone30Title => 'Miesiąc - rośnie stabilność';

  @override
  String get methMilestone30Description =>
      'Organizm nadal się regeneruje, a głód metamfetaminy zaczyna słabnąć. Wraz z ponownym równoważeniem neurochemii rosną energia i stabilność nastroju. Wciąż jednak mogą pojawiać się trudniejsze chwile.';

  @override
  String get methMilestone90Title => '3 miesiące - mózg się regeneruje';

  @override
  String get methMilestone90Description =>
      'Mózg aktywnie się regeneruje. Uwaga, pamięć i podejmowanie decyzji mogą się poprawiać, gdy układ nagrody zbliża się do bardziej prawidłowego funkcjonowania.';

  @override
  String get methMilestone180Title => '6 miesięcy - regeneracja serca';

  @override
  String get methMilestone180Description =>
      'Po odstawieniu metamfetaminy czynność serca może wykazywać mierzalną poprawę. Badania wskazują, że w tym okresie funkcja serca może znacznie się poprawiać, zwłaszcza przy wsparciu medycznym. Ciśnienie i rytm serca mogą nadal się stabilizować.';

  @override
  String get methMilestone365Title => 'Rok - duża poprawa pracy mózgu';

  @override
  String get methMilestone365Description =>
      'Po roku układ dopaminowy wykonał dużą część pracy naprawczej. Codzienne przyjemności mogą znów dawać więcej satysfakcji, a nastrój, pamięć i podejmowanie decyzji są wyraźnie lepsze.';

  @override
  String get methMilestone420Title => '14 miesięcy - powrót dopaminy';

  @override
  String get methMilestone420Description =>
      'Obrazowanie mózgu pokazuje, że białka wychwytujące dopaminę zbliżają się na tym etapie do poziomów obserwowanych u zdrowych osób. Pamięć, motywacja i zdolność czerpania przyjemności z codziennych zajęć mogą nadal się poprawiać.';

  @override
  String get methMilestone730Title => '2 lata - trwała poprawa';

  @override
  String get methMilestone730Description =>
      'Dwa lata bez metamfetaminy dają mózgowi dużo czasu na dalszą regenerację. Uwaga, nastrój, pamięć i codzienna jakość życia mogą nadal się poprawiać.';

