  String get nitrousOxideHeaderNotStarted => 'Gotowy do startu?';

  @override
  String get nitrousOxideSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get nitrousOxideSubtitleNotStarted =>
      'Zobacz, co pozytywne zmiany czekają na Ciebie';

  @override
  String get nitrousOxideMilestone1Title => 'Pierwsze 24 h – gaz usunięty';

  @override
  String get nitrousOxideMilestone1Description =>
      'Gaz opuszcza organizm w ciągu kilku minut, ale regeneracja trwa dłużej. Zawroty głowy ustępują, bóle głowy słabną, a mózg zaczyna dostosowywać się bez szybkiego dopaminowego bodźca. Regeneracja związana z B12 zaczyna się teraz.';

  @override
  String get nitrousOxideMilestone3Title => 'Dzień 3 – bez zespołu odstawienia';

  @override
  String get nitrousOxideMilestone3Description =>
      'Dobra wiadomość: podtlenek azotu nie powoduje fizycznego zespołu odstawiennego. Odczuwane impulsy mają podłoże psychologiczne – wynikają z nawyku i skojarzeń, a nie z tego, że organizm potrzebuje substancji. Dzięki temu można nad nimi pracować.';

  @override
  String get nitrousOxideMilestone7Title => 'Tydzień – poziom B12 rośnie';

  @override
  String get nitrousOxideMilestone7Description =>
      'Minął tydzień bez kolejnej ekspozycji, która unieczynnia B12. Jeśli rozpoczęła się suplementacja, poziom witaminy może już rosnąć. Energia, nastrój i koncentracja są związane z B12, więc pierwsze zmiany mogą być odczuwalne.';

  @override
  String get nitrousOxideMilestone14Title =>
      'Dwa tygodnie – nerwy się regenerują';

  @override
  String get nitrousOxideMilestone14Description =>
      'B12 jest potrzebna do utrzymania ochronnej osłonki włókien nerwowych. Po dwóch tygodniach proces regeneracji trwa. Mrowienie lub drętwienie może stopniowo ustępować – układ nerwowy ma czas na naprawę.';

  @override
  String get nitrousOxideMilestone30Title => 'Miesiąc – wraca energia';

  @override
  String get nitrousOxideMilestone30Description =>
      'B12 odgrywa ważną rolę w produkcji czerwonych krwinek, a więc także w dostarczaniu tlenu do komórek. Miesiąc regeneracji i ewentualnej suplementacji może oznaczać więcej energii, jaśniejsze myślenie i stabilniejszy nastrój.';

  @override
  String get nitrousOxideMilestone90Title =>
      'Trzy miesiące – regeneracja nerwów';

  @override
  String get nitrousOxideMilestone90Description =>
      'Trzy miesiące bez kolejnego unieczynniania B12 oznaczają trzy miesiące na regenerację nerwów. Układ nerwowy potrafi się regenerować; u osób leczonych odpowiednio wcześnie często obserwuje się wyraźną poprawę mrowienia, osłabienia i problemów z koncentracją.';

  @override
  String get nitrousOxideMilestone365Title => 'Rok – trwała ochrona zdrowia';

  @override
  String get nitrousOxideMilestone365Description =>
      'Pełny rok bez podtlenku azotu. Zapasy B12 zostały odbudowane, układ nerwowy miał rok na regenerację, a ryzyko sercowo-naczyniowe związane z podwyższoną homocysteiną ustąpiło. Organizm znów działa bez wpływu tej substancji.';

  @override
  String get addictionCocaine => 'Kokaina';

  @override
  String get addictionAdderall => 'Adderall';

  @override
  String get cocainePageTitle => 'Kokaina';

  @override
  String get cocaineHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get cocaineHeaderNotStarted => 'Gotowy do startu?';

  @override
  String get cocaineSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get cocaineSubtitleNotStarted =>
      'Zobacz, co pozytywne zmiany czekają na Ciebie';

  @override
  String get cocaineMilestone1Title => 'Pierwsze 24 godziny: Początek';

  @override
  String get cocaineMilestone1Description =>
      'Organizm zaczyna się przystosowywać, gdy poziom dopaminy zaczyna się stabilizować. Mogą pojawić się zmęczenie, wahania nastroju i silny głód kokainy, ale układ sercowo-naczyniowy już zaczyna się regenerować.';

  @override
  String get cocaineMilestone3Title => 'Dzień 3: Najtrudniejszy etap';

  @override
  String get cocaineMilestone3Description =>
      'Objawy odstawienia często osiągają w tym czasie największe nasilenie. Mogą wystąpić silny głód kokainy, drażliwość, lęk i wyczerpanie. To przejściowe — mózg pracuje nad odzyskaniem równowagi.';

  @override
  String get cocaineMilestone7Title => 'Tydzień: Początek regeneracji';

  @override
  String get cocaineMilestone7Description =>
      'Najsilniejsze objawy fizyczne zaczynają ustępować. Tętno i ciśnienie krwi stabilizują się. Psychiczny głód kokainy może nadal się pojawiać, ale organizm się regeneruje.';

  @override
  String get cocaineMilestone14Title => 'Dwa tygodnie: Więcej stabilności';

  @override
  String get cocaineMilestone14Description =>
      'Wiele osób zaczyna czuć większą stabilność emocjonalną. Poziom energii się poprawia, a ostre objawy odstawienia słabną. Zdrowie układu sercowo-naczyniowego nadal się poprawia.';

  @override
  String get cocaineMilestone60Title => 'Dwa miesiące: Lepszy sen i nastrój';

  @override
  String get cocaineMilestone60Description =>
      'Jakość snu jest wyraźnie lepsza, gdy chemia mózgu stopniowo wraca do równowagi. Możesz czuć się bardziej wypoczęty i mieć stabilniejszy nastrój w ciągu dnia.';

  @override
  String get cocaineMilestone90Title => 'Trzy miesiące: Regeneracja mózgu';

  @override
  String get cocaineMilestone90Description =>
      'Układ dopaminowy się regeneruje. Koncentracja, podejmowanie decyzji i regulacja emocji wyraźnie się poprawiają, a myślenie staje się bardziej przejrzyste.';

  @override
  String get cocaineMilestone180Title => 'Sześć miesięcy: Jaśniejsze myślenie';

  @override
  String get cocaineMilestone180Description =>
      'Badania obrazowe pokazują poprawę w przedniej części mózgu, która wspiera planowanie i samokontrolę. Pamięć, kontrola impulsów i jasność myślenia nadal się wzmacniają.';

  @override
  String get cocaineMilestone365Title => 'Rok: Zdrowie sercowo-naczyniowe';

  @override
  String get cocaineMilestone365Description =>
      'Serce i układ sercowo-naczyniowy znacznie się zregenerowały. Ciśnienie krwi i tętno wróciły do normy. Ryzyko zawału i udaru istotnie się zmniejszyło. Organizm nadal się regeneruje.';

  @override
  String get cocaineMilestone730Title => 'Dwa lata: Trwałe zdrowienie';

  @override
  String get cocaineMilestone730Description =>
      'Regeneracja mózgu trwa, a pamięć, koncentracja i regulacja emocji nadal się poprawiają. Szlaki nerwowe uległy znacznej reorganizacji, wspierając zdrowsze wzorce zachowania i lepsze ogólne samopoczucie.';

  @override
  String get cocaineMilestone1095Title => 'Trzy lata: Mocny fundament';

  @override
  String get cocaineMilestone1095Description =>
      'Trzy lata bez kokainy to trwały postęp. Rutyny, relacje i sposoby radzenia sobie miały lata, by się umocnić i stworzyć silniejszy fundament zdrowienia.';

  @override
  String get cocaineMilestone1460Title => 'Cztery lata: Trwały rozpęd';

  @override
  String get cocaineMilestone1460Description =>
      'Cztery lata to trwały rozpęd. Kolejny rok życia bez kokainy wzmocnił nawyki i wsparcie, które pomagają utrzymać zdrowienie.';

  @override
  String get cocaineMilestone1825Title => 'Pięć lat: Utrwalona zmiana';

  @override
  String get cocaineMilestone1825Description =>
      'Pięć lat to wielka rocznica. Pół dekady konsekwencji zbudowało życie coraz bardziej kształtowane przez twoje wartości, relacje i cele, a nie przez kokainę.';

