  @override
  String get alcoholMilestone1Title => 'Jakość snu zaczyna się poprawiać';

  @override
  String get alcoholMilestone1Description =>
      'Cykle snu REM zaczynają się normalizować już pierwszego dnia. Alkohol może początkowo ułatwiać zasypianie, ale przez całą noc zaburza sen głęboki i REM, przez co sen staje się pofragmentowany.';

  @override
  String get alcoholMilestone3Title => 'Dzień 3: Szczyt ostrego odstawienia';

  @override
  String get alcoholMilestone3Description =>
      'Trzy dni to ogromny kamień milowy: objawy odstawienia alkoholu często osiągają szczyt około 72. godziny. Drżenie, bezsenność, pobudzenie, poty, szybkie tętno i wysokie ciśnienie mogą być teraz najsilniejsze. Ciężkie odstawienie może pojawić się także później, w tym majaczenie między 3. a 8. dniem po odstawieniu.';

  @override
  String get alcoholMilestone7Title => 'Układ odpornościowy się wzmacnia';

  @override
  String get alcoholMilestone7Description =>
      'Białe krwinki odzyskują swoją funkcję. Nawet jeden epizod intensywnego picia może osłabić odporność nawet na 24 godziny, a przewlekłe picie znacznie zmniejsza zdolność organizmu do zwalczania infekcji.';

  @override
  String get alcoholMilestone14Title => 'Zaczyna się odbudowa objętości mózgu';

  @override
  String get alcoholMilestone14Description =>
      'Objętość mózgu zaczyna się odbudowywać w ciągu pierwszych dwóch tygodni. Myślenie i pamięć nadal poprawiają się w kolejnych miesiącach.';

  @override
  String get alcoholMilestone30Title => 'Ciśnienie krwi się normalizuje';

  @override
  String get alcoholMilestone30Description =>
      'Układ sercowo-naczyniowy wykazuje wyraźną poprawę. Regularne picie alkoholu podnosi ciśnienie, ale około miesiąca abstynencji może pomóc przywrócić je do zdrowszych wartości.';

  @override
  String get alcoholMilestone60Title => 'Funkcja wątroby się poprawia';

  @override
  String get alcoholMilestone60Description =>
      'Funkcja wątroby poprawia się w sposób mierzalny. Ten narząd ma dużą zdolność regeneracji po uszkodzeniach związanych z alkoholem, a enzymy wątrobowe i nagromadzenie tłuszczu mogą poprawiać się w ciągu około dwóch miesięcy abstynencji.';

  @override
  String get alcoholMilestone90Title =>
      'Myślenie i pamięć wyraźnie się poprawiają';

  @override
  String get alcoholMilestone90Description =>
      'Pierwsze trzy miesiące przynoszą duże postępy w pamięci, koncentracji i podejmowaniu decyzji, a poprawa trwa przez kolejne miesiące.';

  @override
  String get alcoholMilestone180Title =>
      'Mózg nadal odzyskuje objętość i funkcje';

  @override
  String get alcoholMilestone180Description =>
      'Sześć miesięcy trzeźwości daje mózgowi dłuższy czas na regenerację. Objętość mózgu i zdolności poznawcze nadal się poprawiają.';

  @override
  String get alcoholMilestone365Title => 'Ryzyko raka może zacząć spadać';

  @override
  String get alcoholMilestone365Description =>
      'Rok abstynencji może zacząć obniżać ryzyko nowotworów. Alkohol wyraźnie zwiększa ryzyko kilku rodzajów raka, w tym wątroby, piersi, jelita grubego i odbytnicy oraz przełyku, ale badania nad tempem spadku ryzyka nadal się rozwijają i różnią się zależnie od typu nowotworu.';

  @override
  String get smokingMilestone1Title => 'Tlenek węgla znika z krwi';

  @override
  String get smokingMilestone1Description =>
      'Twoja krew znów przenosi więcej tlenu! W ciągu 24 godzin poziom tlenku węgla spada do normy, a poziom tlenu rośnie. Serce nie musi już pracować tak ciężko, by pompować po organizmie krew obciążoną tlenkiem węgla.';

  @override
  String get smokingMilestone3Title => 'Szczyt odstawienia nikotyny';

  @override
  String get smokingMilestone3Description =>
      'Odstawienie nikotyny jest teraz najbardziej dokuczliwe, ale dajesz radę! Nikotyna opuściła już organizm. Głód może być teraz najsilniejszy, lecz każda przetrwana fala przybliża Cię do wolności.';

  @override
  String get smokingMilestone7Title => 'Smak i węch wyraźnie wracają';

  @override
  String get smokingMilestone7Description =>
      'Jedzenie znów zaczyna być przygodą! Palenie uszkadza kubki smakowe i receptory węchowe. Po tygodniu odkrywasz na nowo smaki, o których niemal udało Ci się zapomnieć. Czas znów naprawdę cieszyć się jedzeniem!';

  @override
  String get smokingMilestone14Title => 'Lepsze krążenie i chodzenie';

  @override
  String get smokingMilestone14Description =>
      'Twoje nogi czują różnicę przy każdym kroku! Krążenie krwi wyraźnie się poprawia, więc chodzenie i ćwiczenia stają się zauważalnie łatwiejsze. Nawet schody wyglądają już mniej groźnie.';

  @override
  String get smokingMilestone30Title => 'Lepsza funkcja płuc';

  @override
  String get smokingMilestone30Description =>
      'Twoje płuca wracają do formy! Rzęski odrastają i skuteczniej usuwają śluz, smołę oraz inne zanieczyszczenia. Funkcja płuc się poprawia, a uporczywy kaszel palacza zaczyna ustępować.';

  @override
  String get smokingMilestone90Title => 'Ryzyko zawału wyraźnie spada';

  @override
  String get smokingMilestone90Description =>
      'Twoje serce ma powody do świętowania! Po trzech miesiącach bez papierosów ryzyko sercowo-naczyniowe już znacząco spadło. Układ sercowo-naczyniowy regeneruje się szybciej, niż może się wydawać.';

  @override
  String get smokingMilestone180Title => 'Odporność płuc wraca';

  @override
  String get smokingMilestone180Description =>
      'Sześć miesięcy bez palenia to prawdziwy sukces dla odporności płuc. W badaniu okołooperacyjnym odpowiedź przeciwbakteryjna makrofagów pęcherzykowych po 3–12 miesiącach bez papierosów była bliższa wzorcowi osób nigdy niepalących niż po dwóch miesiącach. Pierwsza linia obrony płuc miała miesiące na regenerację.';

  @override
  String get smokingMilestone365Title => 'Ryzyko udaru wyraźnie spada';

  @override
  String get smokingMilestone365Description =>
      'Pełny rok wolności! Ryzyko udaru już wyraźnie spadło, a naczynia krwionośne nadal się regenerują. Dajesz swojemu mózgowi lepsze krążenie i coraz większą ochronę.';

  @override
  String get smokingMilestone730Title => 'Dwa lata: serce zyskuje';

  @override
  String get smokingMilestone730Description =>
      'Dwa lata bez palenia to duży sukces dla serca i naczyń. CDC podaje, że ryzyko zawału wyraźnie spada w ciągu 1–2 lat po rzuceniu palenia, a ryzyko choroby wieńcowej nadal maleje w dłuższej perspektywie.';

  @override
  String get smokingMilestone1095Title => 'Trzy lata: ryzyko serca spada';

  @override
  String get smokingMilestone1095Description =>
      'Trzy lata bez palenia rozpoczynają wskazany przez CDC okres 3–6 lat, w którym dodatkowe ryzyko choroby wieńcowej spada o połowę. Spadek rozwija się w całym tym okresie, a nie jednego dnia.';

  @override
  String get smokingMilestone1460Title => 'Cztery lata: serce dalej zyskuje';

  @override
  String get smokingMilestone1460Description =>
      'Cztery lata bez palenia mieszczą się w okresie 3–6 lat wskazanym przez CDC, w którym dodatkowe ryzyko choroby wieńcowej spada o połowę. Długoterminowe korzyści sercowo-naczyniowe nadal rosną.';

  @override
  String get smokingMilestone1825Title => '5–10 lat: spada ryzyko nowotworów';

  @override
  String get smokingMilestone1825Description =>
      'Pięć lat zwycięstwa! Wchodzisz w okres 5–10 lat, w którym dodatkowe ryzyko nowotworów jamy ustnej, gardła i krtani spada o połowę, a ryzyko udaru nadal maleje. Długoterminowe korzyści właśnie nabierają rozpędu.';

  @override
  String get marijuanaMilestone1Title => 'Początek objawów odstawienia';

  @override
  String get marijuanaMilestone1Description =>
      'Twój mózg przystosowuje się do życia bez THC. W ciągu 24–48 godzin mogą pojawić się drażliwość, niepokój lub trudności ze snem. To normalne: receptory kannabinoidowe zaczynają wracać do równowagi.';

  @override
  String get marijuanaMilestone3Title => 'Szczyt objawów fizycznych';

  @override
  String get marijuanaMilestone3Description =>
      'To jeden z najtrudniejszych momentów, ale odtąd zwykle zaczyna być łatwiej. Między 2. a 6. dniem często przypada szczyt objawów odstawienia, takich jak ból głowy, pocenie się i zmiany nastroju. Organizm intensywnie odzyskuje równowagę.';

  @override
  String get marijuanaMilestone7Title => 'Sen zaczyna się poprawiać';

  @override
  String get marijuanaMilestone7Description =>
      'Po tygodniu bez konopi naturalny rytm snu zaczyna się normalizować. Pojawia się odbicie snu REM, dlatego sny mogą być bardziej wyraziste, a jakość odpoczynku stopniowo się poprawia.';

  @override
  String get marijuanaMilestone14Title => 'Koniec ostrego odstawienia';

  @override
  String get marijuanaMilestone14Description =>
      'Największa burza mija. Po dwóch tygodniach większość fizycznych objawów odstawienia wyraźnie słabnie. Nastrój zaczyna się stabilizować, a codzienne funkcjonowanie staje się łatwiejsze. Najtrudniejszy etap jest za Tobą.';

  @override
  String get marijuanaMilestone30Title => 'Pamięć zaczyna się poprawiać';

  @override
  String get marijuanaMilestone30Description =>
      'Mgła poznawcza zaczyna się rozwiewać. Badania pokazują poprawę uczenia werbalnego i pamięci po zaprzestaniu używania konopi. Hipokamp, ważny dla tworzenia wspomnień, zaczyna funkcjonować lepiej.';

  @override
  String get marijuanaMilestone60Title => 'Koncentracja się wyostrza';

  @override
  String get marijuanaMilestone60Description =>
      'Po dwóch miesiącach bez konopi zdolność skupienia i utrzymania uwagi może być wyraźnie lepsza. Zadania w pracy i nauka stają się łatwiejsze do opanowania.';

  @override
  String get marijuanaMilestone90Title => 'Wraca stabilność nastroju';

  @override
  String get marijuanaMilestone90Description =>
      'Trzy miesiące bez konopi mogą oznaczać stabilniejszy nastrój, mniej lęku i lepsze radzenie sobie ze stresem. Stan emocjonalny stopniowo układa się w zdrowszy rytm.';

  @override
  String get marijuanaMilestone180Title => 'Wracają planowanie i decyzje';

  @override
  String get marijuanaMilestone180Description =>
      'Po sześciu miesiącach bez konopi planowanie, podejmowanie decyzji i rozwiązywanie problemów mogą być wyraźnie sprawniejsze.';

  @override
  String get marijuanaMilestone365Title => 'Odbudowa struktur pamięciowych';

  @override
  String get marijuanaMilestone365Description =>
      'Rok bez konopi daje obszarom mózgu związanym z pamięcią dużo czasu na regenerację. Poprawa uczenia się i pamięci może stać się częścią nowej codzienności.';

  @override
  String get opioidMilestone1Title => 'Rozpoczyna się ostry zespół odstawienny';

  @override
  String get opioidMilestone1Description =>
      'Najtrudniejszy etap zaczyna się teraz, ale nie jesteś sam. Ostre objawy odstawienne zwykle nasilają się w pierwszych 24–72 godzinach. To początek procesu, w którym organizm odzyskuje równowagę. W tej fazie bardzo ważne jest profesjonalne wsparcie medyczne.';

  @override
  String get opioidMilestone7Title => 'Objawy fizyczne zaczynają słabnąć';

  @override
  String get opioidMilestone7Description =>
      'Najgorsza fala jest już za Tobą! Najsilniejsze fizyczne objawy odstawienne zwykle osiągają szczyt około 3.–5. dnia i do 7. dnia zaczynają słabnąć. Organizm intensywnie pracuje nad odzyskaniem naturalnej równowagi.';

  @override
  String get opioidMilestone14Title => 'Sen zaczyna się poprawiać';

  @override
  String get opioidMilestone14Description =>
