  @override
  String get nicotinePouchesMilestone1Description =>
      'Objawy odstawienia nikotyny mogą zacząć się 4–24 godziny po ostatniej saszetce. Pierwszy dzień bez saszetek to prawdziwy biologiczny kamień milowy — organizm już przystosowuje się do życia bez kolejnych dawek nikotyny.';

  @override
  String get nicotinePouchesMilestone3Title => 'Odstawienie osiąga szczyt';

  @override
  String get nicotinePouchesMilestone3Description =>
      'Odstawienie nikotyny zwykle osiąga szczyt około trzeciego dnia, a potem słabnie przez kolejne 3–4 tygodnie. Jesteś na szczycie wzgórza — od tego miejsca ogólny trend prowadzi w dół.';

  @override
  String get nicotinePouchesReferenceDay1 =>
      'Dzień pierwszy: zaczyna się odstawienie nikotyny\n\nŹródło: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nPrzegląd dotyczący odstawienia po przewlekłym używaniu produktów zawierających nikotynę podaje, że zespół odstawienny może rozpocząć się 4–24 godziny po zaprzestaniu używania. Dlatego pierwszy dzień bez saszetek jest rzeczywistym fizjologicznym kamieniem milowym.\n\nCo dalej\nObjawy zwykle osiągają szczyt około 3. dnia, a następnie słabną przez kolejne 3–4 tygodnie. Nasilenie odstawienia zależy także od sposobu przyjmowania nikotyny, więc doświadczenie może różnić się między osobami.';

  @override
  String get nicotinePouchesReferenceDay3 =>
      'Dzień trzeci: szczyt odstawienia nikotyny\n\nŹródło: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nPrzegląd wskazuje, że typowy szczyt odstawienia nikotyny przypada około trzeciego dnia po zaprzestaniu przewlekłego używania nikotyny.\n\nKrzywa od tego miejsca\nPo szczycie objawy zwykle słabną przez kolejne 3–4 tygodnie. Przegląd zaznacza też, że nasilenie zależy od sposobu przyjmowania nikotyny, więc dokładna intensywność jest indywidualna.\n\nTrzeci dzień to ciężko wypracowany kamień milowy: jesteś na szczycie typowej wczesnej krzywej odstawienia.';

  @override
  String get nicotinePouchesMilestone7Title =>
      'Tydzień: odstawienie łagodnieje';

  @override
  String get nicotinePouchesMilestone7Description =>
      'Tydzień bez saszetek nikotynowych oznacza, że typowy szczyt odstawienia około trzeciego dnia jest już za Tobą. Objawy zwykle słabną przez kolejne 3–4 tygodnie — jesteś już na opadającej części krzywej.';

  @override
  String get nicotinePouchesMilestone14Title =>
      'Dwa tygodnie: objawy dalej słabną';

  @override
  String get nicotinePouchesMilestone14Description =>
      'Dwa tygodnie bez saszetek nikotynowych oznaczają, że jesteś już głęboko w 3–4-tygodniowym okresie wygaszania po typowym szczycie około trzeciego dnia. Krzywa nadal opada — to realny proces zdrowienia.';

  @override
  String get nicotinePouchesReferenceDay7 =>
      'Tydzień: odstawienie łagodnieje\n\nŹródło: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nPrzegląd podaje, że odstawienie po przewlekłym używaniu produktów zawierających nikotynę zaczyna się 4–24 godziny po zaprzestaniu, osiąga szczyt około 3. dnia, a następnie objawy słabną przez kolejne 3–4 tygodnie.\n\nPrawdziwe zwycięstwo po tygodniu\nPo tygodniu jesteś już kilka dni za typowym szczytem i w fazie wygaszania objawów. Przegląd zaznacza też, że nasilenie odstawienia zależy od sposobu przyjmowania nikotyny, więc różni się między osobami.\n\nTydzień bez saszetek oznacza, że najbardziej stromy odcinek typowej wczesnej krzywej odstawienia jest już za Tobą.';

  @override
  String get nicotinePouchesReferenceDay14 =>
      'Dwa tygodnie: objawy dalej słabną\n\nŹródło: McLaughlin, Dani & De Biasi — Nicotine Withdrawal\n\nPrzegląd umieszcza typowy szczyt odstawienia nikotyny około 3. dnia i podaje, że objawy słabną przez kolejne 3–4 tygodnie.\n\nGłęboko w fazie wygaszania\nPo dwóch tygodniach jesteś już wyraźnie w okresie wygaszania po szczycie. Przegląd dotyczy przewlekłego używania produktów zawierających nikotynę i zaznacza, że nasilenie odstawienia różni się zależnie od sposobu przyjmowania nikotyny.\n\nDwa tygodnie bez saszetek to konkretny punkt na opadającej krzywej: typowe objawy odstawienia nadal słabną.';

  @override
  String get nicotinePouchesMilestone730Title => 'Dwa lata: siła bez saszetek';

  @override
  String get nicotinePouchesMilestone730Description =>
      'Pełne dwa lata bez saszetek nikotynowych. Badania nie potwierdzają szczególnego progu zdrowienia po dwóch latach, więc ten kamień milowy świętuje dwa lata bez powtarzanej ekspozycji na nikotynę z saszetek i zmianę, którą udało się utrzymać.';

  @override
  String get nicotinePouchesReferenceDay730 =>
      'Dwa lata: siła bez saszetek\n\nŹródło: Rungraungrayabkul i wsp. (2024), przegląd systematyczny dotyczący saszetek nikotynowych i zdrowia jamy ustnej\n\nPrzegląd znalazł tylko trzy badania z udziałem ludzi, łącznie 190 osób, a wszystkie oceniono jako obarczone wysokim ryzykiem błędu systematycznego. Nie ustalono progu zdrowienia dokładnie po dwóch latach od odstawienia.\n\nDwa lata bez saszetek to mimo wszystko duży kamień milowy trwałej zmiany. Ten wpis świętuje osiągnięcie bez wymyślania medycznego harmonogramu.';

  @override
  String get nicotinePouchesMilestone1095Title => 'Trzy lata: wolność trwa';

  @override
  String get nicotinePouchesMilestone1095Description =>
      'Trzy lata bez saszetek to trwałe zwycięstwo. Długoterminowe skutki saszetek nikotynowych są nadal badane, więc uczciwy nagłówek jest prosty: trzy lata trwałej wolności od nikotyny z saszetek.';

  @override
  String get nicotinePouchesReferenceDay1095 =>
      'Trzy lata: wolność trwa\n\nŹródło: CDC — Saszetki nikotynowe\n\nCDC podaje, że potrzeba więcej badań, aby zrozumieć krótko- i długoterminowe skutki zdrowotne saszetek nikotynowych. Nie wskazuje szczególnej zmiany medycznej dokładnie trzy lata po odstawieniu.\n\nTrzy lata bez saszetek warto świętować za to, czym są: trzema latami utrzymanej wolności od nikotyny z saszetek.';

  @override
  String get nicotinePouchesMilestone1460Title => 'Cztery lata: trwała zmiana';

  @override
  String get nicotinePouchesMilestone1460Description =>
      'Cztery lata bez saszetek pokazują prawdziwą konsekwencję. Nie potwierdzono żadnej szczególnej zmiany medycznej zachodzącej dokładnie po czterech latach, ale jest bardzo realne osiągnięcie: cztery lata bez powrotu do nawyku używania saszetek.';

  @override
  String get nicotinePouchesReferenceDay1460 =>
      'Cztery lata: trwała zmiana\n\nŹródło: Rungraungrayabkul i wsp. (2024), przegląd systematyczny dotyczący saszetek nikotynowych i zdrowia jamy ustnej\n\nPrzegląd stwierdza, że dowody dotyczące krótko- i długoterminowych skutków dla zdrowia jamy ustnej pozostają ograniczone i potrzebne są dalsze badania. Nie potwierdza, że dokładnie po czterech latach u każdego następuje szczególny etap zdrowienia.\n\nCztery lata bez saszetek to kamień milowy trwałej zmiany, bez potrzeby niepotwierdzonej obietnicy medycznej.';

