      'W randomizowanym badaniu ACT dotyczącym problematycznego używania pornografii po 12 sesjach odnotowano duże spadki oglądania, które w znacznej części utrzymywały się po trzech miesiącach. Trwała zmiana jest realna, szczególnie gdy budujesz konkretne umiejętności zamiast polegać wyłącznie na sile woli.';

  @override
