  @override
  String get customMilestone14Title => 'Wczesna stabilizacja zdrowienia';

  @override
  String get customMilestone14Description =>
      'Umysł staje się jaśniejszy. Dwa tygodnie zdrowienia często przynoszą większą jasność myślenia i mniejszy głód substancji, gdy mózg zaczyna przystosowywać się do funkcjonowania bez niej.';

  @override
  String get customMilestone30Title => 'Miesiąc za Tobą';

  @override
  String get customMilestone30Description =>
      'To duże zwycięstwo. Trzydzieści dni zdrowienia oznacza wyraźny postęp. U wielu osób w tym czasie nadal poprawiają się sen, nastrój i poziom energii.';

  @override
  String get customMilestone90Title => 'Trzy miesiące zdrowienia';

  @override
  String get customMilestone90Description =>
      'Twoja konsekwencja przynosi efekty. Trzy miesiące zdrowienia to znaczące osiągnięcie. Objawy po ostrej fazie odstawienia zwykle zaczynają słabnąć, a wiele osób znów zaczyna czuć się sobą.';

  @override
  String get customMilestone180Title => 'Sześć miesięcy zdrowienia';

  @override
  String get customMilestone180Description =>
      'Budujesz trwałą zmianę. Sześć miesięcy zdrowienia często przynosi dalszą poprawę zdrowia fizycznego, stabilności emocjonalnej i ogólnej jakości życia, gdy organizm nadal się regeneruje.';

  @override
  String get customMilestone365Title => 'Rok zdrowienia';

  @override
  String get customMilestone365Description =>
      'To ogromne osiągnięcie. Rok zdrowienia jest ważnym życiowym kamieniem milowym. Wiele osób zauważa do tego czasu znaczną poprawę zdrowia fizycznego, relacji i ogólnego samopoczucia.';

  @override
  String get customMilestone730Title => 'Dwa lata trwałego zdrowienia';

  @override
  String get customMilestone730Description =>
      'Udało Ci się zbudować nowe życie. Dwa lata zdrowienia pokazują niezwykłą wytrwałość i zaangażowanie. Długotrwałe zdrowienie często wiąże się z głębokimi pozytywnymi zmianami w wielu obszarach życia i wyraźnie niższym ryzykiem nawrotu.';

  @override
  String get customMilestone1095Title => 'Trzy lata: mocne korzenie';

  @override
  String get customMilestone1095Description =>
      'Trzy lata zdrowienia to trwały postęp. Rutyny, relacje i sposoby radzenia sobie miały lata, by się umocnić. Warto nadal rozwijać to, co działa.';

  @override
  String get customMilestone1460Title => 'Cztery lata: trwała zmiana';

  @override
  String get customMilestone1460Description =>
      'Cztery lata pokazują trwałą zmianę. Wybory i wsparcie, które pozwoliły dojść tak daleko, są już częścią codzienności. Warto je chronić i iść dalej.';

  @override
  String get customMilestone1825Title => 'Pięć lat: pół dekady';

  @override
  String get customMilestone1825Description =>
      'Pięć lat to pół dekady trwałego postępu. Warto świętować zbudowane życie, umiejętności i sieć wsparcia oraz nadal dbać o rutyny, które pomagają się rozwijać.';

  @override
  String get customReferenceDay1095 =>
      'Trzy lata zdrowienia: mocne korzenie\n\nŹródło: NIDA, Narkotyki, mózg i zachowanie: nauka o uzależnieniu\n\nNIDA opisuje zaburzenia związane z używaniem substancji jako możliwe do leczenia, a zdrowienie jako zaprzestanie używania narkotyków i powrót do produktywnego życia. Nie wyznacza uniwersalnej biologicznej granicy trzech lat dla wszystkich substancji.\n\nTrzy lata to trwałe osiągnięcie. Rutyny, wsparcie i wybory, które doprowadziły do tego miejsca, miały lata, by się zakorzenić.';

  @override
  String get customReferenceDay1460 =>
      'Cztery lata zdrowienia: trwała zmiana\n\nŹródło: NIDA, Narkotyki, mózg i zachowanie: nauka o uzależnieniu\n\nNIDA przedstawia uzależnienie jako stan możliwy do leczenia i skutecznego kontrolowania. Nie określa uniwersalnego czteroletniego punktu końcowego zdrowienia dla każdej substancji ani osoby.\n\nCztery lata pokazują siłę konsekwencji. Warto nadal chronić nawyki, relacje i wsparcie, które pomagają utrzymać zdrowienie.';

  @override
  String get customReferenceDay1825 =>
      'Pięć lat zdrowienia: pół dekady\n\nŹródło: NIDA, Narkotyki, mózg i zachowanie: nauka o uzależnieniu\n\nNIDA wspiera leczenie i zdrowienie oparte na dowodach, ale nie twierdzi, że po pięciu latach każda osoba osiąga ten sam stan biologiczny.\n\nPięć lat to pół dekady trwałego postępu. Warto świętować to, co udało się zbudować, i nadal inwestować w to, co działa.';

  @override
  String get addictionSsri => 'SSRI';

  @override
  String get ssriPageTitle => 'Odzyskiwanie SSRI';

  @override
  String get ssriHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get ssriHeaderNotStarted => 'Korzyści z Tapering Off SSRI';

  @override
  String get ssriSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get ssriSubtitleNotStarted =>
      'Zobaczymy, co się stanie, gdy się odprężysz.';

  @override
  String get ssriMilestone3Title => 'Dzień 3: Szczyt zespołu FINISH';

  @override
  String get ssriMilestone3Description =>
      'Objawy odstawienne często osiągają szczyt około 2.–4. dnia. SSRI zmieniają sposób działania układu serotoninowego, dlatego po odstawieniu mózg potrzebuje czasu na dostosowanie. Mogą pojawić się objawy grypopodobne, zawroty głowy, bezsenność, nudności i tzw. „brain zaps”, czyli krótkie wrażenia elektryczne w głowie. Paroksetyna częściej powoduje silniejsze objawy odstawienne; fluoksetyna utrzymuje się w organizmie dużo dłużej i zwykle przebiega łagodniej.';

  @override
  String get ssriMilestone7Title => 'Tydzień: Ostra faza słabnie';

  @override
  String get ssriMilestone7Description =>
      'Najsilniejsze objawy fizyczne zaczynają ustępować. Mózg dostosowuje sygnalizację serotoninową do funkcjonowania bez leku. Sen i apetyt zaczynają się stabilizować.';

  @override
  String get ssriMilestone14Title => '2 tygodnie: Objawy ustępują';

  @override
  String get ssriMilestone14Description =>
      'Większość ostrych fizycznych objawów odstawiennych wyraźnie się zmniejszyła lub ustąpiła. Brain zaps, nudności i zawroty głowy słabną. Wrażliwość emocjonalna może nadal być podwyższona, gdy układ serotoninowy dalej się dostosowuje.';

  @override
  String get ssriMilestone30Title => '1 mies.: Nastrój i energia stabilne';

  @override
  String get ssriMilestone30Description =>
      'Miesiąc to ważny kamień milowy. Jakość snu się poprawia, poziom energii stabilizuje, a wiele osób zauważa, że nastrój znajduje nową równowagę. Mózg nadal dostosowuje naturalną regulację serotoniny.';

  @override
  String get ssriMilestone90Title => '3 mies.: Punkt zwrotny odstawienia';

  @override
  String get ssriMilestone90Description =>
      'W badaniu ANTLER różnica w objawach odstawienia po przerwaniu długotrwałego leczenia przeciwdepresyjnego była największa po 12 tygodniach, a w późniejszych kontrolach mniejsza. Trzy miesiące są więc wyraźnym punktem zwrotnym w mierzonym przebiegu odstawienia.';

  @override
  String get ssriMilestone180Title => '6 mies.: 65% bez nawrotu';

  @override
  String get ssriMilestone180Description =>
      'W sześciomiesięcznej obserwacji po odstawieniu leków przeciwdepresyjnych u osób w remisji 54 z 83 uczestników z danymi końcowymi — 65% — pozostało w dobrym stanie. Sześć miesięcy to konkretny kamień milowy długoterminowej stabilności.';

  @override
  String get ssriMilestone365Title => 'Rok: ogromny kamień milowy';

  @override
  String get ssriMilestone365Description =>
      'Pełny rok bez leku to ogromny kamień milowy. W badaniu ANTLER wiele osób długo przyjmujących leki przeciwdepresyjne, które je odstawiły, przeszło 52 tygodnie bez nawrotu, choć nawrót był częstszy po odstawieniu niż podczas leczenia podtrzymującego. Jeśli po roku czujesz się dobrze, to realny postęp wart świętowania.';

  @override
  String get settingsShowSsriTracking => 'Pokaż śledzenie SSRI';

  @override
  String get settingsNotifySsri => 'Informuj SSRI o zakończeniu postępu';

  @override
  String get addictionSnri => 'SNRI';

  @override
  String get snriPageTitle => 'Odzyskiwanie SNRI';

  @override
  String get snriHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get snriHeaderNotStarted => 'Korzyści związane z odciąganiem SNRI';

  @override
  String get snriSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get snriSubtitleNotStarted =>
      'Zobaczymy, co się stanie, gdy się odprężysz.';

  @override
  String get snriMilestone3Title => 'Dzień 3: Nasilone odstawienie';

  @override
  String get snriMilestone3Description =>
      'SNRI — szczególnie wenlafaksyna (Effexor) — należą do leków przeciwdepresyjnych związanych z silnymi objawami odstawiennymi. Bardzo krótki okres półtrwania wenlafaksyny (5 godzin) może sprawiać, że objawy są bardziej nasilone niż przy większości SSRI. Objawy FINISH (dolegliwości grypopodobne, bezsenność, nudności, zaburzenia równowagi, zaburzenia czucia i nadmierne pobudzenie) obejmują jednocześnie układ serotoninowy i noradrenergiczny.';

  @override
  String get snriMilestone7Title => 'Tydzień: Dwa układy się dostrajają';

  @override
  String get snriMilestone7Description =>
      'SNRI wpływają na wychwyt zwrotny serotoniny i noradrenaliny. Oba układy dostosowują się jednocześnie. Najsilniejsze objawy fizyczne zaczynają słabnąć, ale podwójny mechanizm działania może sprawić, że adaptacja jest bardziej złożona niż przy samych SSRI.';

  @override
  String get snriMilestone14Title => '2 tygodnie: Objawy fizyczne słabną';

  @override
  String get snriMilestone14Description =>
      'Większość ostrych objawów fizycznych po odstawieniu wyraźnie się zmniejszyła. Brain zaps, nudności i zawroty głowy słabną. Dostosowywanie układu noradrenergicznego może jeszcze powodować niepokój lub wahania ciśnienia, które zwykle ustępują w kolejnych tygodniach.';

  @override
  String get snriMilestone30Title => 'Miesiąc: Noradrenalina stabilna';

  @override
  String get snriMilestone30Description =>
      'Miesiąc to ważny kamień milowy. Układy serotoninowy i noradrenergiczny nadal się równoważą. Sen i poziom energii stabilizują się. Wiele osób zauważa szerszy zakres emocji, gdy ustępuje związane z lekiem stępienie emocjonalne.';

  @override
  String get snriMilestone90Title => '3 miesiące: Typowy okres za Tobą';

  @override
  String get snriMilestone90Description =>
      'Odstawienie SNRI zwykle zaczyna się w ciągu kilku dni i trwa kilka tygodni. Po 90 dniach typowy okres objawów jest już daleko za Tobą — to konkretny kamień milowy zdrowienia.';

  @override
  String get snriMilestone180Title => '6 miesięcy: Adaptacja neurologiczna';

  @override
  String get snriMilestone180Description =>
      'Sześć miesięcy daje układom serotoninowemu i noradrenergicznemu dużo czasu na dalszą adaptację. Oś HPA, na którą SNRI wpływają poprzez noradrenalinę, normalizuje się. Wiele osób na tym etapie zgłasza wyraźnie lepszą odporność na codzienny stres.';

  @override
  String get snriMilestone365Title => '1 rok: Osiągnięta poprawa';

  @override
  String get snriMilestone365Description =>
      'Rok oznacza pełny cykl adaptacji układów serotoninowego i noradrenergicznego. Badania konsekwentnie pokazują, że osoby, które skutecznie odstawiły SNRI pod nadzorem medycznym i przy wsparciu psychologicznym, po roku często utrzymują dobre wyniki.';

  @override
  String get snriMilestone730Title => '2 lata: Pewny grunt';

  @override
  String get snriMilestone730Description =>
      'Dwa lata od zakończenia odstawiania SNRI to powód do świętowania. Przebieg objawów odstawiennych jest różny, więc ta rocznica oznacza trwały postęp, a nie uniwersalny biologiczny termin regeneracji.';

  @override
  String get snriReferenceDay730 =>
      'Dwa lata po SNRI: Znacznik postępu\n\nŹródło: Royal College of Psychiatrists — Odstawianie leków przeciwdepresyjnych\n\nLeków przeciwdepresyjnych zwykle nie należy odstawiać nagle. Tempo powinno być indywidualne; duloksetyna lub wenlafaksyna mogą wymagać wolniejszej redukcji przez wiele miesięcy lub dłużej.\n\nWytyczne nie określają dwuletniego biologicznego progu regeneracji. Ta rocznica świętuje trwały postęp.';

  @override
  String get snriMilestone1095Title => '3 lata: Trwały postęp';

  @override
  String get snriMilestone1095Description =>
      'Trzy lata to znaczący okres życia po odstawieniu. Świętuj nawyki, wsparcie i decyzje, które utrzymały Twój postęp; medycyna nie wyznacza na tę datę szczególnego progu regeneracji.';

  @override
  String get snriReferenceDay1095 =>
      'Trzy lata po SNRI: Postęp, który trwa\n\nŹródło: Royal College of Psychiatrists — Odstawianie leków przeciwdepresyjnych\n\nDoświadczenia z odstawianiem są różne. Tempo redukcji powinno uwzględniać osobę, długość leczenia, wcześniejsze objawy i stosowany lek.\n\nŻadne wytyczne kliniczne nie ustanawiają trzech lat jako uniwersalnego terminu regeneracji. Ten kamień milowy docenia Twój postęp.';

  @override
  String get snriMilestone1460Title => '4 lata: Siła z czasem';

  @override
  String get snriMilestone1460Description =>
      'Cztery lata odzwierciedlają trwały postęp budowany z czasem. Twoje doświadczenie jest indywidualne, a ten kamień milowy honoruje to, co udało się utrzymać, bez przypisywania stałego neurologicznego harmonogramu.';

  @override
  String get snriReferenceDay1460 =>
      'Cztery lata po SNRI: Długotrwały postęp\n\nŹródło: Royal College of Psychiatrists — Odstawianie leków przeciwdepresyjnych\n\nRoyal College zaleca stopniowe, indywidualne zmniejszanie dawki. Duloksetyna i wenlafaksyna mają wyższe ryzyko objawów odstawiennych.\n\nTe dane nie tworzą neurologicznego kamienia milowego po czterech latach. Dziś świętujemy trwały postęp.';

  @override
  String get snriMilestone1825Title => '5 lat: Pięcioletni jubileusz';

  @override
  String get snriMilestone1825Description =>
      'Pięć lat to ważny osobisty kamień milowy. Świętuje długoterminowy postęp po odstawieniu SNRI, uznając, że odstawianie i regeneracja nie przebiegają według jednego harmonogramu.';

  @override
  String get snriReferenceDay1825 =>
      'Pięć lat po SNRI: Pięcioletni kamień milowy\n\nŹródło: Royal College of Psychiatrists — Odstawianie leków przeciwdepresyjnych\n\nWytyczne koncentrują się na bezpiecznym, indywidualnym zmniejszaniu dawki i reagowaniu na objawy, nie na jednym harmonogramie dla wszystkich.\n\nNie określają pięcioletniego progu regeneracji opartego na dowodach. Pięć lat pozostaje ważną osobistą rocznicą.';

  @override
  String get settingsShowSnriTracking => 'Pokaż śledzenie SNRI';

  @override
  String get settingsNotifySnri => 'Informuj SNRI o zakończeniu postępu';

  @override
  String get addictionTca => 'TCA';

  @override
  String get tcaPageTitle => 'Odzyskiwanie TCA';

  @override
  String get tcaHeaderStarted => 'Twoja podróż po powrocie do zdrowia';

  @override
  String get tcaHeaderNotStarted => 'Korzyści z Tapering Off TCA';

  @override
  String get tcaSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get tcaSubtitleNotStarted =>
      'Zobaczymy, co się stanie, gdy się odprężysz.';

  @override
  String get tcaMilestone3Title => 'Dzień 3: Odbicie cholinergiczne';

  @override
  String get tcaMilestone3Description =>
      'Odstawienie TCA może wywołać rzeczywisty zespół odstawienny, a nadaktywność cholinergiczna jest jednym z proponowanych mechanizmów. Nudności, biegunka, ból brzucha, bezsenność, lęk, pobudzenie i ból głowy mogą pojawić się wcześnie, szczególnie po nagłym odstawieniu lub zbyt szybkim zmniejszaniu dawki. Dzień 3 to kamień milowy; moment wystąpienia i nasilenie objawów są różne.';

  @override
  String get tcaMilestone7Title => 'Tydzień: Pierwszy etap za Tobą';

  @override
  String get tcaMilestone7Description =>
      'Objawy odstawienne zwykle zaczynają się w ciągu kilku dni i często trwają kilka tygodni. Po tygodniu nadal mogą występować nudności, pocenie się, problemy ze snem, kołatanie serca i zawroty głowy. Siedem dni to realny postęp, a poprawa może postępować w różnym tempie.';

  @override
  String get tcaMilestone14Title => '2 tygodnie: ostry etap słabnie';

  @override
  String get tcaMilestone14Description =>
      'Typowe objawy odstawienia leków przeciwdepresyjnych, takie jak nudności, bezsenność, zaburzenia równowagi, objawy czuciowe i nadmierne pobudzenie, zwykle trwają od jednego do dwóch tygodni. W 14. dniu wiele osób dociera do końca tej ostrej fazy.';

  @override
  String get tcaMilestone30Title => '1 miesiąc: ostry etap minął';

  @override
  String get tcaMilestone30Description =>
      'Typowe objawy odstawienia leków przeciwdepresyjnych trwają zwykle od jednego do dwóch tygodni. Po 30 dniach większość osób ma już za sobą tę ostrą fazę; objawy grypopodobne, nudności, zaburzenia równowagi, bezsenność, zaburzenia czucia i nadmierne pobudzenie zwykle wyraźnie słabną lub ustępują.';

  @override
  String get tcaMilestone90Title => '3 miesiące: ostry etap za tobą';

  @override
  String get tcaMilestone90Description =>
      'Typowe objawy odstawienia leków przeciwdepresyjnych trwają zwykle od jednego do dwóch tygodni. Po 90 dniach jesteś ponad dziesięć tygodni za górną granicą tego typowego ostrego okna; objawy grypopodobne, nudności, zaburzenia równowagi, bezsenność, zaburzenia czucia i nadmierne pobudzenie zwykle dawno już osłabły lub ustąpiły.';

  @override
  String get tcaMilestone180Title => '6 miesięcy: większość bez nawrotu';

  @override
  String get tcaMilestone180Description =>
      'Wśród osób odstawiających leki przeciwdepresyjne po leczeniu dużej depresji metaanaliza 35 badań wykazała łączny odsetek nawrotów 34,8% po sześciu miesiącach — około 65% osób pozostało bez nawrotu. To ogromny odcinek stabilności.';

  @override
  String get tcaMilestone365Title => 'Rok: większość pozostała bez nawrotu';

  @override
  String get tcaMilestone365Description =>
      'Wśród osób odstawiających leki przeciwdepresyjne po leczeniu dużej depresji metaanaliza 35 badań wykazała łączny odsetek nawrotów 45,12% po 12 miesiącach — około 55% pozostało bez nawrotu przez pełny rok. To ważny kamień milowy długoterminowej stabilności.';

  @override
  String get tcaMilestone730Title => '2 lata: Mocny grunt';

  @override
  String get tcaMilestone730Description =>
      'Dwa lata od zakończenia stopniowego odstawiania TCA to ważny kamień milowy. Doświadczenia związane z odstawieniem są różne, dlatego ten moment świętuje trwały postęp bez wyznaczania uniwersalnej biologicznej mety.';

  @override
  String get tcaReferenceDay730 =>
      'Dwa lata po TCA: Trwały postęp\n\nŹródło: NICE NG222 — Depression in adults: treatment and management\n\nNICE wyraźnie wymienia TCA wśród leków przeciwdepresyjnych, po których mogą wystąpić objawy odstawienne. Przebieg różni się między osobami, a dawkę należy zmniejszać stopniowo i indywidualnie.\n\nWytyczne nie definiują biologicznego progu dwóch lat. Ta rocznica świętuje dwa lata trwałego postępu bez tworzenia uniwersalnej mety.';

  @override
  String get tcaMilestone1095Title => '3 lata: Postęp trwa';

  @override
  String get tcaMilestone1095Description =>
      'Trzy lata to długi okres utrzymanego postępu. Wytyczne nie wyznaczają na ten dzień szczególnego końca zdrowienia po TCA; znaczenie mają stabilność, nawyki i decyzje utrzymywane przez te lata.';

  @override
  String get tcaReferenceDay1095 =>
      'Trzy lata po TCA: Postęp utrzymany\n\nŹródło: NICE NG222 — Depression in adults: treatment and management\n\nNICE wyraźnie wymienia TCA wśród leków przeciwdepresyjnych, po których mogą wystąpić objawy odstawienne. Przebieg różni się między osobami, a dawkę należy zmniejszać stopniowo i indywidualnie.\n\nWytyczne nie wskazują trzech lat jako uniwersalnego terminu zdrowienia. Ten kamień milowy docenia stabilność i postęp utrzymane przez trzy lata.';

  @override
  String get tcaMilestone1460Title => '4 lata: Trwały postęp';

  @override
  String get tcaMilestone1460Description =>
      'Cztery lata pokazują trwały postęp budowany z czasem. Doświadczenie po odstawieniu TCA jest indywidualne, a ten kamień milowy docenia to, co udało się utrzymać, bez tworzenia sztywnego neurologicznego harmonogramu.';

  @override
  String get tcaReferenceDay1460 =>
      'Cztery lata po TCA: Postęp długoterminowy\n\nŹródło: NICE NG222 — Depression in adults: treatment and management\n\nNICE wyraźnie wymienia TCA wśród leków przeciwdepresyjnych, po których mogą wystąpić objawy odstawienne. Przebieg różni się między osobami, a dawkę należy zmniejszać stopniowo i indywidualnie.\n\nWytyczne nie ustanawiają biologicznego progu czterech lat. Cztery lata nadal są ważnym znacznikiem długoterminowego postępu.';

  @override
  String get tcaMilestone1825Title => '5 lat: Postęp na lata';

  @override
  String get tcaMilestone1825Description =>
      'Pięć lat to ważna osobista rocznica. Oznacza trwałą zmianę po odstawieniu TCA, z poszanowaniem faktu, że odstawienie i zdrowienie nie przebiegają według jednego harmonogramu.';

  @override
  String get tcaReferenceDay1825 =>
      'Pięć lat po TCA: Ważna rocznica\n\nŹródło: NICE NG222 — Depression in adults: treatment and management\n\nNICE wyraźnie wymienia TCA wśród leków przeciwdepresyjnych, po których mogą wystąpić objawy odstawienne. Przebieg różni się między osobami, a dawkę należy zmniejszać stopniowo i indywidualnie.\n\nDowody nie ustanawiają pięcioletniego progu zdrowienia po TCA. Pięć lat pozostaje ważną osobistą rocznicą i mocnym znakiem trwałej zmiany.';

