  @override
  String get maoiHeaderNotStarted => 'Korzyści związane z odciąganiem IMAO';

  @override
  String get maoiSubtitleStarted =>
      'Śledź swój postęp i świętować każdy kamień milowy';

  @override
  String get maoiSubtitleNotStarted =>
      'Zobaczymy, co się stanie, gdy się odprężysz.';

  @override
  String get maoiMilestone3Title => 'Dzień 3: Najwyższe ryzyko';

  @override
  String get maoiMilestone3Description =>
      'MAOI wiążą się z jednymi z najpoważniejszych zagrożeń po nagłym odstawieniu wśród leków przeciwdepresyjnych. Nagłe przerwanie stosowania — szczególnie fenelzyny i tranylcyprominy — może wywołać silne pobudzenie, splątanie, omamy, mioklonie i hipertermię. Jeśli występują takie objawy, natychmiast zgłoś się po pomoc medyczną. MAOI nieodwracalnie unieczynniają enzymy MAO; powrót ich aktywności wymaga wytworzenia przez organizm nowych enzymów, co zajmuje około 14 dni.';

  @override
  String get maoiMilestone7Title => 'Tydzień: Synteza MAO trwa';

  @override
  String get maoiMilestone7Description =>
      'MAOI nieodwracalnie unieczynniają cząsteczki enzymów MAO, dlatego odzyskanie aktywności wymaga syntezy nowych enzymów. Po tygodniu mogło wrócić około 50% prawidłowej aktywności MAO. Ciężkie ostre objawy odstawienne, takie jak majaczenie, mioklonie i hipertermia, są wyraźnie rzadsze. Nadal ważny jest ścisły nadzór medyczny.';

  @override
  String get maoiMilestone14Title => '2 tygodnie: Aktywność MAO wraca';

  @override
  String get maoiMilestone14Description =>
      'Dwa tygodnie to standardowy kliniczny okres potrzebny na odzyskanie aktywności enzymów MAO po odstawieniu. Około 14. dnia aktywność MAO-A i MAO-B jest w dużej mierze przywrócona, a prawidłowy metabolizm tyraminy ponownie się ustala. Ograniczenia dietetyczne wymagane podczas leczenia MAOI można zwykle łagodzić po konsultacji z lekarzem prowadzącym.';

  @override
  String get maoiMilestone30Title => 'Miesiąc: Równowaga neurochemiczna';

  @override
  String get maoiMilestone30Description =>
      'Miesiąc po odstawieniu MAOI enzymy MAO znów są aktywne, a mózg naturalnie reguluje serotoninę, noradrenalinę, dopaminę i tyraminę. Okres szczególnych ograniczeń dotyczących żywności i interakcji lekowych minął, ale przy przepisywaniu nowych leków nadal warto informować lekarzy o wcześniejszym stosowaniu MAOI.';

  @override
  String get maoiMilestone90Title => '3 miesiące: Stabilizacja';

  @override
  String get maoiMilestone90Description =>
      'Trzy miesiące dają układom odpowiedzialnym za nastrój i energię dużo czasu na ponowne dostosowanie się po MAOI. Nastrój, energia i jasność myślenia stabilizują się, gdy mózg ponownie sam reguluje te neuroprzekaźniki.';

  @override
  String get maoiMilestone180Title => '6 miesięcy: Dalsza regeneracja';

  @override
  String get maoiMilestone180Description =>
      'Sześć miesięcy to długi okres naturalnej regulacji monoamin. Populacje receptorów serotoninowych, noradrenergicznych i dopaminowych miały czas na normalizację. Także szlaki fenyloetyloaminy (PEA), na które wpływają MAOI, wracają do naturalnego poziomu — to często pomijany element regeneracji związany z normalizacją emocji.';

  @override
  String get maoiMilestone365Title => 'Rok: Utrwalona regeneracja';

  @override
  String get maoiMilestone365Description =>
      'Rok po odstawieniu MAOI oznacza pełne dwanaście miesięcy bez leku. Nastrój, energia, jasność myślenia i naturalna regulacja neurochemiczna miały dużo czasu, by się ustabilizować i odbudować.';

