  @override
  String get adderallReferenceDay1 =>
      'Odstawienie amfetaminy: co dzieje się na początku\n\nŹródło: MedlinePlus (U.S. National Library of Medicine)\n\nCzym są amfetaminy?\nAmfetaminy to stymulanty obejmujące zarówno substancje nielegalne (np. uliczny „speed”), jak i leki na receptę stosowane w leczeniu ADHD i narkolepsji, takie jak Adderall i Vyvanse. Silnie zwiększają poziom dopaminy i noradrenaliny, co może powodować intensywne skupienie, przypływ energii i euforię. Przy regularnym, intensywnym używaniu mózg dostosowuje się do powtarzających się wzrostów tych neuroprzekaźników, dlatego po odstawieniu nastrój, energia i motywacja mogą przejściowo się obniżyć.\n\nTypowe objawy odstawienia\nMedlinePlus wymienia jako typowe po odstawieniu amfetamin:\n• silne pragnienie przyjęcia substancji\n• wahania nastroju od depresji przez pobudzenie po lęk\n• zmęczenie przez cały dzień\n• trudności z koncentracją\n• omamy (widzenie lub słyszenie rzeczy, których nie ma)\n• reakcje fizyczne, takie jak ból głowy, bóle ciała, zwiększony apetyt i problemy ze snem\n\nCzy odstawienie jest niebezpieczne?\nMedlinePlus nie opisuje samego zespołu odstawiennego po amfetaminie jako medycznie niebezpiecznego, ale zaznacza, że ciężkie objawy mogą wymagać leczenia stacjonarnego, a problemy z nastrojem i emocjami związane z używaniem amfetaminy — w tym depresja — mogą być poważne i wymagają wsparcia.\n\nUzyskanie pomocy\nMedlinePlus zaleca kontakt z personelem medycznym, jeśli Ty lub ktoś, kogo znasz, ma problem z uzależnieniem od amfetamin i potrzebuje pomocy w zaprzestaniu używania. W przypadku myśli o samookaleczeniu źródło kieruje do pomocy kryzysowej, takiej jak 988 lub 911.';

  @override
  String get adderallReferenceDay3 =>
      'Postępowanie w odstawieniu amfetaminy: dzień 3\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\nGdzie znajduje się dzień 3?\nWytyczne WHO podają, że objawy odstawienia stymulantów „zaczynają się w ciągu 24 godzin od ostatniego użycia stymulantu i trwają 3–5 dni”. Trzeci dzień przypada więc w samym środku ostrej fazy i zwykle należy do najtrudniejszych, zanim objawy zaczną ustępować.\n\nObjawy\nW przypadku stymulantów typu amfetaminowego wytyczne wymieniają:\n• pobudzenie i drażliwość\n• depresję\n• zwiększoną senność i apetyt\n• bóle mięśni\nU osób używających dużych ilości mogą też wystąpić objawy psychotyczne, takie jak paranoja, dezorganizacja myślenia lub omamy.\n\nPrzede wszystkim trudność psychologiczna\nW przeciwieństwie do odstawienia alkoholu lub opioidów typowymi cechami odstawienia stymulantów nie są wymioty, drżenia ani napady drgawkowe. Największe trudności są zwykle psychologiczne: obniżony nastrój, utrata odczuwania przyjemności i silne pragnienie użycia substancji.\n\nPostępowanie\nWytyczne WHO zalecają leczenie wspierające:\n• picie co najmniej 2–3 litrów wody dziennie\n• preparaty wielowitaminowe z witaminami z grupy B i witaminą C\n• leczenie objawowe bólu i lęku\n• przy ciężkim pobudzeniu najpierw strategie behawioralne, a sedację diazepamem tylko wtedy, gdy jest potrzebna\n\nPo fazie ostrej\nWytyczne wskazują, że najtrudniejsza faza odstawienia trwa tylko kilka dni, po czym może nastąpić łagodniejszy okres zdrowienia trwający około jednego do dwóch miesięcy.';

  @override
  String get adderallReferenceDay7 =>
      'Tydzień bez Adderallu: najtrudniejszy etap mija\n\nŹródło: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), PubMed Central\n\nFaza ostra ustępuje\nTen przegląd dowodów opisuje odstawienie psychostymulantów etapami. W fazie ostrej objawy „osiągają szczyt po pierwszych 2–3 dniach”, a „główny dyskomfort zwykle ustępuje w ciągu 4–7 dni”. Pod koniec pierwszego tygodnia większość osób ma już za sobą najtrudniejszą część gwałtownego spadku samopoczucia: energia i apetyt zaczynają się stabilizować, a sen regulować.\n\nCo dalej?\nWedług przeglądu większość pozostałych objawów nadal słabnie przez kolejne dwa do trzech tygodni. Siódmego dnia zdrowienie jest już wyraźnie w toku.\n\nCo może nadal występować w 7. dniu?\nObjawy psychologiczne zwykle utrzymują się dłużej niż fizyczny „zjazd”:\n• niska motywacja i utrata odczuwania przyjemności\n• trudności z koncentracją\n• nastrój nadal gorszy niż zwykle\nOdzwierciedla to układ dopaminowy, który ponownie się dostosowuje — jest to normalna i przejściowa część zdrowienia.\n\nSygnał zdrowienia\nNie ma leku zatwierdzonego przez FDA specjalnie do leczenia odstawienia stymulantów. W tej fazie podstawą są więc opieka wspierająca, rutyna, sen, odżywianie i wsparcie psychologiczne.';

  @override
  String get adderallReferenceDay14 =>
      'Dwa tygodnie bez Adderallu: dłuższa faza zdrowienia\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\nPo fazie ostrej\nWHO opisuje najcięższy etap odstawienia stymulantów jako trwający około 3–5 dni, po którym następuje łagodniejszy okres zdrowienia trwający około 1–2 miesięcy. Po dwóch tygodniach gwałtowny początkowy „zjazd” jest już daleko za Tobą.\n\nJak może wyglądać dłuższa faza zdrowienia?\nNadmierna senność, pobudzenie i bóle mięśni w dużej mierze ustępują. To, co pozostaje, jest zwykle łagodniejsze: obniżony lub zmienny nastrój, mniejsza motywacja i okresowe pragnienie użycia substancji, gdy układ nagrody w mózgu ponownie się dostosowuje.\n\nSen i apetyt\nZwiększona senność i apetyt z ostrej fazy normalizują się. Wraz ze stabilizacją snu zwykle poprawiają się też nastrój, koncentracja i energia.\n\nRyzyko nawrotu i ADHD\nTo nadal okres podwyższonego ryzyka, szczególnie jeśli bez leku powracają podstawowe objawy ADHD. Wytyczne WHO podkreślają znaczenie wsparcia psychologicznego i umiejętności zapobiegania nawrotom. Dla osób przyjmujących Adderall na ADHD jest to dobry moment, by omówić z lekarzem strategie niestymulujące lub inne możliwości leczenia.';

  @override
  String get adderallReferenceDay30 =>
      'Miesiąc bez Adderallu: większość objawów jest już za Tobą\n\nŹródło: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), PubMed Central\n\nGdzie znajduje się pierwszy miesiąc?\nPrzegląd wskazuje, że większość objawów odstawienia słabnie w ciągu pierwszych dwóch do trzech tygodni. Po 30 dniach większość z nich wyraźnie ustąpiła, a nastrój i motywacja są zwykle znacznie lepsze niż w pierwszym tygodniu.\n\nPóźniejsza faza zdrowienia\nMiędzy pierwszym a szóstym miesiącem pamięć, planowanie, koncentracja i podejmowanie decyzji mogą nadal się poprawiać. Po miesiącu początkowy „zjazd” się skończył, a te postępy już trwają.\n\nNastrój i motywacja\nGłęboka utrata odczuwania przyjemności z początkowego okresu w dużej mierze ustępuje. Czynności, które w pierwszym tygodniu wydawały się pozbawione przyjemności, mogą znów zacząć dawać satysfakcję wraz z regeneracją naturalnej sygnalizacji dopaminowej.\n\nDla osób z ADHD\nJeśli Adderall był przepisany na ADHD, podstawowe objawy mogą być teraz bardziej zauważalne. Na tym etapie ważne jest omówienie z lekarzem strategii niestymulujących lub innych możliwości leczenia.';

  @override
  String get adderallReferenceDay60 =>
      'Dwa miesiące bez Adderallu: dłuższa faza zdrowienia dobiega końca\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\nGdzie znajdują się dwa miesiące?\nWHO opisuje łagodniejszy okres zdrowienia trwający około 1–2 miesięcy po początkowym „zjeździe”. Po 60 dniach jesteś przy końcu tego przedziału, a utrzymujące się objawy w dużej mierze ustępują.\n\nCo się poprawia?\nPobudzenie, obniżony nastrój oraz zaburzenia snu i apetytu wymieniane w wytycznych dotyczących odstawienia stymulantów u większości osób znacznie się uspokajają:\n• codzienny nastrój jest stabilniejszy, z mniejszą liczbą wahań niż na początku zdrowienia\n• sen i apetyt normalizują się\n• układ nagrody łatwiej reaguje na codzienne przyjemności — jedzenie, ruch i kontakt z innymi\n\nSygnał zdrowienia\nWyższe dawki i dłuższy okres używania mogą wydłużać zdrowienie. Utrzymywanie abstynencji pozwala jednak nastrojowi, motywacji i jasności myślenia nadal zbliżać się do normy w kolejnych miesiącach.\n\nZdrowie fizyczne\nGdy lek przestaje być częścią codzienności, słabnie jego wpływ na tętno, apetyt i masę ciała, a obciążenie układu krążenia związane z używaniem stymulantów się zmniejsza.';

  @override
  String get adderallReferenceDay90 =>
      'Trzy miesiące bez Adderallu: najtrudniejszy etap za Tobą, zdrowienie trwa\n\nŹródło: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), PubMed Central\n\nGdzie znajduje się 90. dzień?\nPo trzech miesiącach wczesne objawy dawno minęły, natomiast pamięć, planowanie, koncentracja, podejmowanie decyzji i układ nagrody mogą nadal się poprawiać.\n\nMyślenie i pamięć nadal się regenerują\nPrzegląd wskazuje, że pamięć, planowanie, koncentracja i decyzje dotyczące ryzyka mogą poprawiać się przez wiele miesięcy. Po 90 dniach przy dalszej abstynencji koncentracja i pamięć nadal zmierzają we właściwym kierunku.\n\nDlaczego ten okres nadal ma znaczenie?\nNie ma leku zatwierdzonego przez FDA specjalnie do leczenia odstawienia stymulantów. Rutyna, terapia, ruch, sen i wsparcie są więc narzędziami, które pomagają przejść przez ten etap. Budowanie tych nawyków wspiera dalsze zdrowienie.\n\nSzerszy obraz\nTrzy miesiące to realne osiągnięcie — najtrudniejsze odcinki fizyczne i emocjonalne są za Tobą, a przy dalszej abstynencji kierunek zmian jest stopniowo korzystny.';

  @override
  String get adderallReferenceDay180 =>
      'Sześć miesięcy bez Adderallu: daleko poza najtrudniejszym etapem\n\nŹródło: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nCo StatPearls mówi o stymulantach?\nTo źródło kliniczne opisuje zdrowienie po stymulantach jako początkowy „zjazd”, po którym następuje stopniowa poprawa. Typowe problemy obejmują depresję, nadmierną senność, zwiększony głód, obniżony nastrój oraz spowolnienie ruchowe i myślenia. Depresja może trwać kilka tygodni, a łagodniejsza poprawa może postępować jeszcze później.\n\nGdzie znajduje się sześć miesięcy?\nPo sześciu miesiącach zarówno okres ostry, jak i kilkutygodniowa faza depresyjna opisana przez StatPearls są daleko za Tobą. Stopniowa regeneracja miała dużo czasu na postęp i u większości osób zwykły nastrój, sen, apetyt i motywacja stają się stabilniejsze.\n\nSygnał zdrowienia\nStatPearls opisuje stopniową poprawę także po pierwszych tygodniach. Po sześciu miesiącach ostry „zjazd” i kilkutygodniowa faza depresyjna są dawno za Tobą, a stabilny nastrój, sen, apetyt i motywacja stają się dominującym wzorcem.\n\nZwiązek z ADHD\nDla osób, które przyjmowały Adderall z powodu ADHD, sześć miesięcy bez leku to dobry moment na spokojny przegląd aktualnych objawów z lekarzem i ocenę, czy podejścia niestymulujące — ruch, sen, rutyna, terapia lub inne leki — odpowiadają ich potrzebom.';

  @override
  String get adderallReferenceDay365 =>
      'Rok bez Adderallu: znaczna regeneracja, bez przesady\n\nŹródło: Berman et al., \"Potential Adverse Effects of Amphetamine Treatment on Brain and Behavior: A Review,\" Molecular Psychiatry (2008), PubMed Central\n\nO tym przeglądzie\nPrzegląd analizuje możliwy wpływ wysokich dawek lub długotrwałej ekspozycji na amfetaminę na mózg i dokumentuje mierzalną regenerację podczas abstynencji.\n\nCo mówi o regeneracji?\nW przeglądzie udokumentowano poprawę przepływu krwi w mózgu oraz białek odpowiadających za wychwyt zwrotny dopaminy po długotrwałej abstynencji. Niektóre obszary mózgu regenerują się szybciej niż inne, ale ogólny kierunek jest wyraźny: po zaprzestaniu używania mózg się regeneruje.\n\nRegeneracja długoterminowa\nPrzegląd dokumentuje mierzalną poprawę przepływu krwi w mózgu i recyklingu dopaminy po długotrwałej abstynencji. Po roku te układy mózgowe miały pełny rok na dalszą odbudowę.\n\nCo to oznacza po roku?\nU większości osób — szczególnie tych, które przyjmowały Adderall w dawkach zgodnych z zaleceniem — rok bez leku może oznaczać, że układy nagrody, uwagi i motywacji dobrze funkcjonują na co dzień. Przy większym lub dłuższym używaniu regeneracja może potrwać dłużej, ale nadal postępuje. Ryzyko nawrotu jest znacznie niższe niż we wczesnej fazie zdrowienia.';

  @override
  String get alcoholReferenceDay1 =>
      'Co dzieje się ze snem po odstawieniu alkoholu?\n\nŹródło: \"Alcohol and the Sleeping Brain\" (Colrain, Nicholas & Baker), Handbook of Clinical Neurology — publikacja recenzowana, udostępniona przez NIH\n\nAlkohol a struktura snu\nAlkohol działa uspokajająco, więc może skracać czas zasypiania i zwiększać ilość głębokiego snu wolnofalowego w pierwszej połowie nocy. Ma to jednak koszt: alkohol tłumi sen REM, związany z utrwalaniem pamięci i regulacją emocji, a w drugiej połowie nocy, gdy jest metabolizowany, powoduje częstsze wybudzenia i fragmentację snu.\n\nPierwsza noc bez alkoholu\nPonieważ alkohol tłumi sen REM, pierwsze noce bez niego często przynoszą odbicie REM: żywe sny oraz lżejszy, przerywany sen, gdy normalny rytm snu wraca. To zwykła i przejściowa część zdrowienia.\n\nPoczątek poprawy\nW kolejnych dniach i tygodniach, gdy mózg ponownie się dostosowuje, sen REM i ogólna jakość snu poprawiają się. Zaburzenia snu należą do najbardziej uporczywych objawów odstawienia, ale przy utrzymanej abstynencji stopniowo zbliżają się do normy.\n\nUwaga przy intensywnym piciu\nU osób pijących dużo lub codziennie przez długi czas pierwsze 24 godziny mogą przynieść objawy odstawienia, takie jak lęk, poty, drżenie i nudności. Ciężkie odstawienie może być niebezpieczne; jeśli pijesz dużo każdego dnia, porozmawiaj z lekarzem przed nagłym przerwaniem picia.';

  @override
  String get alcoholReferenceDay3 =>
      'Dzień trzeci: Okno szczytu odstawienia\n\nŹródło: \"Alcohol Withdrawal\", StatPearls — recenzowane, NIH National Library of Medicine\n\nOkoło 72 godzin\nObjawy odstawienia alkoholu mogą rozpocząć się w ciągu kilku godzin i często osiągają szczyt około 72. godziny. StatPearls wymienia drżenie, bezsenność, pobudzenie, poty, wysokie ciśnienie, szybkie tętno i napady drgawkowe jako oznaki tego stanu nadmiernego pobudzenia.\n\nTrzy mocne dni\nDotarcie do 72 godzin to ogromny kamień milowy, bo wypada dokładnie w udokumentowanym oknie szczytu wielu ostrych objawów.\n\nCiężkie odstawienie może pojawić się później\nMajaczenie alkoholowe (delirium tremens) może wystąpić 3–8 dni po odstawieniu i może być śmiertelne. Ciężkie odstawienie jest stanem nagłym. Osoby pijące dużo codziennie oraz osoby z wcześniejszymi napadami drgawkowymi lub majaczeniem odstawiennym powinny zasięgnąć porady medycznej zamiast nagle odstawiać alkohol bez wsparcia.\n\nNa co zwracać uwagę\nGorączka, silne pobudzenie, obfite poty, omamy, dezorientacja, napady drgawkowe, bardzo szybkie tętno lub bardzo wysokie ciśnienie wymagają pilnej pomocy medycznej.';

  @override
  String get alcoholReferenceDay7 =>
      'Jak regeneruje się układ odpornościowy\n\nŹródło: \"Alcohol and the Immune System\" (Sarkar, Jung & Wang), Alcohol Research: Current Reviews — publikacja recenzowana, udostępniona przez NIH\n\nJak alkohol osłabia odporność\nAlkohol osłabia układ odpornościowy na kilka sposobów. Nawet jeden epizod intensywnego picia może zmniejszyć zdolność do zwalczania infekcji nawet na 24 godziny. Długotrwałe picie zmniejsza liczbę białych krwinek, zaburza sygnalizację immunologiczną oraz uszkadza bariery obronne jelit i płuc, zwiększając ryzyko infekcji i spowalniając gojenie ran.\n\nUsunięcie szkodliwego czynnika\nWiele z tych efektów zaczyna się poprawiać po odstawieniu alkoholu. Białe krwinki i sygnalizacja immunologiczna zaczynają się regenerować, podobnie jak mechanizmy obronne jelit i dróg oddechowych. W pierwszym tygodniu układ odpornościowy nie jest już codziennie osłabiany przez alkohol, a odporność na częste infekcje zaczyna się poprawiać.\n\nProces stopniowy\nPełna regeneracja odporności trwa dłużej niż tydzień, a jej zakres zależy od intensywności i czasu wcześniejszego picia. Pierwszy tydzień bez alkoholu jest jednak początkiem odbudowy.';

  @override
  String get alcoholReferenceDay14 =>
      'Wczesna regeneracja mózgu podczas abstynencji\n\nŹródło: Bartsch AJ et al., \"Manifestations of early brain recovery associated with abstinence from alcoholism\", Brain (2007) — publikacja recenzowana\n\nPomiar regeneracji\nW badaniu użyto MRI, aby śledzić osoby z zależnością od alkoholu krótko po detoksykacji w pierwszych tygodniach abstynencji i porównać je ze zdrową grupą kontrolną. Pozwoliło to uchwycić fizyczną odbudowę mózgu po zaprzestaniu picia.\n\nObjętość mózgu rośnie\nPrzewlekłe picie alkoholu zmniejsza objętość mózgu, częściowo przez odwracalne zmniejszenie rozmiaru komórek, a nie wyłącznie przez trwałą utratę komórek. Podczas abstynencji badacze zmierzyli średni wzrost całkowitej objętości mózgu o niemal 2%, szczególnie w okolicy móżdżku, śródmózgowia, komór i obszarów czołowych. Duża część tej poprawy zachodzi wcześnie, w pierwszych tygodniach bez alkoholu.\n\nMóżdżek i uwaga\nRegeneracja była szczególnie widoczna w obszarach związanych z ruchem i uwagą. Wskaźnik zdrowia komórek mózgowych wzrastał równolegle z mierzalną poprawą uwagi, więc fizycznej odbudowie towarzyszyły rzeczywiste korzyści poznawcze.\n\nPodstawa, nie meta\nWyższe funkcje, takie jak złożone rozumowanie, wracają stopniowo. Pierwsze dwa tygodnie pokazują jednak, że po usunięciu alkoholu mózg szybko zaczyna się regenerować.';

  @override
  String get alcoholReferenceDay30 =>
      'Ciśnienie krwi spada po ograniczeniu alkoholu\n\nŹródło: Roerecke et al., \"The effect of a reduction in alcohol consumption on blood pressure: a systematic review and meta-analysis\", Lancet Public Health (2017) — publikacja recenzowana\n\nDowody\nMetaanaliza objęła 36 randomizowanych badań z udziałem około 2865 osób i sprawdzała, co dzieje się z ciśnieniem krwi, gdy ludzie piją mniej. Wykazano wyraźny efekt zależny od dawki: im większe ograniczenie alkoholu, tym większy spadek ciśnienia.\n\nJak duży jest efekt?\nU osób pijących dwa drinki dziennie lub mniej dalsze ograniczenie nie przynosiło istotnej zmiany ciśnienia. Powyżej tego progu efekt zależał od dawki. Był najsilniejszy u osób pijących sześć lub więcej drinków dziennie, które zmniejszyły spożycie mniej więcej o połowę: średnio ciśnienie skurczowe spadło o około 5,5 mmHg, a rozkurczowe o około 4,0 mmHg. To zmiana istotna klinicznie, porównywalna z działaniem części leków na nadciśnienie i wystarczająca, by zmniejszyć długoterminowe ryzyko udaru i chorób serca.\n\nDlaczego miesiąc ma znaczenie\nAlkohol podnosi ciśnienie przez aktywację reakcji stresowej, wzrost kortyzolu i usztywnienie naczyń. Badania w tej analizie pokazują, że korzyści pojawiają się w ciągu tygodni utrzymanego ograniczenia, więc około miesiąca abstynencji daje ciśnieniu osoby wcześniej pijącej dużo czas na przesunięcie się w zdrowszym kierunku.\n\nEfekt progowy\nKorzyści koncentrowały się u osób pijących więcej niż dwa drinki dziennie i rosły wraz z większym wcześniejszym spożyciem. Przy lżejszym piciu nie należy oczekiwać tej konkretnej korzyści dla ciśnienia, natomiast osoby pijące dużo mogą uzyskać realny i mierzalny efekt sercowo-naczyniowy po zaprzestaniu picia.';

  @override
  String get alcoholReferenceDay60 =>
      'Regeneracja wątroby po zaprzestaniu picia\n\nŹródło: National Institute on Alcohol Abuse and Alcoholism (NIAAA), \"Alcohol\'s Effects on the Body\"\n\nJak alkohol uszkadza wątrobę\nWątroba przetwarza większość wypijanego alkoholu i ponosi dużą część szkód. NIAAA opisuje kolejne etapy uszkodzenia wątroby związanego z alkoholem: zaczyna się od stłuszczenia, czyli odkładania tłuszczu w komórkach wątroby, może przejść w alkoholowe zapalenie wątroby, a przy długotrwałym intensywnym piciu w zwłóknienie i marskość.\n\nWczesne etapy mogą się cofać\nWątroba ma dużą zdolność regeneracji i wczesne etapy uszkodzenia mogą poprawiać się po zaprzestaniu picia. Stłuszczenie wątroby często ustępuje przy trwałej abstynencji. Po około dwóch miesiącach bez alkoholu wątroba ma czas na zmniejszenie nagromadzenia tłuszczu, wyciszenie stanu zapalnego i odzyskanie zdrowszej funkcji, co zwykle znajduje odzwierciedlenie w spadku enzymów wątrobowych ALT i AST.\n\nNie tylko wątroba\nNIAAA wskazuje też, że alkohol obciąża serce, trzustkę i układ odpornościowy. Dłuższa przerwa od alkoholu pozwala również tym układom się regenerować, co może przyczyniać się do stabilniejszej energii i lepszego ogólnego samopoczucia na tym etapie.';

  @override
  String get alcoholReferenceDay90 =>
      'Myślenie i pamięć po trzech miesiącach trzeźwości\n\nŹródło: systematyczny przegląd neuropsychologicznej regeneracji po abstynencji od alkoholu (PubMed Central, 2024) — publikacja recenzowana\n\nCo pokazują dowody\nPrzegląd połączył badania śledzące, jak po zaprzestaniu picia wracają zdolności myślenia i pamięci. Większość funkcji zbliża się do normy w ciągu około sześciu do dwunastu miesięcy, a część poprawia się wcześniej.\n\nCo poprawia się najpierw\nDwie zdolności wyróżniają się wcześniejszą poprawą: podstawowa szybkość przetwarzania, która zwykle poprawia się około pierwszego miesiąca, choć dokładność w bardziej złożonych zadaniach może pozostawać w tyle, oraz aktualizowanie pamięci roboczej. Około trzeciego miesiąca wiele osób zaczyna zauważać te zmiany.\n\nCo trwa dłużej\nUwaga, planowanie, podejmowanie decyzji, kontrola impulsów, spostrzeganie i pamięć nadal poprawiają się w okresie od sześciu do dwunastu miesięcy.\n\nCo wpływa na regenerację\nNa tempo regeneracji wpływają między innymi wiek, palenie i zdolności sprzed choroby, natomiast związek z całkowitą ilością wcześniej wypijanego alkoholu nie jest konsekwentny. Oczekiwanym kierunkiem jest poprawa.\n\nDlaczego to ważne\nJaśniejsze myślenie to praktyczny element zdrowienia: lepsza uwaga i podejmowanie decyzji pomagają kontynuować leczenie i unikać nawrotu.';

  @override
  String get alcoholReferenceDay180 =>
      'Regeneracja mózgu po sześciu miesiącach trzeźwości\n\nŹródło: recenzowany przegląd strukturalnej i funkcjonalnej regeneracji mózgu podczas abstynencji od substancji (PubMed Central)\n\nRegeneracja trwa\nWczesny wzrost objętości mózgu w pierwszych tygodniach jest dopiero początkiem. Przegląd pokazuje, że przy utrzymanej abstynencji mózg nadal regeneruje się strukturalnie i funkcjonalnie: odbudowuje się istota szara, a uszkodzone drogi istoty białej, koordynujące komunikację między obszarami mózgu, naprawiają się przez kolejne miesiące.\n\nPrzednia część mózgu\nSzczególnie ważna jest regeneracja obszarów czołowych odpowiedzialnych za ocenę sytuacji, planowanie i samokontrolę. Gdy się poprawiają, wzmacniają się podejmowanie decyzji i kontrola impulsów.\n\nReorganizacja i funkcja mózgu\nWraz z fizyczną naprawą poprawiają się również funkcje i połączenia mózgu. Mózg potrafi reorganizować swoje sieci i uczyć się na nowo, dlatego trwała abstynencja jest ważnym okresem dla terapii i budowania nowych nawyków.\n\nSygnał regeneracji\nPo sześciu miesiącach struktura i funkcja mózgu wyraźnie zmierzają w zdrowszym kierunku. Dalsza abstynencja daje tej regeneracji więcej czasu.';

  @override
  String get alcoholReferenceDay365 =>
      'Alkohol, ryzyko raka i zaprzestanie picia\n\nŹródło: National Cancer Institute (NCI), \"Alcohol and Cancer Risk\"\n\nAlkohol powoduje raka\nNCI stwierdza, że istnieje silny konsensus naukowy, iż picie alkoholu może powodować raka. Alkohol jest związany z nowotworami jamy ustnej, gardła, krtani, przełyku, wątroby, piersi oraz jelita grubego i odbytnicy. Im więcej i dłużej ktoś pije, tym wyższe jest ryzyko.\n\nJak alkohol zwiększa ryzyko raka\nMechanizmy obejmują aldehyd octowy, toksyczny produkt rozkładu alkoholu uszkadzający DNA, stres oksydacyjny i stan zapalny, gorsze wchłanianie ochronnych składników odżywczych oraz podwyższenie poziomu estrogenu w przypadku raka piersi.\n\nRyzyko spada po zaprzestaniu picia\nNCI podaje, że rezygnacja z alkoholu wiąże się z obniżaniem ryzyka w czasie. Badania pokazują, że podwyższone ryzyko raka jamy ustnej i przełyku zmniejsza się po zaprzestaniu picia, choć zbliżenie się do ryzyka osoby, która nigdy nie piła, może trwać latami. Rok bez alkoholu to znaczący krok na tej drodze.\n\nKorzyści się sumują\nPo roku utrwalają się również korzyści sercowo-naczyniowe i wątrobowe abstynencji, takie jak niższe ciśnienie, mniejsze ryzyko arytmii i dalsza regeneracja wątroby, obok stopniowego spadku ryzyka raka.';

  @override
  String get benzodiazepineReferenceDay7 =>
      'Odstawienie benzodiazepin: pierwszy tydzień\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings\", Światowa Organizacja Zdrowia (2009), NCBI Bookshelf\n\nBezpieczeństwo przede wszystkim\nOdstawienie benzodiazepin może wywołać napady drgawkowe. WHO wskazuje, że najbezpieczniejsze postępowanie polega na stopniowym zmniejszaniu dawki benzodiazepiny; łagodzi to objawy odstawienne i pomaga zapobiegać napadom. Po długotrwałym stosowaniu nie odstawiaj leku nagle — zmniejszaj dawkę z pomocą personelu medycznego.\n\nKiedy zaczyna się odstawienie\nWedług WHO czas zależy od długości działania leku:\n• Krótko działające (oxazepam, alprazolam, temazepam): zwykle 1–2 dni po ostatniej dawce, przez 2–4 tygodnie lub dłużej\n• Długo działające (diazepam, nitrazepam): zwykle 2–7 dni po ostatniej dawce, przez 2–8 tygodni lub dłużej\nPierwszy tydzień obejmuje typowe okno początku objawów także dla długo działających benzodiazepin.\n\nJak mogą wyglądać objawy\nWHO wymienia lęk, bezsenność, niepokój ruchowy, pobudzenie lub drażliwość, problemy z koncentracją lub pamięcią oraz napięcie lub bóle mięśni.\n\nMonitorowanie\nNasilenie objawów może znacznie się wahać. WHO zaleca regularne monitorowanie objawów i powikłań; w protokole dla placówek zamkniętych personel rozmawia z pacjentem co 3–4 godziny, uspokaja go i w razie potrzeby wyjaśnia objawy.';

  @override
  String get benzodiazepineReferenceDay14 =>
      'Odstawienie benzodiazepin: dwa tygodnie\n\nŹródło: Poyares i wsp., \"Chronic benzodiazepine usage and withdrawal in insomnia patients\", Journal of Psychiatric Research (2004), PubMed\n\nRzeczywisty sygnał poprawy po około dwóch tygodniach\nBadacze obserwowali osoby z przewlekłą bezsennością, które przez lata przyjmowały benzodiazepiny każdej nocy, i ponownie zbadali ich sen 15 dni po stopniowym odstawieniu. W porównaniu z okresem przewlekłego stosowania benzodiazepin poprawiły się sen wolnofalowy, aktywność delta w EEG snu oraz zgłaszana jakość snu.\n\nGłęboki sen wraca\nSen wolnofalowy jest najgłębszym etapem snu NREM. Do 15. dnia zwiększyły się sen wolnofalowy i aktywność delta, a sen NREM w stadium 2 zmniejszył się w kierunku wzorca obserwowanego u zdrowych osób z grupy kontrolnej.\n\nWczesna poprawa potwierdzona pomiarem\nU uczestników, którzy ukończyli odstawianie, sen pogorszył się bezpośrednio po odstawieniu, ale do kontroli w 15. dniu poprawiły się obiektywne wskaźniki głębokiego snu i zgłaszana jakość snu. Dzięki temu dwa tygodnie są rzeczywistym, zmierzonym kamieniem milowym regeneracji.';

  @override
  String get benzodiazepineReferenceDay60 =>
      'Benzodiazepiny: funkcjonowanie w dzień po ośmiu tygodniach\n\nŹródło: Tsunoda i wsp., \"Effects of discontinuing benzodiazepine-derivative hypnotics on postural sway and cognitive functions in the elderly\", International Journal of Geriatric Psychiatry (2010), PubMed\n\nMierzalny sygnał poprawy po ośmiu tygodniach\nBadacze obserwowali dorosłych w wieku 60 lat i starszych mieszkających w domu opieki, którzy stosowali nasenne benzodiazepiny. Dawki stopniowo zmniejszano do odstawienia przez trzy tygodnie, a pod koniec ósmego tygodnia ponownie wykonano testy poznawcze i równowagi.\n\nSkupienie i pamięć poszły w górę\nWśród 26 osób, które ukończyły badanie, istotnie poprawiły się wyniki pamięci bezpośredniej, uwagi i języka. To konkretne, zmierzone korzyści w funkcjonowaniu dziennym po odstawieniu benzodiazepin.\n\nPewniej na nogach\nIstotnie poprawiły się też pomiary wychyleń postawy przy zamkniętych oczach. Autorzy uznali, że odstawienie nasennych benzodiazepin w tej starszej grupie wiązało się z lepszą stabilnością ciała i poprawą dziennych funkcji poznawczych.\n\nSen pozostał stabilny\nOsoby, które ukończyły badanie, nie zgłaszały subiektywnego pogorszenia snu w zastosowanym kwestionariuszu. W ósmym tygodniu badanie wykazało mierzalne korzyści w ciągu dnia bez zgłaszanego pogorszenia jakości snu.';

  @override
  String get benzodiazepineReferenceDay90 =>
      'Trzy miesiące po benzodiazepinach: szybsze myślenie, mniej sedacji\n\nŹródło: Rickels et al., \"Psychomotor performance of long-term benzodiazepine users before, during, and after benzodiazepine discontinuation,\" Journal of Clinical Psychopharmacology (1999), w PubMed\n\nMierzalny sygnał poprawy po 12 tygodniach\nBadacze testowali osoby długotrwale stosujące benzodiazepiny przed stopniowym odstawianiem oraz 5 i 12 tygodni później. Dane z 12. tygodnia były dostępne dla 77 osób, a u osób, które skutecznie odstawiły lek, brak benzodiazepin potwierdzano cotygodniowymi badaniami krwi.\n\nSzybsze wykonywanie zadań poznawczych\nOsoby, które skutecznie odstawiły benzodiazepiny, szybciej wykonywały zadania kopiowania symboli i zastępowania cyfr symbolami niż uczestnicy nadal przyjmujący benzodiazepiny. Różnica pozostawała istotna po uwzględnieniu wieku, wykształcenia i wyników wyjściowych.\n\nMniej sedacji psychicznej i fizycznej\nOsoby po skutecznym odstawieniu zgłaszały też mniejszą sedację psychiczną i fizyczną niż osoby nadal przyjmujące benzodiazepiny.\n\nJak mogą wyglądać trzy miesiące\nW tej grupie skutecznego odstawienia 12 tygodni po taperze odnotowano mierzalną poprawę szybkości przetwarzania i mniejszą sedację psychiczną oraz fizyczną. Myślenie było szybsze, a uczucie otępienia słabło.';

  @override
  String get benzodiazepineReferenceDay180 =>
      'Myślenie i pamięć po sześciu miesiącach: mierzalna poprawa\n\nŹródło: Tata i wsp., \"Lack of cognitive recovery following withdrawal from long-term benzodiazepine use,\" Psychological Medicine (1994), PubMed\n\nCo zrobiono w badaniu\nBadanie objęło 21 osób długotrwale przyjmujących benzodiazepiny. Testowano je przed odstawieniem, bezpośrednio po nim i ponownie po sześciu miesiącach bez benzodiazepin, porównując wyniki z dopasowaną grupą kontrolną.\n\nCo wykazano\nPrzed odstawieniem uczestnicy mieli trudności z uczeniem werbalnym, pamięcią, szybkością ruchów, koordynacją wzrokową i rozumowaniem wzrokowym. Bezpośrednio po odstawieniu zmiany były niewielkie. Po sześciu miesiącach kilka z tych obszarów poprawiło się w sposób mierzalny.\n\nCo to oznacza\nPo sześciu miesiącach mierzalnie poprawiały się uczenie werbalne, pamięć, szybkość ruchów i koordynacja wzrokowa. Poprawa była już wyraźna i mogła postępować dalej.\n\nSzerszy obraz\nJeśli po sześciu miesiącach nadal odczuwasz zamglenie, wyniki tego badania są z tym zgodne. Długoterminowe badania pokazują, że regeneracja może trwać także po tym punkcie.';

  @override
  String get benzodiazepineReferenceDay365 =>
      'Rok po benzodiazepinach: myślenie i pamięć nadal się poprawiają\n\nŹródło: Barker i wsp., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), PubMed\n\nNajmocniejsze dostępne dane\nBadacze połączyli badania, w których ponownie oceniano osoby po długotrwałym stosowaniu benzodiazepin co najmniej sześć miesięcy po odstawieniu. Łączny wynik pokazuje wyraźną poprawę myślenia i pamięci.\n\nDobra wiadomość\nPołączone badania wykazały rzeczywistą, mierzalną poprawę w kilku obszarach poznawczych po odstawieniu. Około roku zakres poprawy jest szeroki w porównaniu z okresem aktywnego stosowania.\n\nRegeneracja trwa\nBadania wskazują na szeroką poprawę myślenia i pamięci. Po roku jesteś daleko na ścieżce poprawy, która była już mierzalna po sześciu miesiącach.\n\nCo oznacza rok\nOkoło roku można oczekiwać znacznej poprawy myślenia, pamięci i jasności umysłu. Jeśli niektóre obszary nadal pozostają słabsze, jest to zgodne z dowodami; regeneracja może trwać dalej.';

  @override
  String get benzodiazepineReferenceDay540 =>
      '18 miesięcy po benzodiazepinach: powolna, ale realna regeneracja\n\nŹródło: Ashton, \"Protracted withdrawal syndromes from benzodiazepines,\" Journal of Substance Abuse Treatment (1991), PubMed\n\nDlaczego regeneracja trwa długo\nBenzodiazepiny działają na GABA, główny układ hamujący mózgu. Długotrwałe stosowanie zmienia jego reakcję, a odwracanie tych zmian może trwać miesiące. Dlatego proces regeneracji liczy się raczej w miesiącach niż tygodniach.\n\nGdzie wypada 18 miesięcy\nAshton opisuje przedłużone objawy odstawienne, które mogą ustępować przez wiele miesięcy. Po 18 miesiącach najtrudniejszy okres jest u większości osób daleko w przeszłości, a utrzymujący się lęk, zmiany czuciowe i zamglenie umysłu zwykle znacznie słabną.\n\nPowoli odwracalne\nAshton określa leżące u podstaw procesu zmiany jako \"powoli odwracalne zmiany czynnościowe w ośrodkowym układzie nerwowym\". Długi czas odzwierciedla głębokość adaptacji do benzodiazepin, a nie trwałe uszkodzenie u większości osób.\n\nSygnał regeneracji\nPo 18 miesiącach układ GABA miał dużo czasu na dostosowanie. Główny kierunek to dalsza regeneracja w stronę bardziej typowego funkcjonowania.';

  @override
  String get benzodiazepineReferenceDay730 =>
      'Dwa lata po benzodiazepinach: duży, trwały postęp\n\nŹródło: Barker i wsp., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), PubMed\n\nWażny etap regeneracji\nDwa lata to ważny kamień milowy, szczególnie po długim okresie odstawienia. Wczesne i przedłużające się fazy objawów są już daleko w przeszłości, a postęp z pierwszego roku miał kolejny rok na utrwalenie.\n\nCo wspierają dowody\nPołączone badania pokazują poprawę w wielu obszarach po odstawieniu. Po dwóch latach dowody wspierają obraz trwałej regeneracji snu, nastroju, pamięci i jasności myślenia, choć tempo różni się między osobami.\n\nSygnał regeneracji\nPołączone badania wskazują na poprawę w wielu obszarach myślenia i pamięci. Po dwóch latach trwała regeneracja jest oczekiwaniem zgodnym z dowodami.\n\nZachowanie perspektywy\nDwa lata dają dużo czasu na poprawę snu, nastroju, pamięci i jasności myślenia. Dowody pokazują znaczący postęp, który może trwać dalej.';

  @override
  String get benzodiazepineReferenceDay1095 =>
      'Trzy lata po benzodiazepinach: długoterminowa regeneracja\n\nŹródło: Barker i wsp., \"Persistence of cognitive effects after withdrawal from long-term benzodiazepine use: a meta-analysis,\" Archives of Clinical Neuropsychology (2004), PubMed\n\nDługoterminowa perspektywa\nTrzy lata to już odległy punkt na ścieżce regeneracji po benzodiazepinach. U zdecydowanej większości osób, nawet po ciężkim i przedłużonym odstawieniu, najbardziej zakłócające objawy są daleko w przeszłości, a jakość życia może być bardzo różna od okresu aktywnego stosowania.\n\nCo wykazała metaanaliza\nPołączone badania osób długotrwale stosujących benzodiazepiny pokazują poprawę w wielu obszarach po odstawieniu. W kolejnych latach dominującym obrazem jest szeroka poprawa myślenia, pamięci i codziennego funkcjonowania.\n\nSygnał regeneracji\nBadania długoterminowe pokazują poprawę wielu obszarów myślenia i pamięci. Po trzech latach wczesne i przedłużone fazy odstawienia są daleko w przeszłości, a wcześniejszy postęp miał lata na utrwalenie.\n\nPrzesłanie nadziei\nRegeneracja po benzodiazepinach może być wymagającym procesem. Trzy lata trwałej zmiany to duże osiągnięcie, a poprawa może postępować wraz z upływem czasu.';

  @override
  String get benzodiazepineReferenceDay1460 =>
      'Cztery lata po benzodiazepinach: trwały postęp\n\nŹródło: Wspólne wytyczne praktyki klinicznej dotyczące stopniowego odstawiania benzodiazepin, wielodyscyplinarne wytyczne pod przewodnictwem ASAM (2025)\n\nCo potwierdzają wytyczne\nWytyczne wskazują, że adaptacja po odstawieniu może trwać znacznie dłużej niż usuwanie leku z organizmu. U części osób przedłużone objawy odstawienne mogą utrzymywać się miesiącami lub latami, dlatego zdrowienie powinno być monitorowane i wspierane indywidualnie.\n\nCo oznaczają cztery lata\nWytyczne nie określają uniwersalnego biologicznego punktu końcowego po czterech latach. Ten kamień milowy bez przesady celebruje więc cztery lata trwałej zmiany, pozwalając zdrowieniu przebiegać we własnym tempie.\n\nKamień milowy wart świętowania\nCztery lata to 1 460 dni. To trwałe osiągnięcie niezależnie od tego, czy zdrowienie było płynne, nierówne czy gdzieś pośrodku.';

  @override
  String get benzodiazepineReferenceDay1825 =>
      'Pięć lat po benzodiazepinach: długoterminowe osiągnięcie\n\nŹródło: Wspólne wytyczne praktyki klinicznej dotyczące stopniowego odstawiania benzodiazepin, wielodyscyplinarne wytyczne pod przewodnictwem ASAM (2025)\n\nNie ma jednej mety\nWytyczne podkreślają, że odstawienie benzodiazepin i adaptacja po ich zakończeniu różnią się między ludźmi. Nie wyznaczają uniwersalnego punktu po pięciu latach, w którym mózg lub ciało uznaje się za całkowicie zregenerowane.\n\nCo oznacza pięć lat\nPięć lat to prawdziwa długoterminowa rocznica: 1 825 dni trwałej zmiany, podczas których nawyki, wsparcie i codzienne życie miały lata, by się zakorzenić.\n\nDoceniaj wykonaną pracę\nTen kamień milowy celebruje sam wysiłek, a nie wymyślony medyczny termin. Pięć lat trwałego postępu jest znaczące samo w sobie.';

  @override
  String get cocaineReferenceDay1 =>
      'Odstawienie kokainy: Pierwsze 24 godziny\n\nŹródło: \"Withdrawal Syndromes\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nKokaina i mózg\nKokaina blokuje wychwyt zwrotny dopaminy i innych monoamin w obwodach nagrody mózgu, powodując nagromadzenie dopaminy oraz intensywną euforię i pobudzenie. Przy regularnym używaniu mózg przystosowuje się, osłabiając aktywność tego układu, dlatego zwykłe czynności mogą bez substancji wydawać się mniej satysfakcjonujące.\n\nFaza „crash”\nStatPearls opisuje początek odstawienia stymulantów jako fazę „crash” po zaprzestaniu używania. Charakteryzują ją nasilona depresja, nadmierna senność, głód, obniżony nastrój oraz wyraźne spowolnienie ruchowe i myślowe. W pierwszych 24 godzinach zwykle obejmuje to:\n• Skrajne zmęczenie i zwiększoną potrzebę snu\n• Obniżony nastrój oraz wolniejsze poruszanie się i myślenie\n• Zwiększony apetyt, ponieważ kokaina go hamuje\n\nSilny głód kokainy, drażliwość i lęk są także bardzo często opisywane w tym okresie w szerszej literaturze dotyczącej uzależnień, choć StatPearls nie wymienia ich osobno jako części fazy „crash”.\n\nInaczej niż w przypadku niektórych innych substancji\nStatPearls wskazuje, że odstawienie stymulantów leczy się poprzez obserwację i opiekę wspomagającą. W przeciwieństwie do odstawienia alkoholu lub benzodiazepin zwykle nie powoduje ono drgawek ani majaczenia. Główne zagrożenie ma charakter psychiczny: podczas fazy „crash” może wystąpić depresja, a u osób intensywnie używających także myśli samobójcze, dlatego zalecane są wsparcie i monitorowanie.\n\nBrak zatwierdzonego leku\nObecnie nie ma leków zatwierdzonych specjalnie do leczenia odstawienia kokainy. Postępowanie ma charakter wspomagający, a niefarmakologiczne metody, takie jak terapia oparta na zarządzaniu wzmocnieniami, należą do metod o potwierdzonej skuteczności w leczeniu zaburzenia używania substancji.';

  @override
  String get cocaineReferenceDay3 =>
      'Trzy dni bez kokainy: Najtrudniejszy etap\n\nŹródło: \"Cocaine Toxicity\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nJak kokaina wpływa na organizm\nStatPearls opisuje, że kokaina blokuje wychwyt zwrotny dopaminy, noradrenaliny i serotoniny, przedłużając pobudzenie układu współczulnego. To odpowiada zarówno za euforię, jak i za zagrożenia, ponieważ kokaina może wpływać niemal na każdy układ narządów.\n\nDni 2–4: Szczyt objawów psychicznych\nDo trzeciego dnia ostra faza „crash” zwykle przechodzi w najbardziej nasilony etap psychicznych objawów odstawienia:\n• Obniżony i depresyjny nastrój o największym nasileniu\n• Utrata zdolności odczuwania przyjemności\n• Silny głód wywoływany przez bodźce i sytuacje skojarzone z używaniem\n• Lęk i niepokój\n• Zaburzenia snu — u części osób nadmierna senność, u innych bezsenność\n\nRyzyko sercowo-naczyniowe maleje\nStatPearls określa toksyczność sercowo-naczyniową jako najbardziej śmiertelne działanie kokainy: wzrost tętna i ciśnienia krwi, zwiększone zapotrzebowanie mięśnia sercowego na tlen, skurcz naczyń wieńcowych i aktywacja płytek zwiększają ryzyko arytmii, zawału i udaru nawet u młodych osób. Sama kokaina ma krótki okres półtrwania, około godziny, i do trzeciego dnia jest już usunięta z organizmu. StatPearls zaznacza jednak, że metabolity mogą jeszcze przez kilka godzin powodować zwężenie naczyń, a jeden z nich może utrzymywać się przez tygodnie, więc część obciążenia układu sercowo-naczyniowego może trwać dłużej niż obecność samej kokainy.\n\nDalsza droga\nOstra faza jest intensywna, ale to objawy psychiczne — depresja, głód kokainy i utrata przyjemności — zwykle wymagają najwięcej wsparcia i mogą utrzymywać się najdłużej.';

  @override
  String get cocaineReferenceDay7 =>
      'Tydzień bez kokainy: Początek regeneracji fizycznej\n\nŹródło: \"Withdrawal Syndromes\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nOstra faza dobiega końca\nStatPearls opisuje przejście od początkowej fazy „crash” do dłuższego okresu zdrowienia. Pod koniec pierwszego tygodnia najgorsze objawy zwykle zaczynają słabnąć, a układ dopaminowy nadal się regeneruje.\n\nRegeneracja fizyczna trwa\nPo ustaniu pobudzenia układu współczulnego wywołanego kokainą jej wpływ na układ sercowo-naczyniowy, apetyt, sen i drogi oddechowe zaczyna się odwracać w kolejnych dniach i tygodniach:\n• Tętno i ciśnienie krwi przesuwają się w stronę wartości prawidłowych\n• Apetyt stopniowo wraca, ponieważ kokaina silnie go hamuje\n• Rytm snu zaczyna się stabilizować\n• Błona śluzowa nosa zaczyna się goić, jeśli kokaina była wciągana przez nos\n\nObjawy psychiczne mogą trwać dłużej\nStatPearls wskazuje, że depresja i utrata przyjemności są typowe dla odstawienia stymulantów i mogą utrzymywać się dłużej niż objawy fizyczne:\n• Nastrój pozostaje obniżony, choć zwykle mniej niż w szczycie objawów\n• Głód wywołany bodźcami nadal może być silny\n• Koncentracja i motywacja pozostają osłabione\n\nFaza po ostrym odstawieniu\nNastępnie zdrowienie przechodzi w tygodnie lub miesiące wolniejszej, stopniowej poprawy nastroju, głodu i jasności myślenia. Znajomość tego przebiegu pomaga lepiej rozumieć wolniejszą część procesu.';

  @override
  String get cocaineReferenceDay14 =>
      'Dwa tygodnie bez kokainy: Więcej stabilności\n\nŹródło: \"Withdrawal Syndromes\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nDwa tygodnie\nPo dwóch tygodniach ciężkie objawy fazy „crash” — głęboka depresja, nadmierna senność oraz spowolnienie ruchowe i myślowe — zwykle wyraźnie słabną. Zdrowienie coraz bardziej koncentruje się na odbudowie zdrowia mózgu i równowagi emocjonalnej.\n\nNastrój i emocje\nPo dwóch tygodniach nastrój może nadal być niższy niż zwykle, podczas gdy układ dopaminowy się regeneruje. W porównaniu z pierwszym tygodniem głęboka utrata przyjemności zaczyna ustępować i wracają autentyczne chwile dobrego samopoczucia.\n\nGłód i wyzwalacze\nGłód wywołany bodźcami pozostaje ważnym wyzwaniem. Mózg tworzy silne skojarzenia między używaniem kokainy a określonymi miejscami, osobami, emocjami i czynnościami. Kontakt z takimi wyzwalaczami może powodować silny głód nawet wtedy, gdy ogólny nastrój się poprawia. Ważne jest unikanie środowisk wysokiego ryzyka i budowanie nowych skojarzeń.\n\nLepszy sen\nPo dwóch tygodniach sen jest zwykle bardziej stabilny i regenerujący niż w ostrej fazie odstawienia. Lepszy sen wspiera nastrój, jasność myślenia i zdolność radzenia sobie z głodem.\n\nBudowanie podstaw\nPonieważ metody o potwierdzonej skuteczności w leczeniu zaburzeń używania stymulantów mają charakter behawioralny — obejmują m.in. zarządzanie wzmocnieniami, terapię i wsparcie rówieśnicze — etap dwóch tygodni jest dobrym momentem na korzystanie ze struktur wsparcia, które mogą wzmacniać długotrwałe zdrowienie.';

  @override
  String get cocaineReferenceDay60 =>
      'Dwa miesiące bez kokainy: Nastrój i układ nagrody zaczynają się regenerować\n\nŹródło: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\nCo dzieje się w mózgu\nTen przegląd podsumowuje badania na ludziach i zwierzętach dotyczące zmian w mózgu po zaprzestaniu używania kokainy. Przewlekłe używanie kokainy zmienia układ dopaminowy i zmniejsza aktywność kory czołowej; regeneracja tych układów stanowi podłoże poprawy nastroju i motywacji obserwowanej we wczesnej abstynencji.\n\nPostęp układu nagrody\nW badaniach na zwierzętach zmiany receptorów dopaminowych i białek transportujących związane z kokainą przesuwały się z czasem w stronę zdrowych wartości podczas utrzymywania abstynencji. Wraz z regeneracją układu nagrody głęboka utrata przyjemności słabnie, a codzienne nagrody — jedzenie, relacje i osiągnięcia — znów mogą być odczuwane jako satysfakcjonujące.\n\nSygnał zdrowienia\nPo dwóch miesiącach nastrój się poprawia, a sen jest stabilniejszy, podczas gdy układ dopaminowy i kora czołowa nadal się regenerują. Badania na naczelnych pokazują, że związane z kokainą zmiany receptorów D1 i transporterów przy utrzymanej abstynencji przesuwają się z powrotem w kierunku wartości kontrolnych.';

  @override
  String get cocaineReferenceDay90 =>
      'Trzy miesiące bez kokainy: Odbudowa markerów dopaminowych\n\nŹródło: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\nDlaczego 90 dni ma znaczenie\nPrzegląd wskazuje punkt trzech miesięcy jako biologicznie istotny. U naczelnych innych niż ludzie receptory dopaminowe D1 i transportery, których poziom wzrósł pod wpływem kokainy, po około 90 dniach abstynencji wykazywały oznaki powrotu do wartości kontrolnych. To bezpośredni dowód, że układ nagrody może ponownie się dostosowywać po odstawieniu substancji.\n\nPrzednia część mózgu\nAutorzy podkreślają regenerację przednich obszarów mózgu jako jeden z ważnych sygnałów dłuższej abstynencji. Obszary te wspierają kontrolę impulsów, podejmowanie decyzji i samokontrolę, a zdolności te wzmacniają się wraz z ich regeneracją.\n\nCo pokazują 90 dni\nPo 90 dniach w badaniach na naczelnych gęstość receptorów D1, D2 i transporterów dopaminy nie różniła się już istotnie od wartości w grupie kontrolnej bez ekspozycji na narkotyk. Nawet po długiej ekspozycji znaczna regeneracja układu dopaminowego jest widoczna już na tym etapie i postępuje wraz z abstynencją.';

  @override
  String get cocaineReferenceDay180 =>
      'Sześć miesięcy bez kokainy: Jaśniejsze myślenie\n\nŹródło: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies\", PubMed Central\n\nRegeneracja widoczna w obrazowaniu\nTen przegląd łączy podłużne badania neuroobrazowe, w których te same osoby są wielokrotnie badane w miarę wydłużania abstynencji. W odniesieniu do kokainy opisuje mierzalną poprawę aktywności funkcjonalnej wraz z utrzymywaną abstynencją.\n\nDowody z obrazowania mózgu\nDwa badania fMRI śledziły osoby używające kokainy w czasie i oba wykazały poprawę aktywacji śródmózgowia i wzgórza przy dłuższej abstynencji. W jednym z nich po około sześciu miesiącach wzorzec aktywacji mózgu był porównywalny z wzorcem u zdrowych osób z grupy kontrolnej bez uzależnienia. W odniesieniu do różnych substancji przegląd wskazuje również, że wyniki obrazowania nuklearnego sugerują regenerację dopaminergiczną podczas abstynencji.\n\nCo to oznacza po sześciu miesiącach\nTe funkcjonalne zmiany odpowiadają poprawie obserwowanej przez ludzi na tym etapie:\n• Lepsza uwaga i pamięć robocza\n• Sprawniejsze podejmowanie decyzji i kontrola impulsów\n• Stabilniejszy nastrój i regulacja emocji\n\nSygnał zdrowienia\nPo około sześciu miesiącach jedna podłużna kohorta fMRI wykazywała wzorzec aktywacji porównywalny ze zdrową grupą kontrolną bez uzależnienia, a aktywacja śródmózgowia i głębszych obszarów mózgu poprawiała się wraz z długością abstynencji. To bezpośrednio zobrazowana funkcjonalna regeneracja mózgu.';

  @override
  String get cocaineReferenceDay365 =>
      'Rok bez kokainy: Koniec powtarzającego się obciążenia serca\n\nŹródło: \"Cocaine Toxicity\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nDlaczego serce jest tak ważne\nStatPearls określa toksyczność sercowo-naczyniową jako najbardziej śmiertelne działanie kokainy. Każde użycie zwiększa tętno, ciśnienie krwi i zapotrzebowanie mięśnia sercowego na tlen, a jednocześnie wywołuje skurcz naczyń wieńcowych i sprzyja tworzeniu zakrzepów. To połączenie zwiększa ryzyko zawału, arytmii i udaru nawet u młodych osób.\n\nCo usuwa rok abstynencji\nKażdy dzień bez kokainy to dzień bez tych ostrych obciążeń. Przez rok nie występują powtarzane skoki ciśnienia i tętna wywołane używaniem, nie pojawia się ryzyko nowego kokainowego skurczu naczyń wieńcowych i ostrego zawału z kolejnej dawki, a serce nie jest wielokrotnie narażane na niedopasowanie zapotrzebowania na tlen do jego podaży.\n\nSygnał zdrowienia\nZaprzestanie kokainy zatrzymuje powtarzające się skurcze naczyń wieńcowych, tachykardię, nadciśnienie, nasilenie krzepnięcia i zaburzenia bilansu tlenowego prowadzące do ostrego uszkodzenia serca. Istniejące zwłóknienie lub zapalenie mięśnia sercowego nadal wymagają uwagi medycznej, ale powtarzające się uszkodzenia wywoływane przez kokainę ustają.\n\nTakże mózg się regeneruje\nPo roku układy nagrody i samokontroli miały długi czas na regenerację, co wspiera lepszą kontrolę impulsów, stabilniejszy nastrój i silniejszą reakcję na codzienne nagrody.';

  @override
  String get cocaineReferenceDay730 =>
      'Dwa lata bez kokainy: Trwałe zdrowienie\n\nŹródło: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\nPerspektywa długoterminowa\nTen przegląd podsumowuje wyniki badań na ludziach i zwierzętach dotyczących przedłużonej abstynencji od kokainy. Główny wniosek jest taki, że zachowanie i odzyskiwanie funkcji kory czołowej należą do najważniejszych wskaźników długotrwałej abstynencji. Osoby pozostające w abstynencji ponad 10 miesięcy wykazywały większą aktywność kory czołowej niż osoby z krótszym okresem abstynencji.\n\nCo nadal się poprawia\n• Markery dopaminowe zmienione przez kokainę nadal zbliżają się do wartości prawidłowych wraz z utrzymywaniem abstynencji\n• Obniżona integralność istoty szarej i białej obserwowana podczas aktywnego używania i we wczesnej abstynencji może poprawiać się przy dłuższej abstynencji, być może dzięki dalszemu dojrzewaniu mieliny\n• Wzmacniają się obwody kontroli czołowej związane z kontrolą impulsów, oceną sytuacji i regulacją emocji\n\nSygnał zdrowienia\nAutorzy wskazują na ważne zastrzeżenie naukowe: część różnic u osób długotrwale abstynentnych może odzwierciedlać \"efekt przeżycia\". Osobom, które od początku miały lepszą integralność mózgu, mogło być łatwiej utrzymać abstynencję, więc nie wszystkie różnice można przypisać samemu zdrowieniu. Jasne jest, że dwa lata bez kokainy wspierają funkcjonowanie mózgu znacznie bliższe temu u osoby nieużywającej kokainy oraz życie, które nie jest jedynie abstynentne, lecz zostało w dużej mierze odbudowane.';

  @override
  String get cocaineReferenceDay1095 =>
      'Trzy lata bez kokainy: Mocny fundament\n\nŹródło: SAMHSA, Treatment of Stimulant Use Disorders\n\nPrzewodnik SAMHSA wyraźnie obejmuje kokainę i oparte na dowodach praktyki wspierające długoterminowe zdrowienie. Nie wyznacza uniwersalnej biologicznej granicy po trzech latach.\n\nTrzy lata to trwałe osiągnięcie samo w sobie. Chroń rutyny, wsparcie i strategie, które podtrzymują zdrowienie.';

  @override
  String get cocaineReferenceDay1460 =>
      'Cztery lata bez kokainy: Trwały rozpęd\n\nŹródło: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA opisuje oparte na dowodach podejścia do zaburzeń związanych ze stymulantami, w tym kokainą, wspierające długoterminowe zdrowienie. Nie wskazuje uniwersalnego medycznego punktu końcowego po czterech latach.\n\nCztery lata pokazują zmianę utrzymaną w zwykłe dni, trudne okresy i ważne chwile.';

  @override
  String get cocaineReferenceDay1825 =>
      'Pięć lat bez kokainy: Utrwalona zmiana\n\nŹródło: SAMHSA, Treatment of Stimulant Use Disorders\n\nPrzewodnik SAMHSA wspiera opartą na dowodach opiekę ukierunkowaną na długoterminowe zdrowienie z zaburzeń związanych ze stymulantami, w tym kokainą. Pięć lat nie jest przedstawiane jako biologiczna linia mety.\n\nPięć lat to pół dekady utrzymanej zmiany. Ta konsekwencja i zbudowane wokół niej życie są właściwym kamieniem milowym.';

  @override
  String get ghbReferenceDay1 =>
      'Odstawienie GHB: pierwsze godziny\n\nŹródło: „Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\n⚠ To nagły stan medyczny\nOdstawienie GHB należy do najniebezpieczniejszych zespołów odstawiennych i może dorównywać ciężkiemu odstawieniu alkoholu lub benzodiazepin. Bez leczenia w ponad połowie przypadków może rozwinąć się majaczenie, z groźnymi wahaniami tętna i ciśnienia tętniczego oraz napadami drgawkowymi. Osoba zależna od GHB, GBL lub 1,4-butanodiolu powinna szukać nadzorowanego leczenia stacjonarnego zamiast odstawiać samodzielnie.\n\nDlaczego zaczyna się tak szybko\nOkres półtrwania GHB wynosi tylko 30–60 minut. Osoby zależne często muszą przyjmować kolejną dawkę co 2–3 godziny tylko po to, by uniknąć objawów odstawienia — znacznie częściej niż w przypadku alkoholu lub benzodiazepin. Ta szybka farmakokinetyka sprawia, że objawy mogą pojawić się dużo wcześniej niż przy odstawieniu innych leków uspokajająco-nasennych.\n\nWczesne objawy\nLęk, bezsenność, drżenie, pocenie się, przyspieszone tętno i wzrost ciśnienia tętniczego.';

  @override
  String get ghbReferenceDay3 =>
      'Odstawienie GHB: najtrudniejsze dni\n\nŹródło: „Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nNajtrudniejszy okres\nBadanie wykazało, że kilka głównych objawów odstawienia — bóle mięśni, drgania mięśni, poczucie napięcia i stresu, przyspieszone tętno oraz skurcze brzucha — było najsilniejszych w pierwszych trzech dniach. Do czwartego dnia nasilenie wielu objawów spadło o ponad 70%. Ten wczesny okres jest zwykle obarczony największym ryzykiem, bo nieleczone odstawienie może wtedy najłatwiej przejść w majaczenie, napady drgawkowe albo niebezpieczne wahania tętna i ciśnienia.\n\nCiężkie objawy\n• Silne pobudzenie i lęk\n• Omamy słuchowe i wzrokowe, paranoja\n• Drżenie, pocenie się, kołatanie serca i wysokie ciśnienie\n• Ryzyko napadów drgawkowych\n\nPostępowanie\nBadanie opisuje stopniowe zmniejszanie dawek benzodiazepin oraz farmaceutycznego GHB jako dwie często stosowane metody detoksykacji. Istnieją pewne dane, że stopniowe zmniejszanie GHB może kontrolować objawy skuteczniej niż same benzodiazepiny. Obie metody wymagają ścisłego nadzoru — nie jest to bezpieczne do prowadzenia w domu.';

  @override
  String get ghbReferenceDay7 =>
      'Tydzień bez GHB\n\nŹródło: „Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nWiększość objawów słabnie\nKilka głównych objawów odstawienia zmniejszyło się w pierwszych czterech dniach o ponad 70% pod względem nasilenia lub częstości. Przy nadzorowanym stopniowym zmniejszaniu dawki sama faza redukcji trwała średnio 11 dni, a następnie około sześciu dni trwała faza zdrowienia. Po tygodniu wiele osób jest więc już wyraźnie w fazie poprawy, nawet jeśli proces nie jest jeszcze zakończony.\n\nCo może się utrzymywać\n• Pocenie się, drżenie i drżenie rąk\n• Duża senność albo przeciwnie — bezsenność i niepokój\n• Głód GHB\n\nW badaniu objawy te zmieniały się stosunkowo niewiele nawet do 11. dnia, więc ich obecność po tygodniu nie jest niezwykła. Nadzór medyczny pozostaje ważny, dopóki zespół wyraźnie nie ustąpi.';

  @override
  String get ghbReferenceDay14 =>
      'Dwa tygodnie bez GHB\n\nŹródło: „Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nPo ostrej fazie\nPo dwóch tygodniach ostry zespół fizyczny opisany w badaniu zwykle już ustąpił albo jest bliski ustąpienia. Pod nadzorowanym leczeniem faza stopniowego zmniejszania i zdrowienia trwała łącznie średnio około 17 dni. Tętno, ciśnienie i większość objawów fizycznych powinny się stabilizować.\n\nCo może pozostać\nBadanie wskazuje, że u części pacjentów przy wypisie nadal występowały głód GHB i bezsenność, co może zwiększać ryzyko nawrotu. Wsparcie i uporządkowany rytm dnia są nadal ważne, nawet jeśli niebezpieczny początek jest już za Tobą.';

  @override
  String get ghbReferenceDay30 =>
      'Miesiąc bez GHB\n\nŹródło: „Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nCo oznacza miesiąc\nPo miesiącu opisana w badaniu ostra i niebezpieczna faza jest już dawno za Tobą. Koncentrowała się na pierwszych dniach, a po niej następował nadzorowany okres stopniowego zmniejszania i zdrowienia trwający średnio około dwóch i pół tygodnia. Głód GHB i bezsenność były głównymi pozostałymi czynnikami ryzyka nawrotu przy wypisie.\n\nDlaczego wsparcie nadal pomaga\nJeśli po miesiącu nadal występują głód GHB, obniżony nastrój lub problemy ze snem, odpowiada to czynnikom ryzyka nawrotu wskazanym przez autorów badania. Dlatego stałe wsparcie i uporządkowany rytm dnia nadal mają znaczenie.';

  @override
  String get ghbReferenceDay90 =>
      'Trzy miesiące bez GHB\n\nŹródło: „Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nTrzy miesiące zdrowienia\nPo trzech miesiącach ostry zespół odstawienia GHB jest już dawno zakończony. Przy wypisie jako pozostałe ryzyka wskazywano głód GHB i bezsenność. Trzy miesiące abstynencji dają dużo czasu na utrwalenie snu, stabilności autonomicznej i nawyków zapobiegających nawrotom.\n\nCo ludzie często zgłaszają\n• Spokojniejszy nastrój na co dzień\n• Bardziej regularny sen\n• Jaśniejsze myślenie i mniejszy głód GHB\n\nJeśli po trzech miesiącach lęk, bezsenność lub obniżony nastrój nadal są wyraźne, warto omówić to z lekarzem zamiast zakładać, że samo minie.';

  @override
  String get ghbReferenceDay180 =>
      'Sześć miesięcy bez GHB\n\nŹródło: „Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\nPół roku później\nPo sześciu miesiącach ostry zespół odstawienia GHB jest już dawno zakończony, a zdrowienie całkowicie przesuwa się z detoksykacji na stabilny sen, radzenie sobie z głodem i zapobieganie nawrotom. Niebezpieczna faza zaburzeń autonomicznych i ryzyka majaczenia dotyczy pierwszych dni i tygodni, a nie tego etapu.\n\nSzersza perspektywa\nBezpieczne przejście przez odstawienie GHB i pół roku bez używania to duże osiągnięcie, biorąc pod uwagę zagrożenia wczesnej fazy oraz realne ryzyko nawrotu, częściowo związane z utrzymującym się głodem i bezsennością. Warto zachować rutyny i wsparcie, które pomogły Ci dojść aż tutaj.';

  @override
  String get inhalantsReferenceDay1 =>
      'Odstawienie inhalantów: pierwszy dzień\n\nŹródło: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), PubMed Central\n\nDlaczego pojawia się odstawienie\nPrzewlekłe używanie inhalantów prowadzi do neuroadaptacji — układ nerwowy przyzwyczaja się do obecności substancji. Wiele inhalantów wpływa na podobne obwody mózgowe jak alkohol, dlatego po odstawieniu mózg może być przejściowo rozregulowany. Substancje szybko znikają z krwi, ale mogą być magazynowane w tkance tłuszczowej, przez co czas pojawienia się objawów odstawiennych bywa trudny do przewidzenia.\n\nWczesne objawy\nPrzegląd opisuje odstawienie inhalantów jako podobne do odstawienia alkoholu lub benzodiazepin. Zgłaszane objawy obejmują:\n• Nudności, wymioty i potliwość\n• Drżenie i przyspieszone tętno\n• Bezsenność i zaburzenia snu\n• Lęk i drażliwość\n\nUwaga dotycząca bezpieczeństwa\nW cięższych przypadkach przegląd wymienia też omamy, urojenia i napady drgawkowe. Nie podaje jednak dokładnego harmonogramu dzień po dniu — to objawy, które mogą wystąpić, a nie stały przebieg. Nadzór medyczny podczas detoksykacji jest rozsądny, zwłaszcza przy intensywnym lub wieloletnim używaniu.';

  @override
  String get inhalantsReferenceDay7 =>
      'Tydzień bez inhalantów\n\nŹródło: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), PubMed Central\n\nOstra faza\nW literaturze klinicznej odstawienie inhalantów opisuje się jako podobne do odstawienia alkoholu lub benzodiazepin, ale zwykle krótsze. Pod koniec pierwszego tygodnia ostre objawy fizyczne — nudności, drżenie, potliwość i bezsenność — u większości osób zwykle zaczynają ustępować.\n\nCo może pozostać\n• Zmęczenie i zamglenie myślenia\n• Obniżony lub niestabilny nastrój\n• Silna chęć użycia substancji\n\nUwaga o wczesnej abstynencji\nZamglenie myślenia na tym etapie nie oznacza trwałego uszkodzenia — mózg nadal się przystosowuje. Późniejsze kamienie milowe omawiają badania nad tym, jak myślenie i pamięć wracają do sprawności w kolejnych tygodniach i miesiącach.';

  @override
  String get inhalantsReferenceDay14 =>
      'Dwa tygodnie bez inhalantów\n\nŹródło: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), PubMed Central\n\nPo ostrej fazie\nPrzeglądy kliniczne opisują odstawienie inhalantów jako podobne do odstawienia alkoholu lub benzodiazepin, ale krótsze. Po dwóch tygodniach nudności, drżenie, bezsenność i lęk zwykle już ustąpiły.\n\nDalsza droga\nUwaga, pamięć, ruch i koordynacja poprawiają się bardziej stopniowo w kolejnych miesiącach. Utrzymywanie abstynencji daje tym funkcjom czas na regenerację. Dobre odżywianie, ponieważ używanie inhalantów może obniżać poziom witaminy B12, oraz dalsza abstynencja tworzą warunki sprzyjające poprawie.';

  @override
  String get inhalantsReferenceDay30 =>
      'Miesiąc bez inhalantów\n\nŹródło: Dingwall i wsp., \"Cognitive recovery during and after treatment for volatile solvent abuse\", Drug and Alcohol Dependence (2011), PubMed\n\nGdzie znajduje się pierwszy miesiąc\nWczesna faza odstawienia jest już daleko za tobą. W tym badaniu część zdolności uczenia się poprawiła się w ciągu sześciu tygodni, natomiast koordynacja wzrokowa, pamięć, planowanie i podejmowanie decyzji poprawiały się wolniej w kolejnych miesiącach.\n\nCo może się poprawiać\n• Uwaga i niektóre zadania związane z uczeniem\n• Nastrój i sen wraz ze stabilizacją organizmu\n• Szybkość ruchowa, stopniowo\n\nSygnał poprawy\nWniosek z badania jest jasny: pamięć, planowanie i podejmowanie decyzji poprawiają się stopniowo przez miesiące i lata abstynencji. Utrzymywanie abstynencji jest najsilniejszym czynnikiem wspierającym tę poprawę.';

  @override
  String get inhalantsReferenceDay90 =>
      'Trzy miesiące bez inhalantów\n\nŹródło: Dingwall i wsp., \"Cognitive recovery during and after treatment for volatile solvent abuse\", Drug and Alcohol Dependence (2011), PubMed\n\nNierówny, dłuższy proces\nBadanie śledziło uczestników także po ośmiotygodniowym programie leczenia i część z nich oceniono ponownie po około roku. Niektóre zdolności uczenia się poprawiły się w ciągu sześciu tygodni, natomiast koordynacja wzrokowa, pamięć, planowanie i podejmowanie decyzji poprawiały się przez dłuższy czas.\n\nTrzymanie kursu\nBadanie pokazuje, że wolniej wracające funkcje poprawiają się stopniowo przez miesiące i lata. Po trzech miesiącach utrzymywanie abstynencji pozostaje najważniejszym czynnikiem pozwalającym budować dalszą poprawę z miesiąca na miesiąc.';

  @override
  String get inhalantsReferenceDay365 =>
      'Rok bez inhalantów\n\nŹródło: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse\", PubMed\n\nRzeczywista, mierzalna poprawa\nDługoterminowe badanie wykazało znaczną poprawę problemów z funkcjonowaniem mózgu i myśleniem związanych z przewlekłym używaniem inhalantów po dwóch latach abstynencji. Po roku jesteś już daleko na tej drodze.\n\nCo to oznacza\nPamięć, uwaga i funkcje motoryczne nadal się poprawiają. Długotrwała abstynencja pozwala na rzeczywistą regenerację mózgu: po dwóch latach większość wyników dotyczących funkcji mózgu, pamięci i myślenia wróciła do normy u przewlekłych użytkowników bez uszkodzeń mózgu spowodowanych ołowiem.';

  @override
  String get inhalantsReferenceDay730 =>
      'Dwa lata bez inhalantów\n\nŹródło: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse\", PubMed\n\nPróg dwóch lat\nTo kluczowy punkt w badaniu: deficyty odzwierciedlające uszkodzenia mózgu po długotrwałym używaniu rozpuszczalników wykazały znaczną poprawę po dwóch latach abstynencji. Autorzy uznali, że przy braku uszkodzeń mózgu spowodowanych benzyną ołowiową długotrwała abstynencja może umożliwić powrót prawidłowego funkcjonowania mózgu.\n\nSygnał poprawy\nGłównym wyjątkiem są uszkodzenia po nadużywaniu benzyny ołowiowej, które mogą powodować trwałe deficyty. Poza tym dwa lata abstynencji stanowią najlepiej udokumentowaną szansę na regenerację mózgu, równolegle z odbudową życia.';

  @override
  String get ketamineReferenceDay1 =>
      'Odstawienie ketaminy: pierwszy dzień\n\nŹródło: „Ketamine-Induced Cystitis: A Comprehensive Review of the Urologic Effects of This Psychoactive Drug” w PubMed Central\n\nObjawy odstawienne są głównie psychiczne\nW przeciwieństwie do opioidów czy alkoholu ketamina rzadko powoduje ciężkie fizyczne objawy odstawienne. Odstawienie jest na ogół bezpieczne; częściej problemem są głód ketaminy i zależność psychiczna niż dolegliwości fizyczne.\n\nCo możesz odczuwać\n• Wahania i obniżenie nastroju\n• Głód ketaminy\n• Sporadyczne pocenie się lub kołatanie serca\n\nNajważniejszy krok\nPrzy objawach ze strony pęcherza natychmiastowe i całkowite odstawienie jest koniecznym początkiem zdrowienia — dlatego decyzja pierwszego dnia jest tak ważna.';

  @override
  String get ketamineReferenceDay7 =>
      'Tydzień bez ketaminy\n\nŹródło: „Ketamine-Induced Cystitis: A Comprehensive Review” w PubMed Central\n\nFaza psychiczna\nNajwiększe wyzwanie na początku odstawiania ketaminy ma charakter psychiczny: głód ketaminy, zmienny lub obniżony nastrój i mgła mózgowa. Fizyczne objawy odstawienne, jeśli występują, są zwykle łagodne.\n\nMgła mózgowa jest na tym etapie częsta — koncentracja wymaga większego wysiłku, czas reakcji jest wolniejszy, a pamięć krótkotrwała może wydawać się zawodna. Te problemy z myśleniem i pamięcią poprawiają się wraz z abstynencją: w badaniu podłużnym 114 użytkowników ketaminy po 12 tygodniach bez ketaminy stwierdzono istotną poprawę pamięci werbalnej i wzrokowej, szybkości przetwarzania oraz planowania, koncentracji i podejmowania decyzji.\n\nObjawy ze strony pęcherza\nJeśli masz zapalenie pęcherza wywołane ketaminą (parcie na mocz, częste oddawanie moczu, ból lub krew w moczu), odstawienie daje pęcherzowi najlepszą szansę na poprawę. Ból może skłaniać do powrotu do ketaminy jako sposobu samoleczenia — ten cykl lepiej przerwać odpowiednim wsparciem w leczeniu bólu.';

  @override
  String get ketamineReferenceDay14 =>
      'Dwa tygodnie bez ketaminy\n\nŹródło: „Ketamine-Induced Cystitis: A Comprehensive Review” w PubMed Central\n\nJaśniejsze myślenie\nGdy substancja została już usunięta z organizmu, mgła umysłowa i poczucie odłączenia związane z regularnym używaniem ketaminy zaczynają ustępować. Pamięć i koncentracja poprawiają się, a nastrój stabilizuje.\n\nPoczątek regeneracji pęcherza\nW przypadku zapalenia pęcherza we wczesnym stadium przegląd podkreśla, że samo odstawienie ketaminy jest najważniejszym krokiem w kierunku zmniejszenia objawów, a wcześniejsze odstawienie daje największą szansę na poprawę, zanim uszkodzenia staną się trwałe. Dwa tygodnie abstynencji to początek tego procesu.';

  @override
  String get ketamineReferenceDay30 =>
      'Miesiąc bez ketaminy\n\nŹródło: „Prevalence and Natural History of Urinary Symptoms Among Recreational Ketamine Users”, Winstock i wsp., BJU International (2012)\n\nRegeneracja pęcherza\nNajważniejszym elementem leczenia zapalenia pęcherza wywołanego ketaminą jest odstawienie ketaminy. W tym badaniu rekreacyjnych użytkowników ketaminy 51% osób z objawami ze strony układu moczowego zgłosiło poprawę po odstawieniu, a u mniej niż 4% nastąpiło pogorszenie. Im wcześniej przestaniesz używać, tym lepsze rokowanie.\n\nUmysł i nastrój\nPo miesiącu funkcje poznawcze i nastrój nadal się poprawiają. Wsparcie psychologiczne i społeczne istotnie zwiększa szansę na utrzymanie abstynencji — łatwiej utrzymać odstawienie, gdy ma się wsparcie.';

  @override
  String get ketamineReferenceDay90 =>
      'Trzy miesiące bez ketaminy\n\nŹródło: „Ketamine-Induced Cystitis: A Comprehensive Review” w PubMed Central\n\nDalsza regeneracja\nRegeneracja pęcherza po ketaminie często przebiega stopniowo; przegląd opisuje zmniejszanie nasilenia objawów po odstawieniu, choć proces może być długotrwały i zróżnicowany. Trzy miesiące dają drogom moczowym ciągły czas na gojenie w przypadkach reagujących na odstawienie.\n\nUmysł\nMyślenie i nastrój są wyraźnie lepsze niż na początku abstynencji, a głód ketaminy pojawia się rzadziej. Utrzymujące się lub ciężkie objawy ze strony pęcherza powinien ocenić urolog.';

  @override
  String get ketamineReferenceDay180 =>
      'Sześć miesięcy bez ketaminy\n\nŹródło: „Ketamine-Induced Cystitis: A Comprehensive Review” w PubMed Central\n\nPół roku później\nPrzy utrzymanej abstynencji objawy pęcherza nadal poprawiają się w przypadkach reagujących na odstawienie, a myślenie, pamięć i nastrój pozostają stabilne. Przymus używania ketaminy znacznie osłabł.\n\nSygnał zdrowienia\nRegeneracja utrwalonych uszkodzeń pęcherza może być niepełna, dlatego wczesne odstawienie ma tak duże znaczenie. Niezależnie od etapu, na którym udało się przestać, dalsza abstynencja daje pęcherzowi najlepszą możliwą szansę.';

  @override
  String get ketamineReferenceDay365 =>
      'Rok bez ketaminy\n\nŹródło: „Ketamine-Induced Cystitis: A Comprehensive Review” w PubMed Central\n\nRok później\nDwanaście miesięcy abstynencji daje pęcherzowi, w przypadkach wcześnie wykrytych, największą szansę na regenerację, a myślenie, pamięć i nastrój pozostają stabilne i wyraźne. Zależność psychiczna, która utrudniała odstawienie, w dużej mierze osłabła.\n\nSzersza perspektywa\nRok bez ketaminy to głęboka zmiana w zdrowiu fizycznym, jasności myślenia i samodzielnym kierowaniu swoim życiem. Utrzymanie wsparcia, które pomogło dotrzeć do tego miejsca, chroni ten postęp.';

  @override
  String get ketamineReferenceDay730 =>
      'Dwa lata bez ketaminy\n\nŹródło: kompleksowy przegląd z 2022 r. dotyczący zapalenia pęcherza wywołanego ketaminą (PubMed Central).\n\nPrzegląd zdecydowanie zaleca odstawienie ketaminy i wskazuje, że wczesna choroba często poprawia się po zaprzestaniu używania, natomiast przy zaawansowanych uszkodzeniach powrót do zdrowia może być niepełny. Nie określa dwóch lat jako uniwersalnej biologicznej mety; ten kamień milowy docenia trwały postęp bez obiecywania identycznego wyniku medycznego dla wszystkich.';

  @override
  String get ketamineReferenceDay1095 =>
      'Trzy lata bez ketaminy\n\nŹródło: kompleksowy przegląd z 2022 r. dotyczący zapalenia pęcherza wywołanego ketaminą (PubMed Central).\n\nPrzegląd zdecydowanie zaleca odstawienie ketaminy i wskazuje, że wczesna choroba często poprawia się po zaprzestaniu używania, natomiast przy zaawansowanych uszkodzeniach powrót do zdrowia może być niepełny. Nie wskazuje szczególnego progu poprawy po trzech latach; trzy lata oznaczają trwały postęp, choć wyniki pozostają indywidualne.';

  @override
  String get ketamineReferenceDay1460 =>
      'Cztery lata bez ketaminy\n\nŹródło: kompleksowy przegląd z 2022 r. dotyczący zapalenia pęcherza wywołanego ketaminą (PubMed Central).\n\nPrzegląd zdecydowanie zaleca odstawienie ketaminy i wskazuje, że wczesna choroba często poprawia się po zaprzestaniu używania, natomiast przy zaawansowanych uszkodzeniach powrót do zdrowia może być niepełny. Nie przypisuje czwartemu rokowi szczególnego zdarzenia biologicznego; cztery lata oznaczają mocne podstawy, a nie obietnicę medyczną.';

  @override
  String get ketamineReferenceDay1825 =>
      'Pięć lat bez ketaminy\n\nŹródło: kompleksowy przegląd z 2022 r. dotyczący zapalenia pęcherza wywołanego ketaminą (PubMed Central).\n\nPrzegląd zdecydowanie zaleca odstawienie ketaminy i wskazuje, że wczesna choroba często poprawia się po zaprzestaniu używania, natomiast przy zaawansowanych uszkodzeniach powrót do zdrowia może być niepełny. Nie uznaje pięciu lat za uniwersalny biologiczny punkt końcowy; ten kamień milowy docenia znaczny trwały postęp bez obiecywania gwarantowanego wyleczenia.';

  @override
  String get kratomReferenceDay1 =>
      'Odstawienie kratomu: pierwszy dzień\n\nŹródło: Swogger i wsp. (2022), „Understanding Kratom Use: A Guide for Healthcare Providers”, Frontiers in Pharmacology\n\nDlaczego pojawiają się objawy odstawienne\nAktywne związki kratomu działają na te same receptory opioidowe co klasyczne opioidy. Przy regularnym używaniu organizm się przystosowuje, dlatego przerwanie używania może wywołać objawy odstawienne podobne do opioidowych. Ten przewodnik kliniczny opisuje zależność i odstawienie jako uznane ryzyka regularnego używania kratomu.\n\nCo wiadomo o początku objawów\nBadania na zwierzętach cytowane w przewodniku pokazują pojawianie się somatycznych objawów odstawiennych w ciągu około 12 godzin, a efektów podobnych do lęku w ciągu 24 godzin. Dokładny czas początku objawów u ludzi jest mniej ustalony, ale często zgłaszane wczesne objawy obejmują:\n• Niepokój, lęk i drażliwość\n• Bóle mięśni i katar\n• Potliwość i łzawienie oczu\n• Silną chęć użycia\n\nUwaga o nasileniu\nPrzewodnik wskazuje, że dłuższy czas używania i wyższe dawki wiążą się z silniejszym i dłużej trwającym odstawieniem. Warto rozważyć wsparcie medyczne pod nadzorem, zwłaszcza po wysokich dawkach lub jeśli kratom był używany razem z opioidami.';

  @override
  String get kratomReferenceDay3 =>
      'Odstawienie kratomu: najtrudniejsze dni\n\nŹródło: Singh i wsp. (2014), Drug and Alcohol Dependence — badanie 293 regularnych użytkowników kratomu w Malezji\n\nCo pokazują dane\nZamiast jednego określonego „dnia szczytu” badanie wykazało, że nasilenie odstawienia zależy od ilości i czasu używania: osoby pijące trzy lub więcej szklanek kratomu dziennie miały znacznie większe prawdopodobieństwo ciężkiej zależności i trudniejszego odstawienia. Dla większości ludzi pierwsze dni po przerwaniu używania są najtrudniejsze.\n\nCzęsto zgłaszane objawy\n• Bóle mięśni i stawów, niespokojne nogi\n• Bezsenność mimo wyczerpania\n• Nudności, skurcze brzucha i biegunka\n• Lęk, obniżony nastrój i drażliwość\n• Silna chęć użycia\n\nJak przejść przez tę fazę\nPomagają nawodnienie, odpoczynek i leczenie objawowe. Jeśli odstawienie było dotąd bardzo ciężkie, częściej pasuje to do większej ilości lub dłuższego okresu używania niż do czegoś nietypowo niepokojącego — i zwykle od tego momentu zaczyna słabnąć.';

  @override
  String get kratomReferenceDay7 =>
      'Tydzień bez kratomu\n\nŹródło: Swogger i wsp. (2022), „Understanding Kratom Use: A Guide for Healthcare Providers”, Frontiers in Pharmacology\n\nPo ostrej fazie\nDane z samoopisów ludzi cytowane w przewodniku wskazują, że u większości osób objawy odstawienne ustępują w ciągu około jednego do trzech dni po zaprzestaniu używania. Po tygodniu ostre objawy fizyczne — bóle mięśni, potliwość i nudności — zwykle w dużej mierze ustępują. Mogą pozostać bardziej psychiczne trudności: zmęczenie, zaburzony sen i obniżony nastrój, gdy receptory opioidowe wcześniej pobudzane przez kratom ponownie dostosowują się do sygnałów organizmu.\n\nRealne ryzyko\nPrzewodnik zauważa też, że niewielkiej grupie osób bardzo trudno odstawić kratom; cięższe i dłużej trwające odstawienie częściej zgłaszają osoby używające więcej i przez dłuższy czas. W tym okresie stosunkowo często dochodzi do powrotu do używania, a tolerancja szybko spada. Powrót do poprzedniej dawki, szczególnie przy jednoczesnym użyciu opioidów, może być naprawdę niebezpieczny.';

  @override
  String get kratomReferenceDay14 =>
      'Dwa tygodnie bez kratomu\n\nŹródło: National Institute on Drug Abuse (NIDA), „Kratom”\n\nPoza najlepiej zbadanym okresem\nKontrolowane dane z badań u ludzi dotyczące czasu trwania odstawienia kratomu obejmują głównie pierwsze dni, dlatego nie ma dobrze potwierdzonych badań wyznaczających konkretny dwutygodniowy punkt zdrowienia. Udokumentowany jest szerszy mechanizm: kratom działa na te same receptory opioidowe co klasyczne opioidy, a po zakończeniu regularnego używania receptory stopniowo odzyskują wrażliwość na sygnały organizmu.\n\nCo ludzie często zgłaszają\n• Apetyt i energia często się poprawiają\n• Sen staje się bardziej regularny\n• Nastrój zwykle jest stabilniejszy, choć nadal może się zmieniać\n\nSilna chęć użycia może nadal pojawiać się pod wpływem stresu i znajomych bodźców, dlatego plan radzenia sobie z nimi pozostaje przydatny.';

  @override
  String get kratomReferenceDay30 =>
      'Miesiąc bez kratomu\n\nŹródło: National Institute on Drug Abuse (NIDA), „Kratom”\n\nUkład nagrody wraca do równowagi\nNIDA opisuje kratom jako substancję działającą na receptory opioidowe w mózgu, a zależność i odstawienie jako uznane ryzyka regularnego używania. Nie ma konkretnego badania, które określałoby miesiąc jako szczególny punkt zdrowienia, ale ogólny wzorzec zależności związanej z receptorami opioidowymi wskazuje, że przy utrzymującym się nieużywaniu reakcja mózgu na codzienne przyjemności stopniowo się normalizuje.\n\nCo może zbudować miesiąc bez kratomu\nMiesiąc bez kratomu to miesiąc regularnego snu, posiłków i codziennej rutyny w miejsce czasu i wysiłku, których wymagało używanie. Silna chęć sięgnięcia po kratom zwykle pojawia się rzadziej i jest łatwiejsza do opanowania, choć okresy dużego stresu pozostają najbardziej podatne na trudności.';

  @override
  String get kratomReferenceDay90 =>
      'Trzy miesiące bez kratomu\n\nŹródło: National Institute on Drug Abuse (NIDA), „Kratom”\n\nStabilniejsza codzienność\nKratom działa na receptory opioidowe, więc trzy miesiące bez niego dają układom nagrody i stresu w mózgu dłuższy czas na uspokojenie się. Wiele osób zgłasza jaśniejsze myślenie i stabilniejszą motywację, im dalej są od aktywnego używania.\n\nDlaczego to ważne\nIm więcej czasu upływa od używania, tym bardziej zwykle słabnie codzienne przyciąganie kratomu. Ten etap może stanowić solidną podstawę trwałej poprawy.';

  @override
  String get kratomReferenceDay365 =>
      'Rok bez kratomu\n\nŹródło: National Institute on Drug Abuse (NIDA), „Kratom”\n\nDługo po ostrym odstawieniu\nNIDA nie publikuje konkretnego rocznego harmonogramu zdrowienia po kratomie. Rok ciągłego nieużywania wykracza jednak daleko poza ostry i wczesny psychologiczny okres odstawienia opisany w badaniach nad kratomem. U większości osób, które osiągają ten etap, silna chęć użycia pojawia się rzadko i jest znacznie łatwiejsza do opanowania.\n\nSzersza perspektywa\nRok bez kratomu oznacza znaczącą zmianę w zdrowiu, finansach i samodzielnym kierowaniu swoim życiem. Utrzymywanie kontaktu ze wsparciem pomaga chronić ten postęp.';

  @override
  String get kratomReferenceDay730 =>
      'Dwa lata bez kratomu\n\nŹródło: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nCo mówią dowody\nPrzegląd opisuje zależność od kratomu, ryzyko nawrotu i podejścia do długoterminowego leczenia. Zaznacza też, że nie istnieją ustalone wytyczne dotyczące utrzymywania długotrwałej abstynencji od kratomu. Dowody nie określają tej rocznicy jako biologicznego punktu końcowego zdrowienia.\n\nCo oznacza ten etap\nNajlepiej traktować tę rocznicę jako świętowanie utrzymywanej zmiany, a nie medyczny termin graniczny. Rutyny, wsparcie i decyzje utrzymywane przez te lata są ważnym osiągnięciem same w sobie.';

  @override
  String get kratomReferenceDay1095 =>
      'Trzy lata bez kratomu\n\nŹródło: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nCo mówią dowody\nPrzegląd opisuje zależność od kratomu, ryzyko nawrotu i podejścia do długoterminowego leczenia. Zaznacza też, że nie istnieją ustalone wytyczne dotyczące utrzymywania długotrwałej abstynencji od kratomu. Dowody nie określają tej rocznicy jako biologicznego punktu końcowego zdrowienia.\n\nCo oznacza ten etap\nNajlepiej traktować tę rocznicę jako świętowanie utrzymywanej zmiany, a nie medyczny termin graniczny. Rutyny, wsparcie i decyzje utrzymywane przez te lata są ważnym osiągnięciem same w sobie.';

  @override
  String get kratomReferenceDay1460 =>
      'Cztery lata bez kratomu\n\nŹródło: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nCo mówią dowody\nPrzegląd opisuje zależność od kratomu, ryzyko nawrotu i podejścia do długoterminowego leczenia. Zaznacza też, że nie istnieją ustalone wytyczne dotyczące utrzymywania długotrwałej abstynencji od kratomu. Dowody nie określają tej rocznicy jako biologicznego punktu końcowego zdrowienia.\n\nCo oznacza ten etap\nNajlepiej traktować tę rocznicę jako świętowanie utrzymywanej zmiany, a nie medyczny termin graniczny. Rutyny, wsparcie i decyzje utrzymywane przez te lata są ważnym osiągnięciem same w sobie.';

  @override
  String get kratomReferenceDay1825 =>
      'Pięć lat bez kratomu\n\nŹródło: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\nCo mówią dowody\nPrzegląd opisuje zależność od kratomu, ryzyko nawrotu i podejścia do długoterminowego leczenia. Zaznacza też, że nie istnieją ustalone wytyczne dotyczące utrzymywania długotrwałej abstynencji od kratomu. Dowody nie określają tej rocznicy jako biologicznego punktu końcowego zdrowienia.\n\nCo oznacza ten etap\nNajlepiej traktować tę rocznicę jako świętowanie utrzymywanej zmiany, a nie medyczny termin graniczny. Rutyny, wsparcie i decyzje utrzymywane przez te lata są ważnym osiągnięciem same w sobie.';

  @override
  String get maoiReferenceDay3 =>
      'Odstawienie MAOI: Faza najwyższego ryzyka\n\nŹródło: Dilsaver (1988), badania nad reakcjami odstawiennymi po MAOI\n\nWażne ostrzeżenie dotyczące bezpieczeństwa\nMAOI wiążą się z jednymi z najpoważniejszych zagrożeń po nagłym odstawieniu wśród leków przeciwdepresyjnych. Nagłe przerwanie stosowania — zwłaszcza fenelzyny i tranylcyprominy — może wywołać ciężkie reakcje, w tym:\n• Silny lęk i pobudzenie\n• Przyspieszoną, napierającą mowę i niepokój ruchowy\n• Bezsenność lub senność\n• Omamy\n• Majaczenie i psychozę paranoidalną\n\nJeśli występują takie objawy, natychmiast zgłoś się po pomoc medyczną.\n\nJak działają MAOI\nMAOI nieodwracalnie wiążą się z enzymami monoaminooksydazy (MAO-A i MAO-B) i je unieczynniają. Enzymy te zwykle rozkładają serotoninę, noradrenalinę, dopaminę i tyraminę w mózgu i jelitach. Ponieważ unieczynniony zostaje sam enzym, a nie tylko czasowo zablokowana jego aktywność, regeneracja zależy od wytworzenia nowych enzymów przez organizm, a nie od szybkości usuwania leku z krwi.';

  @override
  String get maoiReferenceDay7 =>
      'Tydzień po MAOI: Trwa synteza enzymów MAO\n\nŹródło: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nProces odtwarzania enzymów\nW przeciwieństwie do SSRI, SNRI i TCA — które odwracalnie hamują wychwyt zwrotny neuroprzekaźników — nieodwracalne MAOI, takie jak fenelzyna i tranylcypromina, trwale unieczynniają cząsteczki monoaminooksydazy. Dlatego kliniczny okres wypłukiwania zależy od tego, jak szybko organizm syntetyzuje nowe enzymy — około 2 tygodni — a nie od tego, jak szybko sam lek znika z krwi.\n\nCo dzieje się po tygodniu\n• Synteza MAO-A i MAO-B jest już zaawansowana, mniej więcej w połowie około dwutygodniowego okresu odtwarzania enzymów\n• Ostra faza ryzyka opisana dla 3. dnia mija, choć nadal ważny jest ścisły nadzór medyczny\n\nOstrożność dietetyczna\nLeczenie MAOI wymaga diety ubogiej w tyraminę, ponieważ enzymy MAO zwykle rozkładają tyraminę i zapobiegają wywołaniu przez nią przełomu nadciśnieniowego. Ograniczenia dietetyczne należy utrzymywać w okresie odtwarzania enzymów; lekarz prowadzący doradzi, kiedy można je bezpiecznie złagodzić.';

  @override
  String get maoiReferenceDay14 =>
      'Dwa tygodnie po MAOI: Aktywność enzymów MAO w dużej mierze wróciła\n\nŹródło: Fritz i wsp. (1983), Biological Psychiatry\n\nKluczowy punkt dwóch tygodni\nDwa tygodnie to standardowy kliniczny okres wypłukiwania potrzebny na odzyskanie aktywności enzymów MAO po odstawieniu nieodwracalnego MAOI, takiego jak tranylcypromina lub fenelzyna. W badaniu tranylcyprominy aktywność katalityczna MAO-B w płytkach krwi — silnie obniżona już w ciągu doby od podania leku — wracała do normy w około dwa tygodnie, gdy organizm zastępował płytki poddane działaniu leku nowymi płytkami z aktywnym enzymem, mimo że całkowity poziom białka MAO-B się nie zmieniał.\n\nOdzyskiwanie aktywności MAO\n• Aktywność MAO-B w płytkach krwi jest na tym etapie w dużej mierze przywrócona\n• MAO-A i MAO-B w mózgu, których odtwarzanie przebiega w podobnym czasie, również są w dużej mierze przywrócone\n• Prawidłowy metabolizm tyraminy ponownie się ustala; ograniczenia dietetyczne związane z MAOI można zwykle łagodzić po konsultacji z lekarzem\n\nPowrót równowagi neurochemicznej\nWraz z powrotem aktywności MAO układy neurochemiczne, na które wpływały MAOI, zaczynają ponownie podlegać naturalnej regulacji:\n• Serotonina, noradrenalina i dopamina nie są już podwyższane przez hamowanie MAO\n• Nadwrażliwość receptorów monoaminowych wywołana długotrwałym podwyższeniem stężeń monoamin zaczyna ustępować\n• Wraca naturalna regulacja nastroju i energii';

  @override
  String get maoiReferenceDay30 =>
      'Miesiąc po MAOI: Ponowne równoważenie układów neurochemicznych\n\nŹródło: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nOcena po miesiącu\nMiesiąc po odstawieniu MAOI przypada już długo po około dwutygodniowym okresie odtwarzania enzymów MAO opisanym w tym źródle. Na tym etapie aktywność MAO wróciła, a układy neurochemiczne ponownie podlegają naturalnej regulacji.\n\nCo odzyskało się po miesiącu\n• Pełna aktywność MAO: MAO-A i MAO-B ponownie działają\n• Koniec ograniczeń dietetycznych: zwykła dieta bez ograniczeń dotyczących tyraminy\n• Naturalny rozkład serotoniny: wrócił prawidłowy cykl obrotu serotoniny w mózgu\n• Naturalna regulacja katecholamin: poziomy dopaminy i noradrenaliny są regulowane przez naturalną aktywność MAO\n\nOstrożność przy interakcjach lekowych\nMAOI mogą powodować zagrażające życiu interakcje z lekami serotoninergicznymi. Ryzyko związane z okresem wypłukiwania minęło do końca pierwszego miesiąca. Mimo to przy każdym nowym leku należy informować lekarza i farmaceutę o wcześniejszym stosowaniu MAOI.';

  @override
  String get maoiReferenceDay90 =>
      'Trzy miesiące po MAOI: Daleko poza ostrą fazą odstawienną\n\nŹródło: \"Antidepressant Withdrawal Syndrome\", Therapeutics Letter 112 (2018), Therapeutics Initiative, NCBI Bookshelf\n\nOdstawienie w różnych klasach leków przeciwdepresyjnych\nPrzegląd traktuje objawy odstawienne po lekach przeciwdepresyjnych jako rzeczywiste zjawisko związane z tolerancją i zależnością. Szczegółowe dane dotyczą głównie SSRI i SNRI, ale reakcje odstawienne występują w różnych klasach leków przeciwdepresyjnych, także po odstawieniu MAOI. Objawy \"zwykle pojawiają się w ciągu kilku dni od odstawienia\", a \"większość… ustępuje w ciągu 2 tygodni\", choć u części osób trwają dłużej.\n\nCo oznaczają trzy miesiące\nPo trzech miesiącach ostra faza odstawienna jest u zdecydowanej większości osób daleko w przeszłości, a organizm od dawna reguluje monoaminy bez hamowania MAO.\n\nSygnał regeneracji i \"ponowne uwrażliwienie receptorów\"\nKategoryczne twierdzenie, że receptory serotoninowe, noradrenergiczne i dopaminowe są już po trzech miesiącach w pełni \"ponownie uwrażliwione\", wykracza poza to, co potwierdzają dane. Pewne jest natomiast, że faza odstawienna zwykle już minęła, a u większości osób nastrój, energia i zakres emocji stabilizują się przy naturalnej, samoregulującej sygnalizacji mózgu.\n\nOdstawienie a nawrót\nTherapeutics Letter podkreśla potrzebę odróżnienia objawów odstawiennych od rzeczywistego nawrotu choroby podstawowej. Jeśli objawy utrzymują się po trzech miesiącach, omów je z lekarzem zamiast zakładać, że są wyłącznie skutkiem odstawienia.';

  @override
  String get maoiReferenceDay180 =>
      'Sześć miesięcy po MAOI: Długoterminowa regeneracja\n\nŹródło: Zwiebel & Viguera (2022), Cleveland Clinic Journal of Medicine\n\nOcena po sześciu miesiącach\nPrzegląd wyjaśnia, że leki przeciwdepresyjne działają częściowo przez stopniowe zmniejszenie wrażliwości receptorów monoaminowych, a odwrócenie tego procesu po odstawieniu leku trwa od tygodni do miesięcy — dłużej niż około dwutygodniowe odtwarzanie enzymów MAO.\n\nCo oznacza sześć miesięcy\nSześć miesięcy przypada zdecydowanie po typowym, trwającym od tygodni do miesięcy okresie ponownego dostosowania receptorów u większości osób, a aktywność enzymów MAO wróciła do normy już w pierwszym miesiącu. Dokładnego terminu pełnego ponownego uwrażliwienia receptorów serotoninowych, noradrenergicznych i dopaminowych nie da się ustalić dzień po dniu na podstawie literatury. Wiarygodne jest natomiast to, że po sześciu miesiącach większość osób funkcjonuje z naturalną, samoregulującą sygnalizacją mózgu.\n\nUwaga o fenyloetyloaminie\nMAOI hamują też rozkład fenyloetyloaminy (PEA), aminy śladowej związanej z nastrojem i energią. Oczekuje się, że jej metabolizm normalizuje się wraz z ogólnym powrotem aktywności MAO, ale — podobnie jak w przypadku ponownego uwrażliwienia receptorów — literatura nie określa precyzyjnego terminu właściwego tylko dla PEA.';

  @override
  String get maoiReferenceDay365 =>
      'Rok po MAOI: Utrwalona regeneracja\n\nŹródło: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\nRok: Ważne osiągnięcie\nPełny rok po odstawieniu MAOI to naprawdę znaczący kamień milowy. Odstawianie MAOI wymaga szczególnej ostrożności ze względu na ich nieodwracalny mechanizm działania, ścisłą dietę ubogą w tyraminę i środki ostrożności dotyczące interakcji lekowych, które różnią tę klasę od innych leków przeciwdepresyjnych.\n\nCo oznacza ten rok\n• Pełny rok naturalnej, samoregulowanej aktywności monoaminooksydazy po zakończeniu odtwarzania enzymów w pierwszym miesiącu\n• Udowodnioną zdolność do utrzymywania dobrostanu bez farmakologicznego hamowania MAO\n• Okres wystarczająco długi, by ostre zagrożenia odstawienne z 3. dnia były zdecydowanie przeszłością\n\nUwaga o MAOI\nMAOI pozostają wyjątkowo skuteczne w niektórych przypadkach depresji opornej na leczenie i depresji atypowej. Udane odstawienie nie umniejsza ich wartości jako leków; pokazuje zdolność mózgu do regeneracji i umiejętność przejścia przez wymagający proces medyczny. Jedno trwałe zalecenie: nadal informuj nowych lekarzy i anestezjologów o wcześniejszym stosowaniu MAOI, ponieważ niektóre potencjalne interakcje lekowe warto zgłaszać także po dłuższym czasie.';

  @override
  String get marijuanaReferenceDay1 =>
      'Odstawienie marihuany: Dzień pierwszy\n\nŹródło: „The cannabis withdrawal syndrome: current insights”, Substance Abuse and Rehabilitation (2017), PubMed Central\n\nOdstawienie konopi jest realnym zjawiskiem\nTen recenzowany przegląd potwierdza, że zespół odstawienia konopi (CWS) jest dobrze udokumentowanym stanem klinicznym i występuje u około 90% osób z rozpoznanym uzależnieniem od konopi po zaprzestaniu używania. Jego średnie największe nasilenie jest porównywalne z zespołem odstawienia tytoniu.\n\nDlaczego pojawiają się objawy odstawienia\nTHC działa na układ endokannabinoidowy, w tym receptory CB1 związane z nastrojem, apetytem, snem, pamięcią i stresem. Przy przewlekłym używaniu mózg zmniejsza aktywność tego układu; po odstawieniu konopi przez pewien czas działa on słabiej. Przegląd wskazuje, że funkcjonowanie receptorów CB1 wraca w kierunku normy w ciągu około czterech tygodni abstynencji.\n\nPoczątek pierwszego dnia\nPrzegląd opisuje, że objawy fizyczne zwykle pojawiają się jako pierwsze, w ciągu 1–3 dni od ostatniego użycia, a objawy psychiczne rozwijają się w ciągu 2–10 dni. Wczesne objawy obejmują:\n• Drażliwość, lęk i niepokój ruchowy\n• Trudności ze snem\n• Zmniejszony apetyt\n• Napięcie fizyczne, pocenie się lub dreszcze\n• Obniżony nastrój\n\nNasilenie\nCWS nie jest stanem niebezpiecznym medycznie, a objawy są zwykle łagodne lub umiarkowane. Przegląd zaznacza jednak, że mogą być na tyle uciążliwe, by sprzyjać nawrotowi, dlatego znajomość ich przebiegu ma znaczenie.';

  @override
  String get marijuanaReferenceDay3 =>
      'Przebieg odstawienia konopi: Pierwsze dni\n\nŹródło: „Time-course of the DSM-5 cannabis withdrawal symptoms in poly-substance abusers”, BMC Psychiatry (2013), PubMed Central\n\nZmierzony przebieg w czasie\nW badaniu śledzono objawy odstawienia konopi według DSM-5 u 90 pacjentów przez cztery tygodnie, uzyskując wyraźny obraz ich narastania i ustępowania. Łączne nasilenie tworzyło krzywą: najpierw rosło, a następnie spadało w kolejnych tygodniach.\n\nCo osiąga szczyt wcześniej\nKilka najbardziej dokuczliwych objawów fizycznych osiąga szczyt w pierwszych dniach po odstawieniu:\n• Bezsenność — około 1. dnia\n• Nerwowość — około 4. dnia\n• Obniżony nastrój i objawy fizyczne — około 5. dnia\n• Niepokój ruchowy — około 6. dnia\n\nCo osiąga szczyt później\nBadanie wykazało, że część objawów pojawia się i nasila później niż w pierwszym tygodniu:\n• Wyraziste, nieprzyjemne sny — około 11. dnia\n• Drażliwość i złość — około 14. dnia\n\nSen i konopie\nPóźniejsze, wyraziste sny odzwierciedlają odbicie fazy REM: konopie tłumią sen REM podczas używania, a po odstawieniu mózg przez pewien czas go kompensuje. Autorzy uznają ten objaw za na tyle częsty, że powinien należeć do formalnych kryteriów odstawienia.\n\nZnaczenie trzeciego dnia\nTrzeciego dnia jesteś w środku wczesnego szczytu objawów fizycznych. Bezsenność, nerwowość i niepokój są blisko największego nasilenia. Sam przewidywalny przebieg może uspokajać: objawy mają znany tor i później słabną.';

  @override
  String get marijuanaReferenceDay7 =>
      'Tydzień bez konopi: Za najgorszym etapem\n\nŹródło: „The cannabis withdrawal syndrome: current insights”, Substance Abuse and Rehabilitation (2017), PubMed Central\n\nGdzie wypada pierwszy tydzień\nPrzegląd opisuje, że zespół odstawienia konopi zwykle trwa do około trzech tygodni, a najbardziej dokuczliwy okres przypada między pierwszym a trzecim tygodniem. Po tygodniu najwcześniejsze objawy fizyczne, takie jak bezsenność, utrata apetytu i niepokój, zwykle są już po szczycie i zaczynają słabnąć.\n\nCo jeszcze się reguluje\nPrzegląd odróżnia wcześniej nasilające się objawy fizyczne od później nasilających się objawów psychicznych. Po tygodniu:\n• Dyskomfort fizyczny i apetyt zwykle się poprawiają\n• U wielu osób sen nadal jest zaburzony, a żywe sny związane z odbiciem REM często osiągają szczyt właśnie w tym okresie\n• Drażliwość i wahania nastroju mogą nadal być nasilone, ponieważ ich szczyt przypada później w pierwszych dwóch tygodniach\n\nNeurobiologia zdrowienia\nPrzegląd wskazuje, że obniżona wcześniej aktywność receptorów CB1 wraca w kierunku normy w ciągu około czterech tygodni abstynencji. Po tygodniu ten proces już trwa, nawet jeśli niektóre objawy jeszcze się utrzymują.\n\nNajważniejsze\nTydzień oznacza, że ostry fizyczny szczyt jest już za Tobą. Pozostałe zaburzenia snu i nastroju należą do zespołu o znanym i ograniczonym przebiegu, który nadal wygasa w kolejnych tygodniach.';

  @override
  String get marijuanaReferenceDay14 =>
      'Dwa tygodnie bez konopi: Ostre odstawienie dobiega końca\n\nŹródło: Budney, AJ et al. (2003) — recenzowane badanie przebiegu odstawienia konopi\n\nWyniki badania\nTo recenzowane badanie systematycznie opisało przebieg objawów odstawienia u regularnych użytkowników konopi. Wyniki pokazały, że ostry zespół odstawienia osiąga szczyt w pierwszym tygodniu, a większość objawów w dużej mierze ustępuje w ciągu dwóch tygodni od zaprzestania używania.\n\nCo w dużej mierze ustępuje po dwóch tygodniach\nW 14. dniu u uczestników badania w dużej mierze ustąpiły:\n• Dyskomfort i objawy fizyczne\n• Zaburzenia apetytu\n• Większość zaburzeń snu\n• Największe nasilenie drażliwości i lęku\n\nCo może utrzymywać się dłużej\nBadanie wskazało także objawy, które u części osób utrzymywały się po dwóch tygodniach:\n• Obniżony nastrój\n• Trudności z koncentracją\n• Gorsza jakość snu, choć stopniowo się poprawiająca\n\nZnaczenie dwóch tygodni\nPrzekroczenie dwóch tygodni jest ważne, ponieważ oznacza, że ostry zespół odstawienia jest w dużej mierze zakończony. Późniejsze wyzwania dotyczą głównie długoterminowego zdrowienia mózgu i radzenia sobie z przyczynami używania konopi, a nie ostrej fizjologicznej reakcji na odstawienie.';

  @override
  String get marijuanaReferenceDay30 =>
      'Miesiąc bez konopi: Pamięć się poprawia\n\nŹródło: Pope et al. (2001), Archives of General Psychiatry\n\nKonopie i pamięć: Problem\nBadanie obserwowało osoby intensywnie i długo używające konopi przez 28 dni potwierdzonej abstynencji i porównywało ich wyniki testów myślenia i pamięci z osobami używającymi niewiele oraz nieużywającymi. Na początku abstynencji, a następnie w 1. i 7. dniu, osoby intensywnie używające gorzej przypominały sobie listy słów niż grupa kontrolna. Deficyt ten korelował z poziomem metabolitów THC w moczu, czyli z niedawną ekspozycją, a nie całkowitym używaniem w ciągu życia.\n\nDobra wiadomość: Poprawa do 28. dnia\nDo 28. dnia osoby intensywnie używające, używające niewiele i nieużywające osiągały niemal takie same wyniki w testach myślenia i pamięci. Nie stwierdzono też istotnego związku między całkowitym używaniem konopi w ciągu życia a wynikami testów w tym momencie.\n\nCo to oznacza po 30 dniach\n• Uczenie werbalne i przypominanie wróciły do poziomu grupy kontrolnej\n• Resztkowe deficyty widoczne w pierwszym tygodniu ustąpiły\n• Wcześniejszy deficyt był związany z niedawną ekspozycją, a nie trwałym uszkodzeniem\n\nCo pokazują dane\nDo 28. dnia osoby intensywnie używające były praktycznie nie do odróżnienia od osób używających niewiele i nieużywających w pełnym zestawie testów myślenia i pamięci. Deficyty uczenia werbalnego i przypominania z pierwszego tygodnia wróciły do poziomu grupy kontrolnej.';

  @override
  String get marijuanaReferenceDay60 =>
      'Dwa miesiące bez konopi: Lepsza koncentracja\n\nŹródło: Roten et al. (2015), Addictive Behaviors\n\nPytanie badawcze\nBadanie młodych osób zaprzestających używania konopi śledziło przez około dwa miesiące wyniki testów pamięci i myślenia wraz z wynikami badań moczu, porównując osoby nadal używające z tymi, które niedawno przestały lub utrzymywały abstynencję.\n\nNajważniejsze wyniki\nStała abstynencja była związana z istotną poprawą:\n• Łącznego wyniku pamięci\n• Pamięci werbalnej — najbardziej dotkniętej domeny\n• Sprawności ruchowej i szybkości reakcji\n\nPo dwóch miesiącach\nPo około ośmiu tygodniach stałej abstynencji wyniki pamięci oraz sprawności ruchowej i szybkości reakcji mierzalnie wzrosły względem okresu aktywnego używania. Zmiany te silniej odpowiadały potwierdzonemu nieużywaniu niż samemu upływowi czasu.\n\nCo pokazuje badanie\nU nastolatków i młodych dorosłych z uzależnieniem od konopi stała abstynencja wiązała się z istotną poprawą łącznej pamięci, pamięci werbalnej oraz sprawności ruchowej i szybkości reakcji w około dwumiesięcznym okresie badania.';

  @override
  String get marijuanaReferenceDay90 =>
      'Trzy miesiące bez konopi: Wraca stabilniejszy nastrój\n\nŹródło: Connor et al. (2022), Addiction — kliniczny przegląd odstawienia konopi\n\nJak wygląda przebieg odstawienia\nPrzegląd opisuje, że objawy odstawienia konopi zwykle zaczynają się 24–48 godzin po zaprzestaniu używania i osiągają szczyt około 2.–6. dnia. Złość, agresja i obniżony nastrój mogą pojawić się już po tygodniu, ale zwykle osiągają szczyt po około dwóch tygodniach abstynencji; zaburzenia snu mogą utrzymywać się dłużej niż inne objawy.\n\nGdzie wypadają trzy miesiące\nPo trzech miesiącach jesteś daleko poza udokumentowanym okresem odstawienia: objawy zwykle zaczynają się w ciągu 24–48 godzin, szczyt osiągają około 2.–6. dnia, a wolniej ustępujące problemy z nastrojem i snem osiągają szczyt w kolejnych tygodniach. Dziewięćdziesiąt dni daje tym objawom miesiące na uspokojenie.\n\nUwaga o układzie endokannabinoidowym\nBadania nad odstawieniem konopi pokazują również, że obniżona wcześniej aktywność receptorów CB1 wraca w kierunku normy w ciągu około czterech tygodni abstynencji. Po 90 dniach jesteś daleko poza tym oknem zmian receptorowych.\n\nCo dalej\nPrzegląd omawia również rokowanie po detoksykacji i zapobieganie nawrotom, podkreślając znaczenie stałego wsparcia i strategii radzenia sobie także długo po ostrym okresie odstawienia.';

  @override
  String get marijuanaReferenceDay180 =>
      'Sześć miesięcy bez konopi: Planowanie i decyzje wracają\n\nŹródło: Crean, Crane & Mason (2011), Journal of Addiction Medicine\n\nPlanowanie i podejmowanie decyzji po konopiach\nPrzegląd obejmował uwagę, podejmowanie decyzji, samokontrolę, pamięć roboczą i płynność słowną od pierwszych godzin po użyciu po długotrwałą abstynencję. Po sześciu miesiącach jesteś daleko poza krótkotrwałymi efektami i w zaawansowanym okresie zdrowienia.\n\nCo wykazały badania\nWiele problemów związanych z intensywnym używaniem słabnie przy utrzymywanej abstynencji, a część badań wykazuje poprawę już po 28 dniach. Do wolniej wracających obszarów po intensywnym używaniu rozpoczętym wcześnie należą:\n• Podejmowanie decyzji i skłonność do ryzyka — obszary, w których deficyty mogą utrzymywać się długo u osób przewlekle i intensywnie używających\n• Myślenie abstrakcyjne i zdolności werbalne — szczególnie osłabione u dorosłych, którzy zaczęli używać przed 17. rokiem życia\n\nZdrowienie po wczesnym rozpoczęciu\nSześć miesięcy znacznie wykracza poza krótkoterminowe efekty opisane w tym przeglądzie. Planowanie, podejmowanie decyzji i rozumowanie mogą nadal poprawiać się przy utrzymywanej abstynencji.\n\nSzerszy obraz\nPrzy lżejszym używaniu rozpoczętym w dorosłości rokowanie jest korzystniejsze. Wiele osób po sześciu miesiącach zgłasza jaśniejsze myślenie, stabilniejsze decyzje i silniejsze poczucie kierowania sobą. Największym wsparciem dalszej poprawy pozostaje utrzymywanie abstynencji, szczególnie po intensywnym lub wcześnie rozpoczętym używaniu.';

  @override
  String get marijuanaReferenceDay365 =>
      'Rok bez konopi: Odbudowa struktury mózgu\n\nŹródło: „Hippocampal harms, protection and recovery following regular cannabis use”, Translational Psychiatry (2016), PubMed Central\n\nZmiany strukturalne związane z konopiami\nBadanie obrazowe analizowało hipokamp, obszar mózgu kluczowy dla pamięci, u obecnych użytkowników, byłych użytkowników i osób nieużywających. Obecni użytkownicy, którzy nie byli narażeni na CBD, mieli hipokamp około 11% mniejszy i marker zdrowia komórek mózgowych około 15% niższy niż osoby kontrolne.\n\nKluczowy wynik: Poprawa przy abstynencji\nAnalizy dopasowania krzywej wspierały model „ochrony i zdrowienia”. Co ważne, byli użytkownicy abstynentni średnio przez około 29 miesięcy nie różnili się od osób nieużywających w żadnej z badanych miar integralności. Autorzy stwierdzili, że szkody związane z THC w obszarach pamięci „mogą się cofać przy dłuższych okresach abstynencji”.\n\nZdrowienie mózgu w ciągu roku i później\nPo roku bez konopi układ pamięciowy mózgu jest daleko na drodze zdrowienia: rozmiar hipokampa i wskaźniki zdrowia komórek mózgowych przesuwają się w kierunku normy, wspierając pamięć i regulację emocji.\n\nSygnał zdrowienia\nByli użytkownicy abstynentni przez około 29 miesięcy osiągali wyniki podobne do osób nieużywających w pomiarach zdrowia hipokampa. Po roku układ pamięciowy jest już na udokumentowanej ścieżce w kierunku normy.';

  @override
  String get mdmaReferenceDay1 =>
      'Po MDMA: zejście\n\nŹródło: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nSkąd bierze się gorszy nastrój\nMDMA powoduje duży wyrzut serotoniny, a także częściowo dopaminy. Później dostępność serotoniny w mózgu jest przejściowo obniżona. Przegląd opisuje spadek nastroju, tzw. „midweek blues”, obserwowany zarówno u nowych, jak i doświadczonych użytkowników 2–5 dni po użyciu.\n\nCo pomaga\n• Nawodnienie i wartościowe jedzenie\n• Sen\n• Cierpliwość — ten spadek jest przejściowy, a nie trwały\n\nZejście po jednorazowym użyciu różni się od odstawienia związanego z zależnością. Ten sam przegląd opisuje to drugie jako mogące obejmować głód substancji, ale bez istotnych objawów fizycznych.';

  @override
  String get mdmaReferenceDay3 =>
      'Kilka dni po MDMA\n\nŹródło: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\n„Midweek blues”\nTo mniej więcej okres opisywany w przeglądzie jako „midweek blues”: obniżenie nastroju mierzone 2–5 dni po użyciu zarówno u nowych, jak i doświadczonych użytkowników, związane z krótkotrwałym spadkiem serotoniny, a nie trwałą zmianą.\n\nCo zaczyna się poprawiać\n• Nastrój zwykle odbija od najniższego punktu\n• Wraca energia\n• Sen zaczyna się normalizować';

  @override
  String get mdmaReferenceDay7 =>
      'Tydzień po MDMA\n\nŹródło: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nPo okresie „midweek blues”\nDla większości osób tydzień oznacza, że minęło już 2–5-dniowe okno, które przegląd wiąże z ostrym zejściem, więc nastrój powinien wracać do normy. Autorzy zauważają, że przy intensywnym lub powtarzanym używaniu głód substancji może utrzymywać się jako element zależności, choć nie opisują znaczących fizycznych objawów odstawienia.\n\nKiedy szukać pomocy\nJeśli po tygodniu nadal utrzymują się obniżony nastrój, lęk lub problemy ze snem, może to być coś więcej niż zwykłe zejście i warto porozmawiać ze specjalistą.';

  @override
  String get mdmaReferenceDay14 =>
      'Dwa tygodnie bez MDMA\n\nŹródło: Meyer (2013), \"3,4-Methylenedioxymethamphetamine (MDMA): Current Perspectives,\" Substance Abuse and Rehabilitation\n\nPrzebieg regeneracji\nPo jednorazowym użyciu dwa tygodnie to znacznie później niż 2–5-dniowy spadek nastroju opisany w tym przeglądzie, więc nastrój, sen i koncentracja powinny być stabilniejsze. Po intensywniejszym lub powtarzanym używaniu regeneracja trwa dłużej, a badania obrazowe osób abstynentnych pokazują wzrost zdolności układu serotoninowego do wychwytu zwrotnego wraz z utrzymywaniem abstynencji.\n\nCo to oznacza dla Ciebie\nJeśli używanie było okazjonalne, najtrudniejszy etap prawdopodobnie jest już za Tobą. Jeśli było częste lub intensywne, daj sobie czas — pełna regeneracja sygnalizacji serotoninowej trwa dłużej niż dwa tygodnie i jest omawiana przy kolejnych kamieniach milowych.';

  @override
  String get mdmaReferenceDay30 =>
      'Miesiąc bez MDMA\n\nŹródło: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" PubMed\n\nGdzie jesteś po miesiącu\nOstre zejście i objawy odstawienia są już daleko za Tobą, a nastrój, myślenie i pamięć są stabilniejsze. Badania obrazowe pokazują, że MDMA zmniejsza zdolność mózgu do przetwarzania serotoniny i że zdolność ta poprawia się wraz z utrzymywaniem abstynencji.\n\nSygnał regeneracji\nTe same badania pokazują poprawę zdolności układu serotoninowego do wychwytu zwrotnego przy długotrwałej abstynencji. Nastrój i funkcjonowanie układu serotoninowego poprawiają się wcześniej, podczas gdy pamięć ma własne tempo regeneracji — dalsza abstynencja wspiera oba procesy.';

  @override
  String get mdmaReferenceDay90 =>
      'Trzy miesiące bez MDMA\n\nŹródło: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" PubMed\n\nDalsza regeneracja\nPrzy utrzymywanej abstynencji układ serotoninowy nadal się regeneruje, szczególnie w głębszych obszarach mózgu. Nastrój i sen są zwykle stabilne na tym etapie.\n\nSygnał regeneracji\nDługotrwała abstynencja wspiera dalszą regenerację transporterów serotoniny w różnych obszarach mózgu, podczas gdy nastrój i sen pozostają stabilne, a poprawa myślenia i pamięci trwa nadal.';

  @override
  String get mdmaReferenceDay365 =>
      'Rok bez MDMA\n\nŹródło: \"Serotonin transporter availability, neurocognitive function and their correlation in abstinent MDMA users,\" PubMed\n\nRok później\nPo roku abstynencji przetwarzanie serotoniny w mózgu miało długi czas na regenerację, a nastrój jest zwykle stabilny.\n\nSygnał regeneracji\nPełny rok abstynencji daje układowi serotoninowemu długie okno regeneracji. Badania obrazowe pokazują, że zdolność wychwytu zwrotnego serotoniny wzrasta wraz z abstynencją, co czyni znaczną regenerację tego układu najbardziej wyraźnym sygnałem biologicznym na tym etapie.';

  @override
  String get methReferenceDay1 =>
      'Odstawienie metamfetaminy: pierwsze 24 godziny\n\nŹródło: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), PubMed\n\nZjazd\nMetamfetamina wywołuje duży wyrzut dopaminy; po przerwaniu używania układ ten jest początkowo wyczerpany. Badanie śledziło objawy odstawienia codziennie przez pierwsze trzy tygodnie abstynencji i wykazało, że ich ogólne nasilenie było największe w ciągu 24 godzin od ostatniego użycia — to „zjazd”, nagłe przejście od silnej stymulacji do fizycznego i psychicznego wyczerpania.\n\nObjawy pierwszego dnia\nBadanie opisało objawy, które są wtedy najbardziej nasilone:\n• Skrajne zmęczenie i zwiększona potrzeba snu (hipersomnia)\n• Większy apetyt, bo metamfetamina silnie go tłumi\n• Obniżony nastrój i utrata odczuwania przyjemności\n• Silny głód metamfetaminy\n• Lęk i drażliwość\n\nBezpieczeństwo fizyczne\nSam zespół odstawienia metamfetaminy zwykle nie zagraża życiu, ale mierzone w badaniu objawy depresyjne mogą być na początku ciężkie i obejmować myśli samobójcze. Szczególnie przy intensywnym używaniu zdecydowanie wskazany jest nadzór medyczny.\n\nZaczyna być lżej\nDobra wiadomość z badania: nasilenie jest najwyższe na samym początku, a potem spada. Od szczytu w pierwszej dobie objawy stopniowo zmniejszają się w kolejnych dniach — najtrudniejszy jest początek.';

  @override
  String get methReferenceDay3 =>
      'Odstawienie metamfetaminy: dzień trzeci — nadal faza ostra\n\nŹródło: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), PubMed\n\nPo szczycie\nBadanie wykazało, że ogólne nasilenie odstawienia osiąga szczyt w pierwszej dobie, a potem zmniejsza się mniej więcej liniowo przez ostrą fazę trwającą około 7–10 dni. Trzeciego dnia najwyższy punkt jest już za tobą, ale nadal trwa faza ostra — objawy pozostają wyraźne, mimo że trend jest spadkowy.\n\nObjawy trzeciego dnia\nObjawy śledzone w badaniu, które wciąż mogą być istotne:\n• Depresja i utrata przyjemności\n• Silny głód metamfetaminy\n• Trudności z koncentracją i jasnym myśleniem\n• Zaburzony sen — bezsenność na przemian z hipersomnią\n• Utrzymujące się zmęczenie\n\nSkąd to uczucie\nNasilenie odstawienia odzwierciedla duże zaburzenie układu dopaminowego po metamfetaminie. Objawy depresyjne były najbardziej widoczne w tych pierwszych dniach. Co ważne, badanie wykazało, że ogólne nasilenie odstawienia „spadło do poziomu zbliżonego do grupy kontrolnej pod koniec pierwszego tygodnia abstynencji”.\n\nTo minie\nNajtrudniejsze są pierwsze dni, a dane pokazują później stały spadek objawów. Pomaga pamiętać, że to przejściowy stan mózgu i układu nerwowego, a nie trwała kondycja.';

  @override
  String get methReferenceDay7 =>
      'Tydzień bez metamfetaminy: koniec fazy ostrej\n\nŹródło: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), PubMed\n\nKoniec fazy ostrej\nTo jedna z najbardziej pokrzepiających obserwacji badania. Ogólne nasilenie odstawienia, w tym śledzone objawy depresyjne, „spadło do poziomu zbliżonego do grupy kontrolnej pod koniec pierwszego tygodnia abstynencji”, co oznacza koniec fazy ostrej. Najbardziej stromy odcinek jest za tobą.\n\nDwie fazy odstawienia\nAutorzy opisali:\n• Fazę ostrą trwającą około 7–10 dni, w której nasilenie objawów stale spada od wczesnego szczytu\n• Fazę podostrą trwającą co najmniej kolejne dwa tygodnie, z łagodniejszymi, utrzymującymi się objawami\n\nCo może zostać w 7. dniu\nW fazie podostrej dominują już raczej wyzwania psychiczne niż ostry zjazd:\n• Obniżony nastrój, choć znacznie lepszy niż w pierwszych dniach\n• Głód metamfetaminy, szczególnie po bodźcach wyzwalających\n• Nadal regenerujące się koncentracja i pamięć\n• Sen, który wciąż się stabilizuje\n\nRegeneracja fizyczna trwa\nPo fazie ostrej wraca apetyt, a energia stopniowo rośnie, kiedy organizm regeneruje się po wpływie metamfetaminy na sen, odżywianie i układ sercowo-naczyniowy.';

  @override
  String get methReferenceDay30 =>
      'Miesiąc bez metamfetaminy: nastrój się stabilizuje, głód pozostaje\n\nŹródło: Zorick et al., \"Withdrawal symptoms in abstinent methamphetamine-dependent subjects,\" Addiction (2010), PubMed Central\n\nPierwsze pięć tygodni\nBadanie obserwowało osoby zależne od metamfetaminy, które pozostawały abstynentne do pięciu tygodni, i porównywało je ze zdrową grupą kontrolną. Daje to wyjątkowo czytelny obraz sytuacji po miesiącu.\n\nCo poprawiło się po miesiącu\n• Objawy depresyjne „znacznie zmniejszyły się w pierwszych 2 tygodniach abstynencji do stabilnego niskiego poziomu”, a pod koniec czwartego tygodnia zbliżały się do poziomu zdrowej grupy kontrolnej, choć nie były jeszcze statystycznie takie same\n• Objawy psychiatryczne i psychotyczne osiągnęły niski poziom pod koniec drugiego tygodnia\nPo 30 dniach ciężka depresja wczesnego odstawienia w dużej mierze więc ustąpiła — to realna, zmierzona poprawa.\n\nCo nadal się utrzymuje\nJedno zjawisko trwało dłużej: głód metamfetaminy „utrzymywał się na niższym poziomie przez całe 5 tygodni abstynencji”. Jest słabszy niż w pierwszym tygodniu, ale nie znika całkowicie, dlatego dalsze wsparcie nadal ma znaczenie.\n\nWniosek\nPo miesiącu mechanizmy mózgowe związane z nastrojem zregenerowały się na tyle, że codzienne samopoczucie może być znacznie lepsze niż na początku odstawienia. Utrzymujący się głód jest na tym etapie normalny i nie oznacza porażki.';

  @override
  String get methReferenceDay90 =>
      'Trzy miesiące bez metamfetaminy: regeneracja już trwa — daj jej czas\n\nŹródło: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nO badaniu\nTo przełomowe badanie obrazowe sprawdzało osoby używające metamfetaminy dwa razy — po około trzech miesiącach abstynencji i ponownie po około 14 miesiącach — aby zobaczyć, jak regeneruje się układ dopaminowy.\n\nGdzie jesteś po trzech miesiącach\nPo trzech miesiącach wczesny okres odstawienia jest dawno zakończony i trwa głębsza regeneracja układu dopaminowego. To samo badanie wykazało później, że białka wychwytujące dopaminę w obszarach nagrody i ruchu wzrosły o około 16%–19% po 12–17 miesiącach abstynencji.\n\nCo to oznacza\nPo 90 dniach ostry odstaw jest daleko za tobą, poprawiają się nastrój i sen, a udział w terapii może być bardziej efektywny. Głębsza regeneracja dopaminy trwa jednak dłużej, przez kolejny rok. Jeśli motywacja i odczuwanie przyjemności są jeszcze przytłumione po trzech miesiącach, mieści się to w trajektorii opisanej w badaniu i nie oznacza porażki.\n\nDlaczego warto dać sobie czas\nBadanie pokazało, że im dłuższa abstynencja, tym większa mierzona regeneracja transporterów dopaminy. Trzy miesiące to fundament, na którym poprawa może nadal się budować.';

  @override
  String get methReferenceDay180 =>
      'Sześć miesięcy bez metamfetaminy: serce może się regenerować\n\nŹródło: \"Stopping Drug Abuse Can Reverse Related Heart Damage,\" American College of Cardiology (2017), relacja z badania w JACC: Heart Failure\n\nMetamfetamina i serce\nMetamfetamina jest jedną z najbardziej kardiotoksycznych substancji rekreacyjnych. Może wywoływać ciężkie nadciśnienie i arytmie, a z czasem kardiomiopatię związaną z metamfetaminą — osłabienie mięśnia sercowego prowadzące do niewydolności serca.\n\nCo wykazało badanie\nAmerican College of Cardiology opisało pacjentów z kardiomiopatią związaną z metamfetaminą i wyraźnie obniżoną funkcją pompowania serca. Najważniejsza, optymistyczna obserwacja: zaprzestanie używania „może odwrócić uszkodzenia serca powodowane przez narkotyk i poprawić jego funkcję”. Osoby, które przestały używać, miały znacznie lepsze wyniki niż te, które kontynuowały. Autorzy podkreślali również, że wczesne rozpoznanie „może zapobiec dalszemu pogorszeniu kardiomiopatii”.\n\nDlaczego sześć miesięcy ma znaczenie\nKażdy miesiąc bez metamfetaminy usuwa powtarzające się toksyczne obciążenie serca i daje mięśniowi czas na regenerację. Po sześciu miesiącach układ sercowo-naczyniowy ma za sobą długi okres bez tego uszkadzającego bodźca — właśnie w takich warunkach badanie obserwowało poprawę.\n\nSygnał regeneracji\nDowody są obiecujące: zaprzestanie używania metamfetaminy może odwrócić związane z nią uszkodzenia serca i poprawić funkcję serca. Sześć miesięcy bez powtarzającego się działania stymulantu daje sercu istotne okno na regenerację.';

  @override
  String get methReferenceDay365 =>
      'Rok bez metamfetaminy: mierzalna regeneracja mózgu\n\nŹródło: Wang et al., \"Partial Recovery of Brain Metabolism in Methamphetamine Abusers After Protracted Abstinence,\" American Journal of Psychiatry (2004), PubMed\n\nCo pokazuje obrazowanie\nBadanie sprawdzało osoby używające metamfetaminy we wczesnej abstynencji i ponownie po 12–17 miesiącach. Wykazało rzeczywistą regenerację mózgu, przy czym jedne obszary wracały do normy szybciej niż inne.\n\nDobra wiadomość: głębokie struktury i myślenie\nWzgórze, głęboki ośrodek przekaźnikowy mózgu, zaczęło wykorzystywać energię bardziej prawidłowo wraz z dłuższą abstynencją. Ta poprawa wiązała się z lepszym ruchem i pamięcią werbalną, więc zmiany w obrazie mózgu miały przełożenie na realne funkcje.\n\nUkład nagrody regeneruje się wolniej\nPo 12–17 miesiącach głęboki ośrodek przekaźnikowy wyraźnie się zregenerował, co wiązało się z lepszym ruchem i pamięcią werbalną. Układy nagrody i motywacji również nadal się poprawiały, dlatego obraz po roku wskazuje na dużą regenerację myślenia i pamięci.\n\nCo to oznacza po roku\nPo roku myślenie i pamięć mogą działać znacznie lepiej niż na początku zdrowienia — to jasna, mierzalna zmiana. Jeśli motywacja lub zdolność odczuwania przyjemności wciąż czasem pozostają w tyle, jest to zgodne z nauką, a nie oznaką osobistej porażki: układ nagrody może regenerować się wolniej, a pewne różnice utrzymywać się ponad rok.';

  @override
  String get methReferenceDay420 =>
      '14 miesięcy bez metamfetaminy: marker dopaminy się odbudowuje\n\nŹródło: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\nNajważniejszy wynik\nTo przełomowe badanie obrazowe sprawdzało osoby używające metamfetaminy we wczesnej abstynencji i ponownie po około 12–17 miesiącach. Białka wychwytujące dopaminę wzrosły o około 16%–19% w obszarach nagrody i ruchu, osiągając poziomy, które nie różniły się już istotnie od zdrowej grupy kontrolnej. Dłuższa abstynencja wiązała się z większą regeneracją.\n\nDlaczego DAT ma znaczenie\nBiałka te wychwytują dopaminę po jej uwolnieniu. Metamfetamina zmniejsza ich liczbę, przez co układ dopaminowy jest gorzej regulowany. Ich odbudowa po około 14 miesiącach to rzeczywisty i mierzalny sygnał regeneracji.\n\nSygnał regeneracji\nPo 12–17 miesiącach białka wychwytujące dopaminę w obszarach nagrody i ruchu wzrosły o około 16%–19% i osiągnęły poziom zdrowej grupy kontrolnej. Układ dopaminowy mierzalnie wrócił w stronę normy, a myślenie, pamięć i ruch mogły nadal się poprawiać.\n\nCo to oznacza po 14 miesiącach\nUkład dopaminowy mierzalnie wraca w stronę prawidłowego funkcjonowania — to realny powód do optymizmu. Pełna regeneracja funkcji, takich jak pamięć, motywacja i precyzja ruchów, może jednak pozostawać w tyle za zmianami widocznymi w obrazowaniu i nadal poprawiać się przy utrzymanej abstynencji.';

  @override
  String get methReferenceDay730 =>
      'Dwa lata bez metamfetaminy: myślenie i nastrój nadal się poprawiają\n\nŹródło: Iudicello et al., \"Longer Term Improvement in Neurocognitive Functioning and Affective Distress Among Methamphetamine Users Who Achieve Stable Abstinence,\" Journal of Clinical and Experimental Neuropsychology (2010), PubMed Central\n\nRegeneracja trwająca ponad rok\nBadanie śledziło osoby używające metamfetaminy przez około 13 miesięcy i porównywało osoby utrzymujące stabilną abstynencję z tymi, które nadal używały, oraz ze zdrową grupą kontrolną. Stabilna abstynencja poprawiała ogólne funkcje poznawcze i zmniejszała cierpienie emocjonalne, a korzyści utrzymywały się ponad rok.\n\nCo się poprawia\n• Ogólne funkcje poznawcze osób utrzymujących abstynencję osiągnęły poziom zdrowej grupy kontrolnej, podczas gdy osoby nadal używające pozostawały wyraźnie upośledzone\n• Największe poprawy dotyczyły szybkości przetwarzania i zdolności ruchowych, szczególnie u osób najbardziej zaburzonych na początku\n• Nastrój poprawił się wyraźnie: tylko osoby utrzymujące abstynencję wykazały istotną poprawę depresji i ogólnego nastroju\n\nSygnał regeneracji\nOsoby ze stabilną abstynencją osiągnęły poziom zdrowej grupy kontrolnej w ogólnych funkcjach poznawczych i zgłaszały mniejsze cierpienie emocjonalne. Uczenie werbalne, pamięć robocza, planowanie i koncentracja mogą poprawiać się także po pierwszym roku, więc trend regeneracji może trwać w drugim roku.\n\nPo dwóch latach\nWniosek oparty na dowodach: utrzymana abstynencja może przynosić korzyści długo po pierwszym roku — jaśniejsze myślenie, lepszy nastrój i stale lepsze funkcjonowanie, nawet jeśli niektóre obszary potrzebują więcej czasu.';

  @override
  String get methMilestone1095Title => 'Trzy lata - Trwała poprawa';

  @override
  String get methMilestone1095Description =>
      'Trzy lata bez metamfetaminy to trwała zmiana liczona w latach, nie tygodniach. Osiągnięciem jest sama jej wytrwałość: nawyki i wsparcie w zdrowieniu miały kolejny pełny rok, by się umocnić.';

  @override
  String get methReferenceDay1095 =>
      'Trzy lata - Trwała poprawa\n\nŹródło: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\nPrzegląd systematyczny i metaanaliza z 2026 roku objęły 68 niezależnych badań z 9 045 uczestnikami. Analizy zmian podczas abstynencji obejmowały okresy tylko do 280 dni, a pewność dowodów w poszczególnych obszarach oceniono jako bardzo niską. Dane te nie pozwalają wyznaczyć biologicznego terminu pełnego powrotu do zdrowia na tę rocznicę.\n\nTrzy lata bez metamfetaminy to trwała zmiana liczona w latach, nie tygodniach. Osiągnięciem jest sama jej wytrwałość: nawyki i wsparcie w zdrowieniu miały kolejny pełny rok, by się umocnić.';

  @override
  String get methMilestone1460Title => 'Cztery lata - Mocne podstawy';

  @override
  String get methMilestone1460Description =>
      'Cztery lata to solidny okres trwałej zmiany. Badania nie wyznaczają czteroletniej mety regeneracji mózgu, dlatego ten kamień milowy świętuje kolejny pełny rok ochrony tego, co udało Ci się zbudować.';

  @override
  String get methReferenceDay1460 =>
      'Cztery lata - Mocne podstawy\n\nŹródło: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\nPrzegląd systematyczny i metaanaliza z 2026 roku objęły 68 niezależnych badań z 9 045 uczestnikami. Analizy zmian podczas abstynencji obejmowały okresy tylko do 280 dni, a pewność dowodów w poszczególnych obszarach oceniono jako bardzo niską. Dane te nie pozwalają wyznaczyć biologicznego terminu pełnego powrotu do zdrowia na tę rocznicę.\n\nCztery lata to solidny okres trwałej zmiany. Badania nie wyznaczają czteroletniej mety regeneracji mózgu, dlatego ten kamień milowy świętuje kolejny pełny rok ochrony tego, co udało Ci się zbudować.';

  @override
  String get methMilestone1825Title => 'Pięć lat - Trwała zmiana';

  @override
  String get methMilestone1825Description =>
      'Pięć lat bez metamfetaminy to ważny długoterminowy kamień milowy. Nauka nie może obiecać biologicznego punktu końcowego po pięciu latach; pewne jest pięć lat trwałej zmiany wartej świętowania.';

  @override
  String get methReferenceDay1825 =>
      'Pięć lat - Trwała zmiana\n\nŹródło: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\nPrzegląd systematyczny i metaanaliza z 2026 roku objęły 68 niezależnych badań z 9 045 uczestnikami. Analizy zmian podczas abstynencji obejmowały okresy tylko do 280 dni, a pewność dowodów w poszczególnych obszarach oceniono jako bardzo niską. Dane te nie pozwalają wyznaczyć biologicznego terminu pełnego powrotu do zdrowia na tę rocznicę.\n\nPięć lat bez metamfetaminy to ważny długoterminowy kamień milowy. Nauka nie może obiecać biologicznego punktu końcowego po pięciu latach; pewne jest pięć lat trwałej zmiany wartej świętowania.';

  @override
  String get nitrousOxideReferenceDay1 =>
      'Dzień pierwszy: gaz zniknął, ale trzeba uważać na B12\n\nŹródło: Knuf & Maani, „Nitrous Oxide”, StatPearls (NCBI Bookshelf)\n\nJak szybko znika\nPodtlenek azotu zaczyna działać szybko, w ciągu 2–5 minut, i po zaprzestaniu inhalacji równie szybko jest usuwany z organizmu. Dziś sam gaz nie pozostaje już w organizmie.\n\nPrawdziwe ryzyko nie polega na obecności gazu\nPo zaprzestaniu używania ważne jest to, co powtarzana ekspozycja mogła już spowodować. Podtlenek azotu unieczynnia syntazę metioninową, enzym zależny od witaminy B12. StatPearls podaje, że powtarzana ekspozycja, zawodowa lub rekreacyjna, może prowadzić do niedokrwistości megaloblastycznej oraz zaburzeń funkcji mózgu i nerwów, a w rzadkich przypadkach do zwyrodnienia rdzenia kręgowego.\n\nJeśli używanie było intensywne lub częste\nNie opisano fizycznego zespołu odstawiennego po podtlenku azotu takiego jak po opioidach czy alkoholu. Pierwszy dzień nie oznacza więc, że organizm domaga się substancji. Chodzi o zwracanie uwagi na objawy związane z B12, opisane w kolejnych etapach, i o konsultację medyczną, jeśli się pojawią.';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72 godziny: bez fizycznego odstawienia, ale obserwuj objawy neurologiczne\n\nŹródło: Knuf & Maani, StatPearls; Tikaria et al. (2026), Cureus\n\nW przeciwieństwie do opioidów czy alkoholu nie opisano, aby podtlenek azotu wywoływał fizyczny zespół odstawienny. Na tym etapie chęć użycia wynika z nawyku i głodu psychicznego, a nie z tego, że organizm potrzebuje substancji do funkcjonowania.\n\nNa co zwracać uwagę\nPrzegląd systematyczny 1 809 przypadków rekreacyjnego używania podtlenku azotu (Tikaria et al., 2026) wykazał, że objawy ze strony mózgu i nerwów, zwłaszcza mrowienie lub drętwienie (parestezje), były najczęstszym objawem szkód związanych z B12. Często występowały nawet wtedy, gdy standardowe badania krwi wyglądały prawidłowo. Zgłaszano także problemy z chodem i osłabienie.\n\nJeśli zauważysz któryś z tych objawów\nZgłoś się po ocenę medyczną. Ten sam przegląd wykazał, że standardowe badania krwi, takie jak hemoglobina i B12 w surowicy, nie wykrywały istotnej części przypadków. Kwas metylomalonowy (MMA) i homocysteina są bardziej czułymi markerami i warto poprosić o ich oznaczenie, informując o używaniu podtlenku azotu.';

  @override
  String get nitrousOxideReferenceDay7 =>
      'Tydzień: przy intensywnym używaniu warto się zbadać\n\nŹródło: Tikaria et al. (2026), „The Toxic Legacy of Recreational Nitrous Oxide Use”, Cureus\n\nCo pokazują dowody\nPrzegląd systematyczny wykazał, że niedobór witaminy B12 wywołany podtlenkiem azotu często ma charakter „funkcjonalny”: u około połowy osób dotkniętych problemem poziom B12 w surowicy wyglądał prawidłowo mimo rzeczywistych uszkodzeń mózgu i nerwów. Homocysteina i MMA były nieprawidłowe znacznie częściej, odpowiednio u 84% i 73% badanych osób, dlatego są bardziej wiarygodnymi markerami.\n\nCo można zrobić\nJeśli używanie było intensywne lub częste, tydzień bez podtlenku azotu to rozsądny moment na wizytę u lekarza i poproszenie konkretnie o oznaczenie homocysteiny i MMA, a nie tylko standardowego poziomu B12. Jest to szczególnie ważne przy mrowieniu, drętwieniu, problemach z równowagą lub niewyjaśnionym osłabieniu.\n\nPoprawa neurologiczna po zaprzestaniu używania podtlenku azotu i leczeniu witaminą B12 jest często opisywana. Duże serie kliniczne donoszą o częściowej lub pełnej poprawie u większości obserwowanych pacjentów, a regeneracja może trwać przez pierwsze miesiące po leczeniu.';

  @override
  String get nitrousOxideReferenceDay14 =>
      'Dwa tygodnie: objawy neurologiczne wymagają dalszej obserwacji\n\nŹródło: Tikaria et al. (2026), Cureus; Knuf & Maani, StatPearls\n\nCo opisano\nRaporty i serie przypadków przeanalizowane przez Tikaria et al. opisują uszkodzenia nerwów związane z podtlenkiem azotu jako utratę czucia, ataksję chodu i czasem osłabienie utrudniające chodzenie. Objawy te mogą przypominać inne choroby neurologiczne i bywają przeoczane, jeśli personel medyczny nie wie o używaniu podtlenku azotu.\n\nCo wiadomo o czasie regeneracji\nŻadne z tych źródeł nie podaje, jak długo zwykle trwa powrót do zdrowia po zaprzestaniu używania i leczeniu niedoboru. Raporty przypadków pokazują bardzo różne wyniki – od pełnej poprawy po trwałe deficyty – zależnie głównie od stopnia uszkodzenia przed rozpoznaniem. W literaturze powtarza się natomiast, że wcześniejsze leczenie wiąże się z lepszym rokowaniem.\n\nJeśli nie było jeszcze badań\nPo dwóch tygodniach nadal warto wykonać badania krwi, nawet bez objawów – szczególnie homocysteinę i MMA, a nie tylko B12 w surowicy.';

  @override
  String get nitrousOxideReferenceDay30 =>
      'Miesiąc: nawyk i głód psychiczny, nie zależność fizyczna\n\nŹródło: Knuf & Maani, „Nitrous Oxide”, StatPearls (NCBI Bookshelf)\n\nGdzie jesteś\nStatPearls nie opisuje podtlenku azotu jako substancji wywołującej zespół zależności fizycznej. Po miesiącu utrzymujące się impulsy są więc raczej związane z nawykiem, sytuacjami społecznymi lub nudą niż z organizmem nadal przystosowującym się do braku substancji.\n\nKwestia B12\nJeśli wykonano badania i wdrożono leczenie niedoboru B12, miesiąc jest rozsądnym momentem, by lekarz sprawdził, czy poziom witaminy i objawy odpowiedziały na leczenie. Jeśli przy intensywnym używaniu nie było jeszcze badań, nadal warto o nie zapytać.\n\nCo jest chronione\nKażdy miesiąc bez używania to miesiąc bez dodatkowego unieczynniania syntazy metioninowej i bez zwiększania związanego z tym ryzyka dla mózgu i nerwów.';

  @override
  String get nitrousOxideReferenceDay90 =>
      'Trzy miesiące: czas na kontrolę, jeśli jeszcze jej nie było\n\nŹródło: Tikaria et al. (2026), „The Toxic Legacy of Recreational Nitrous Oxide Use”, Cureus\n\nCo wiemy – i czego nie wiemy\nPodstawa dowodowa opiera się na raportach i seriach przypadków, a nie na kontrolowanych badaniach regeneracji. Nie ma więc wiarygodnego opublikowanego harmonogramu opisującego, jak objawy powinny ustępować dokładnie po trzech miesiącach. Wyniki są bardzo różne: część osób z łagodnym, wcześnie wykrytym niedoborem wraca do zdrowia całkowicie, natomiast późne rozpoznanie lub poważniejsze uszkodzenie nerwów może pozostawić trwałe deficyty.\n\nCo można zrobić teraz\nJeśli występowały objawy neurologiczne, a nie było jeszcze kontrolnych badań krwi lub konsultacji specjalistycznej, trzy miesiące bez używania to rozsądny moment, by je zaplanować. Jeśli leczenie przynosi poprawę, warto z lekarzem potwierdzić, że ten trend się utrzymuje.\n\nNajważniejsze jest dalsze nieużywanie\nPrzegląd jest spójny w jednej kwestii: dalsza ekspozycja nadal unieczynnia B12 i zwiększa ryzyko. Nieużywanie jest najważniejszym czynnikiem działającym na twoją korzyść.';

  @override
  String get nitrousOxideReferenceDay365 =>
      'Rok: najlepszą ochroną jest dalsze nieużywanie\n\nŹródło: Knuf & Maani, StatPearls; Tikaria et al. (2026), Cureus\n\nGdzie naprawdę kończą się dowody\nŻadne ze źródeł nie obiecuje określonego terminu pełnej regeneracji. Literatura dotycząca podtlenku azotu i niedoboru B12 opiera się niemal wyłącznie na pojedynczych raportach przypadków, a nie na długoterminowych badaniach obserwacyjnych. Dobrze ustalony jest mechanizm: podtlenek azotu unieczynnia witaminę B12 przy każdej ekspozycji, a zaprzestanie używania usuwa to dalsze źródło szkody.\n\nJeśli występowały objawy związane z niedoborem\nRaporty przypadków pokazują bardzo szerokie spektrum wyników – od pełnej poprawy po utrzymujące się objawy neurologiczne – zależne głównie od stopnia uszkodzenia i tego, jak wcześnie rozpoczęto leczenie. Jeśli po roku objawy nadal się utrzymują, to powód, by kontynuować opiekę neurologiczną, a nie znak, że nic więcej nie można zrobić. Regeneracja nerwów może trwać długo.\n\nCo jest pewne\nRok bez podtlenku azotu to rok bez dalszego unieczynniania syntazy metioninowej. To jedna rzecz, którą oba źródła wyraźnie wspierają.';

  @override
  String get opioidReferenceDay1 =>
      'Odstawienie opioidów: pierwszy dzień\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings\", World Health Organization (2009), NCBI Bookshelf\n\n⚠ Uwaga dotycząca bezpieczeństwa\nOdstawienie opioidów rzadko bywa śmiertelne u osób poza tym zdrowych, ale może powodować bardzo silne dolegliwości fizyczne i wiąże się z dużym ryzykiem powrotu do używania. Powrót po okresie abstynencji jest szczególnie niebezpieczny, ponieważ tolerancja szybko spada — dawka wcześniej uznawana za zwykłą może wtedy doprowadzić do śmiertelnego przedawkowania. Zdecydowanie zaleca się nadzór medyczny i leczenie agonistami opioidowymi.\n\nKiedy zaczyna się odstawienie\nWedług WHO czas początku zależy od rodzaju opioidu:\n• Opioidy krótkodziałające (heroina, oksykodon): początek 8–24 godziny po ostatnim użyciu, czas trwania 4–10 dni\n• Opioidy długodziałające (metadon): początek 12–48 godzin, czas trwania 10–20 dni\n\nObjawy pierwszego dnia\nWHO wymienia wczesne cechy odstawienia opioidów:\n• Lęk i pobudzenie\n• Kurcze i bóle mięśni\n• Łzawienie oczu i wodnista wydzielina z nosa\n• Ziewanie i pocenie się\n• Bezsenność z napadami gorąca i zimna\n• Wczesne nudności\n\nDlaczego jest tak trudno\nUkład opioidowy reguluje ból, stres, dobrostan emocjonalny i podstawowe poczucie komfortu. Długotrwałe używanie opioidów hamuje własną produkcję opioidów przez organizm, w tym endorfin. Po odstawieniu ciało przez pewien czas funkcjonuje bez zwykłego poziomu tego naturalnego wsparcia, dlatego ból, lęk i dyskomfort mogą być bardzo nasilone. WHO zaleca opiekę wspomagającą, m.in. picie 2–3 litrów wody dziennie oraz monitorowanie stanu 3–4 razy na dobę.';

  @override
  String get opioidReferenceDay7 =>
      'Tydzień bez opioidów: najsilniejsze objawy słabną\n\nŹródło: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings\", World Health Organization (2009), NCBI Bookshelf\n\nSzczyt i stopniowe wygaszanie\nWedług WHO odstawienie opioidów krótkodziałających trwa zwykle 4–10 dni. Objawy nasilają się na początku, a następnie w tym przedziale stopniowo słabną. Pod koniec pierwszego tygodnia:\n• Wymioty i biegunka zwykle w dużej mierze ustępują\n• Kurcze mięśni stają się mniej nasilone\n• Ogólny dyskomfort fizyczny wyraźnie się zmniejsza\n\nCo może pozostać w 7. dniu\nMimo poprawy ostrych objawów fizycznych nadal mogą występować:\n• Bezsenność — zaburzenia snu należą do najbardziej uporczywych objawów odstawiennych\n• Obniżony nastrój i spłycenie emocji\n• Zmęczenie i osłabienie\n• Głód opioidowy\n• Lęk\n\nObjawy po ostrej fazie\nPo pierwszym okresie odstawienia problemy ze snem, zmiany nastroju i nawroty głodu mogą utrzymywać się przez tygodnie lub miesiące. W tej dłuższej fazie ciągłe wsparcie ma duże znaczenie.\n\nLeczenie agonistami opioidowymi\nWHO opisuje metadon i buprenorfinę jako skuteczne terapie zmniejszające nasilenie objawów odstawiennych i wspierające powrót do zdrowia. Leki te obniżają także śmiertelność związaną z zaburzeniem używania opioidów, a wiele osób w trwałym zdrowieniu korzysta z nich również na początku leczenia.';

  @override
  String get opioidReferenceDay14 =>
      'Dwa tygodnie bez opioidów: sen zaczyna się poprawiać\n\nŹródło: recenzowane badania farmakologiczne dotyczące opioidów i snu\n\nZwiązek opioidów ze snem\nBadania opisują dwukierunkowy związek między używaniem opioidów a zaburzeniami snu. Opioidy mogą silnie zakłócać prawidłową architekturę snu przez kilka mechanizmów:\n• Ograniczenie snu wolnofalowego (głębokiego)\n• Zaburzenie snu REM\n• Powodowanie zaburzeń oddychania podczas snu, w tym centralnego bezdechu sennego\n• Zaburzanie regulacji rytmu dobowego\n\nBłędne koło\nOpioidy pogarszają sen, a zły sen zwiększa wrażliwość na ból i nasila głód substancji, co może sprzyjać dalszemu używaniu. Wychodzenie z zależności opioidowej oznacza więc również przerwanie tego cyklu.\n\nSen po dwóch tygodniach\nPo 14 dniach abstynencji sen może zacząć wracać do normy:\n• Centralny bezdech senny, jeśli występował, może ustępować w ciągu dni\n• Sen głęboki wolnofalowy zaczyna się odbudowywać\n• Udział snu REM wraca w stronę prawidłowych proporcji\n• Zasypianie staje się bardziej regularne\n\nDla wielu osób sen nadal jest trudny po dwóch tygodniach, ale kierunek zmian jest korzystny. Lepszy sen wspiera nastrój, zmniejsza głód i pomaga odzyskać jasność myślenia potrzebną w zdrowieniu.';

  @override
  String get opioidReferenceDay30 =>
      'Miesiąc bez opioidów: myślenie i pamięć zaczynają się poprawiać\n\nŹródło: Mayo Clinic\n\nZrozumieć zaburzenie używania opioidów\nMayo Clinic wyjaśnia, że opioidy wiążą się z receptorami w mózgu i całym ciele, powodując działanie przeciwbólowe, euforię i senność. Przy powtarzanym używaniu mózg reaguje słabiej i produkuje mniej własnych substancji o działaniu opioidowym, co prowadzi do zależności fizycznej.\n\nMyślenie i pamięć po miesiącu\nPo 30 dniach może być widoczna istotna poprawa myślenia i pamięci. Najsilniejsza mgła poznawcza ustępuje, a przednie obszary mózgu odpowiedzialne za planowanie i samokontrolę odzyskują sprawność:\n• Poprawia się podejmowanie decyzji\n• Odbudowuje się pamięć robocza\n• Rośnie szybkość przetwarzania informacji\n• Koncentracja staje się stabilniejsza\n\nUkład endorfin\nPo miesiącu naturalny układ endorfinowy mózgu aktywnie się odbudowuje: organizm ponownie wytwarza więcej własnych substancji opioidopodobnych i bardziej prawidłowo na nie reaguje. Spłycenie emocji i obniżona tolerancja bólu mogą dalej się poprawiać.\n\nZapobieganie nawrotom\nMayo Clinic podkreśla, że miesiąc abstynencji nie oznacza końca ryzyka nawrotu. Tolerancja znacznie spada, dlatego powrót do wcześniejszych dawek wiąże się z poważnym ryzykiem przedawkowania.';

  @override
  String get opioidReferenceDay60 =>
      'Dwa miesiące bez opioidów: obwody stresu zaczynają się wyciszać\n\nŹródło: \"Neuroplasticity of the extended amygdala in opioid withdrawal and prolonged opioid abstinence\", Frontiers in Pharmacology (2023)\n\nSkąd biorą się negatywne emocje\nPrzegląd opisuje, jak długotrwałe używanie opioidów zmienia obwody stresu i lęku w mózgu. Podczas odstawienia obwody te stają się nadaktywne, a sygnalizacja dopaminowa w układzie nagrody spada. To połączenie pomaga wyjaśnić lęk, obniżony nastrój i głód substancji na początku zdrowienia.\n\nDlaczego po dwóch miesiącach może być lżej\nWażne jest to, że część tych zmian jest odwracalna. W modelach zwierzęcych spadek gęstości kolców dendrytycznych w powłoce jądra półleżącego opisano jako \"utrzymujący się, ale odwracalny\", z powrotem w stronę wartości sprzed ekspozycji na substancję w ciągu kilku tygodni. Wraz z ponowną regulacją obwodów stresu i nagrody słabnie biologiczna podstawa emocjonalnego chaosu wczesnego zdrowienia.\n\nSygnał zdrowienia\nOdwracalne zmiany gęstości kolców dendrytycznych i obwodów stresu pokazują rzeczywisty proces biologicznej regeneracji: obwody napędzające negatywny stan emocjonalny zależności podczas abstynencji przesuwają się w stronę stanu sprzed używania.';

  @override
  String get opioidReferenceDay90 =>
      'Trzy miesiące bez opioidów: układ nagrody zaczyna się regenerować\n\nŹródło: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies\", Drug and Alcohol Dependence (2022), PubMed Central\n\nDopamina i opioidy\nOpioidy zwiększają uwalnianie dopaminy w układzie nagrody. Długotrwałe używanie może ten układ osłabić: w jednym badaniu obrazowym poziom białek transportujących dopaminę był na początku około 30% niższy niż u osób zdrowych. Pomaga to wyjaśnić utratę zdolności odczuwania przyjemności w zaburzeniu używania opioidów i we wczesnym zdrowieniu.\n\nRegeneracja jest stopniowa\nPrzegląd zebrał badania podłużne, w których te same osoby skanowano ponownie w czasie abstynencji. Niedobór transportera dopaminy poprawił się o około 20% w ciągu 6–12 miesięcy, a niektóre nieprawidłowości istoty szarej i białej w obszarach czołowych, widoczne na początku odstawienia, po około miesiącu nie były już wykrywalne. Po trzech miesiącach proces jest nadal na wczesnym etapie: układ nagrody i obszary czołowe mierzalnie się poprawiają, ale regeneracja nie jest zakończona.\n\nCo można zauważyć\nWraz z regeneracją tych obwodów wiele osób około 90. dnia zauważa:\n• Więcej naturalnej przyjemności z aktywności, jedzenia i relacji\n• Mniejszy głód w porównaniu z początkiem zdrowienia\n• Jaśniejsze myślenie i lepsze decyzje\n\nSygnał zdrowienia\nPodłużne badania obrazowe u ludzi pokazują wzrost dostępności transportera dopaminy przez 6–12 miesięcy abstynencji, podczas gdy nieprawidłowości czołowej istoty szarej i białej zaczynają normalizować się wcześniej. Po 90 dniach mierzalne oznaki regeneracji mózgu są już obecne.';

  @override
  String get opioidReferenceDay180 =>
      'Sześć miesięcy bez opioidów: układ odpornościowy zaczyna się regenerować\n\nŹródło: \"Effects of opioid tolerance and withdrawal on the immune system\", Journal of Neuroimmune Pharmacology (2006), PubMed\n\nOpioidy i układ odpornościowy\nPrzegląd pokazuje, że długotrwałe używanie opioidów może osłabiać odporność na kilka sposobów:\n• Bezpośrednie działanie opioidów na komórki odpornościowe (limfocyty T, komórki NK, makrofagi)\n• Zaburzenie cząsteczek sygnalizacyjnych układu odpornościowego\n• Zaburzenie osi podwzgórze–przysadka–nadnercza (HPA)\n• Zwiększona podatność na infekcje\n\nSygnał zdrowienia\nDługotrwałe opioidy tłumią kilka elementów układu odpornościowego. Po sześciu miesiącach bez opioidów ten ciągły wpływ nie występuje już od pół roku, a układ odpornościowy ma czas na powrót w stronę prawidłowej funkcji.\n\nCo oznacza sześć miesięcy\nSześć miesięcy bez opioidów daje komórkom odpornościowym, sygnalizacji immunologicznej i układowi stresu organizmu dłuższy czas na regenerację.\n\nDlaczego to nadal ważne\nMa to szczególne znaczenie dla osób, które wstrzykiwały opioidy i były narażone na dodatkowe infekcje, takie jak HIV i wirusowe zapalenie wątroby typu C. Zaprzestanie używania opioidów, lepsze odżywianie i utrzymywanie abstynencji tworzą warunki sprzyjające dalszej regeneracji odporności.';

  @override
  String get opioidReferenceDay365 =>
      'Rok bez opioidów: regeneracja struktury i chemii mózgu\n\nŹródło: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies\", Drug and Alcohol Dependence (2022), PubMed Central\n\nCo pokazują badania obrazowe u ludzi\nPrzegląd zebrał badania, w których te same osoby z zaburzeniem używania opioidów skanowano więcej niż raz podczas abstynencji. Wyniki konsekwentnie wskazują na regenerację:\n• Białka transportujące dopaminę w obszarach nagrody i ruchu, początkowo około 30% poniżej normy, wzrosły o około 20% w ciągu 6–12 miesięcy bez opioidów\n• Nieprawidłowości istoty szarej w obszarach czołowych widoczne we wczesnym odstawieniu po około miesiącu nie były już wykrywalne\n• Istota biała w obszarach czołowych i zakręcie obręczy oraz spoczynkowa aktywność czołowa także zaczynały normalizować się w pierwszym miesiącu\n\nGdzie znajduje się rok\nPo dwunastu miesiącach jesteś na końcu lub poza najdłuższym okresem mierzonym w tych badaniach. Układ dopaminowy miał najwięcej czasu na regenerację, a obwody czołowe wspierające samokontrolę i ocenę sytuacji poprawiały się przez wiele miesięcy — to biologiczny odpowiednik jaśniejszego myślenia, słabszego głodu i stabilniejszego nastroju opisywanych po roku.\n\nSygnał zdrowienia\nPo roku obrazowanie u ludzi wyraźnie wskazuje na regenerację: dostępność transportera dopaminy rosła przez 6–12 miesięcy, a czołowe nieprawidłowości strukturalne i funkcjonalne miały wiele miesięcy na normalizację.';

  @override
  String get opioidReferenceDay730 =>
      'Dwa lata bez opioidów: stabilna podstawa\n\nŹródło: \"Treatment of Opioid Use Disorder\", Centers for Disease Control and Prevention (CDC)\n\nPrzewlekła choroba, którą można dobrze leczyć\nCDC opisuje zaburzenie używania opioidów jako \"przewlekłą chorobę, która może dotknąć każdego\" oraz \"stan medyczny, a nie moralne niepowodzenie\". Dwa lata trwałego zdrowienia oznaczają skuteczne przejście przez jeden z najbardziej podatnych na nawrót okresów.\n\nCo według CDC działa\nWytyczne CDC koncentrują się na leczeniu, które pomaga utrzymać stabilność w dłuższej perspektywie:\n• Leki stosowane w zaburzeniu używania opioidów — buprenorfina, metadon i naltrekson — uznawane za szczególnie skuteczne\n• Łączenie leków z terapią behawioralną i poradnictwem\n• Długość leczenia dopasowana do potrzeb danej osoby\nCDC wskazuje, że leki te pomagają \"normalizować chemię mózgu\" i łagodzić głód opioidowy.\n\nBezpieczeństwo\nCDC zachęca osoby w zdrowieniu do rozmowy z lekarzem o ryzyku powrotu do używania i przedawkowania oraz do posiadania naloksonu pod ręką. Tolerancja podczas abstynencji spada, dlatego powrót do opioidów po tak długiej przerwie może być szczególnie niebezpieczny — świadomość tego ryzyka pomaga chronić dotychczasowe postępy.\n\nDwa lata\nCDC podkreśla, że zdrowienie jest często procesem długoterminowym, a nie linią mety. Dwa lata nie są końcem drogi — to stabilna, zdrowa podstawa i silny sygnał, że stosowane podejście działa.';

  @override
  String get opioidReferenceDay1095 =>
      'Trzy lata - Trwała zmiana\n\nŹródło: amerykańskie Centra Kontroli i Prewencji Chorób (CDC), „Leczenie zaburzenia używania opioidów”\n\nWytyczne opisują to zaburzenie jako przewlekłą, leczalną chorobę. Leczenie może mieć różne formy i trwać różnie długo, a leczenie farmakologiczne jest opcją opartą na dowodach.\n\nWytyczne nie wyznaczają biologicznego końca zdrowienia po trzech latach. Ten kamień milowy świętuje 1095 dni trwałego zdrowienia.';

  @override
  String get opioidReferenceDay1460 =>
      'Cztery lata - Mocny fundament\n\nŹródło: amerykańskie Centra Kontroli i Prewencji Chorób (CDC), „Leczenie zaburzenia używania opioidów”\n\nWytyczne podkreślają, że zdrowienie jest możliwe, a leczenie powinno być dopasowane do osoby, bez jednego harmonogramu dla wszystkich.\n\nCztery lata nie są biologiczną linią mety, lecz dowodem utrwalonej zmiany.';

  @override
  String get opioidReferenceDay1825 =>
      'Pięć lat - Pół dekady\n\nŹródło: amerykańskie Centra Kontroli i Prewencji Chorób (CDC), „Leczenie zaburzenia używania opioidów”\n\nWytyczne traktują zdrowienie indywidualnie i nie wskazują rocznicy, w której leczenie powinno się skończyć albo zdrowienie stać się biologicznie kompletne.\n\nPięć lat to pół dekady trwałej zmiany. To osiągnięcie jest wartościowe samo w sobie.';

  @override
  String get pornographyReferenceDay1 =>
      'Dzień pierwszy: odzyskiwanie kontroli\n\nŹródło: Kraus et al., Compulsive sexual behaviour disorder in the ICD-11, World Psychiatry (2018).\n\nKlinicznie ważnym problemem nie jest samo korzystanie z pornografii. Kompulsywne zaburzenie zachowań seksualnych definiuje się przez utrzymującą się trudność w kontrolowaniu powtarzających się zachowań seksualnych, gdy prowadzą one do istotnego cierpienia lub pogorszenia funkcjonowania. Problematyczne korzystanie z pornografii może być jedną z postaci tego szerszego problemu.\n\nDlatego pierwszy dzień ma konkretny, a nie mistyczny sens: udało Ci się przerwać zachowanie, które uznałeś za wymykające się spod kontroli. Jeden dzień nie dowodzi „resetu” mózgu ani układu nerwowego, ale daje pierwszą realną obserwację tego, kiedy pojawiają się impulsy, co je uruchamia i co możesz zrobić zamiast tego.\n\nJeśli Twoje korzystanie nie powodowało cierpienia, pogorszenia funkcjonowania ani trudności z kontrolą, kliniczne ramy CSBD mogą Cię nie dotyczyć. Te kamienie milowe są przeznaczone dla osób, które świadomie zmieniają problematyczne lub kompulsywne używanie.';

  @override
  String get pornographyReferenceDay3 =>
      'Dzień trzeci: rozpoznaj, jak może wyglądać impuls\n\nŹródło: Lewczuk et al., Withdrawal and tolerance as related to compulsive sexual behavior disorder and problematic pornography use, Journal of Behavioral Addictions (2022).\n\nW prerejestrowanej, reprezentatywnej dla Polski próbie 1 541 dorosłych silniejsze zgłaszane samodzielnie doświadczenia przypominające odstawienie wiązały się z większym nasileniem CSBD i problematycznego używania pornografii. Wśród osób z problematycznym używaniem często zgłaszano trudne do zatrzymania myśli seksualne, trudne do kontrolowania pragnienie, zwiększone pobudzenie, drażliwość, zmiany nastroju i problemy ze snem.\n\nNiepokój, natrętne myśli seksualne, silne impulsy i drażliwość są opisywane u osób z bardziej nasilonym problematycznym używaniem. Jeśli pojawiają się około trzeciego dnia, potraktuj je jako rzeczywisty wzorzec przypominający odstawienie i pracuj z wyzwalaczami.\n\nZapisz, jakie impulsy rzeczywiście się pojawiają, co je poprzedzało i jaka reakcja pomogła. Zmianą łatwiej kierować, gdy wyzwalacz jest nazwany, a nie traktowany jak tajemnicze zdarzenie w mózgu.';

  @override
  String get pornographyReferenceDay7 =>
      'Tydzień: co wykazało randomizowane badanie abstynencji\n\nŹródło: Effects of a 7-Day Pornography Abstinence Period on Withdrawal-Related Symptoms in Regular Pornography Users, Archives of Sexual Behavior (2023).\n\nBadacze losowo przydzielili 176 regularnych użytkowników pornografii do próby siedmiodniowej abstynencji albo do dalszego korzystania jak zwykle. W całej próbie abstynencja nie powodowała istotnego ogólnego wzrostu głodu, negatywnego nastroju ani objawów odstawiennych.\n\nAnaliza eksploracyjna wykazała większy głód u osób, które przed badaniem miały jednocześnie wysokie wyniki problematycznego używania i codziennie oglądały pornografię. Wynik wymaga powtórzenia, ale jest użyteczny: trudny pierwszy tydzień może być realny przy bardziej nasilonym problemie, natomiast badanie nie potwierdza uniwersalnego zespołu odstawienia pornografii.\n\nPo tygodniu masz już lepsze dane o własnym wzorcu niż te, które może dać jakakolwiek ogólna internetowa oś czasu.';

  @override
  String get pornographyReferenceDay14 =>
      'Dwa tygodnie: zmapuj wyzwalacze, które naprawdę mają znaczenie\n\nŹródło: Biopsychosocial Determinants of Problematic Pornography Use: A Systematic Review (2023).\n\nPrzegląd obejmujący 66 badań wykazał, że problematyczne korzystanie z pornografii wiąże się z kombinacją różnych czynników, a nie z jednym prostym mechanizmem dopaminowym. Do często wskazywanych czynników psychologicznych i społecznych należały głód, stres, unikanie, samotność, samoocena, negatywne przekonania i styl radzenia sobie.\n\nDwa tygodnie oznaczają wielokrotny kontakt z dniami roboczymi, weekendami, nudą, stresem, prywatnością, urządzeniami i innymi kontekstami, które mogły uruchamiać dawny schemat. Wykorzystaj te dane. Jeśli wyzwalaczem jest stres, zaplanuj reakcję na stres. Jeśli samotność, zwiększ kontakt z ludźmi. Jeśli łatwy dostęp, zmień środowisko.\n\nDowody wspierają pracę nad czynnikami podtrzymującymi problematyczne używanie; nie wymagają udawania, że każdy człowiek podlega temu samemu biologicznemu odliczaniu.';

  @override
  String get pornographyReferenceDay30 =>
      'Miesiąc: kontrola jest ważniejsza niż sama częstotliwość\n\nŹródło: Bőthe et al., Are sexual functioning problems associated with frequent pornography use and/or problematic pornography use?, Addictive Behaviors (2021).\n\nW próbie społecznościowej obejmującej 14 581 dorosłych problematyczne używanie pornografii miało umiarkowany dodatni związek z problemami funkcjonowania seksualnego zarówno u mężczyzn, jak i kobiet. Sama częstotliwość używania wykazywała słaby ujemny związek z tymi problemami.\n\nTo rozróżnienie ma znaczenie. Dowody nie wspierają twierdzenia, że sama częstotliwość oglądania szkodzi funkcjonowaniu seksualnemu każdej osoby korzystającej z pornografii. Klinicznie ważniejszym celem jest utrata kontroli i problemy otaczające ten wzorzec.\n\nPo miesiącu porównaj obecne życie z punktem wyjścia: zaabsorbowanie, utracony czas, zdolność zatrzymania się, funkcjonowanie seksualne, konflikty w relacjach i cierpienie. Te zmiany są ważniejsze niż czekanie na mityczny „reset mózgu” trzydziestego dnia.';

  @override
  String get pornographyReferenceDay90 =>
      'Trzy miesiące: trwała zmiana jest możliwa\n\nŹródło: Crosby & Twohig, Acceptance and Commitment Therapy for Problematic Internet Pornography Use: A Randomized Trial, Behavior Therapy (2016).\n\nTo małe randomizowane badanie porównało 12-sesyjny program ACT z listą oczekujących u 28 dorosłych mężczyzn. Pod koniec leczenia oglądanie pornografii spadło znacznie bardziej w grupie ACT, a istotne redukcje utrzymywały się po trzech miesiącach.\n\nBadanie nie dowodzi, że sama 90-dniowa abstynencja powoduje taki sam efekt, a próba była mała i mało zróżnicowana demograficznie. Pokazuje jednak coś ważnego: problematyczne korzystanie z pornografii można zmienić, a ustrukturyzowane umiejętności mogą dawać efekty wykraczające poza bezpośredni okres leczenia.\n\nJeśli postęp nadal opiera się głównie na zaciskaniu zębów, trzy miesiące są dobrym momentem, by wzmocnić system: plany na wyzwalacze, akceptowanie impulsów bez działania, zwiększenie trudności dostępu, odpowiedzialność wobec innych i terapię w razie potrzeby.';

  @override
  String get pornographyReferenceDay180 =>
      'Sześć miesięcy: długoterminowa kontrola objawów może się utrzymać\n\nŹródło: Hallberg et al., A Randomized Controlled Study of Group-Administered Cognitive Behavioral Therapy for Hypersexual Disorder in Men, Journal of Sexual Medicine (2019).\n\nU 137 mężczyzn z trudnym do kontrolowania zachowaniem seksualnym siedem tygodni grupowej CBT przyniosło większe spadki objawów hiperseksualności i kompulsywności seksualnej niż lista oczekujących, a także poprawę dobrostanu psychicznego. Efekty leczenia pozostawały stabilne zarówno po trzech, jak i sześciu miesiącach.\n\nBadanie dotyczyło szerzej zaburzenia hiperseksualnego, a nie samej abstynencji od pornografii, więc nie należy go zmieniać w twierdzenie, że każdy po sześciu miesiącach jest biologicznie „wyleczony”. Wspiera ono mocniejsze i bardziej użyteczne stwierdzenie: trwała poprawa kompulsywnych zachowań seksualnych może utrzymywać się przez taki okres.\n\nSześć miesięcy jest więc kamieniem milowym utrzymania zmiany. Zachowaj rutyny, które ułatwiły kontrolę, zamiast traktować datę jako pozwolenie na ich porzucenie.';

  @override
  String get pornographyReferenceDay365 =>
      'Rok: dowody na trwałą zmianę zachowania\n\nŹródło: One-year follow-up effects of an acceptance-based treatment for hypersexuality (2026).\n\nPo roku uczestnicy badania terapii opartej na akceptacji nie wrócili do poziomów hiperseksualności sprzed leczenia. Autorzy opisali wyniki jako wstępne dowody trwałych, klinicznie znaczących korzyści; jednym z obserwowanych procesów było poczucie kontroli nad głodem.\n\nTo dowody z obserwacji po leczeniu, a nie dowód na roczny „reset mózgu”. Sensowny wniosek jest lepszy: klinicznie istotna kontrola może utrzymywać się przez rok zamiast znikać wraz z końcem pierwszej interwencji.\n\nRok własnej utrzymanej zmiany to również duży osobisty zbiór danych. Porównaj obecną kontrolę, cierpienie, funkcjonowanie, relacje i wykorzystanie czasu z punktem wyjścia; klinicznie właśnie te wyniki mają znaczenie.';

  @override
  String get pornographyReferenceDay730 =>
      'Dwa lata: stabilna kontrola\n\nŹródło: Ince i wsp. (2026), przegląd dotyczący CSBD i problematycznego korzystania z pornografii.\n\nBadania opisują te problemy jako złożone i indywidualne, oceniając kontrolę, cierpienie, funkcjonowanie i kontekst. Nie ustalają uniwersalnego biologicznego progu dwóch lat.\n\nDwa lata oznaczają więc trwałe utrzymanie zmiany. Stała kontrola i lepsze funkcjonowanie są ważnymi wynikami same w sobie.';

  @override
  String get pornographyReferenceDay1095 =>
      'Trzy lata: trwała zmiana\n\nŹródło: Ince i wsp. (2026), przegląd dotyczący CSBD i problematycznego korzystania z pornografii.\n\nObecne dowody nie określają biologicznego punktu końcowego po trzech latach. Klinicznie nadal liczą się kontrola, cierpienie, ograniczenie funkcjonowania, kontekst i codzienne życie.\n\nTrzy lata świadczą o trwałości. Zmianę utrzymaną mimo różnych rutyn i okoliczności warto nadal chronić.';

  @override
  String get pornographyReferenceDay1460 =>
      'Cztery lata: trwałość\n\nŹródło: Ince i wsp. (2026), przegląd dotyczący CSBD i problematycznego korzystania z pornografii.\n\nDowody podkreślają różnice indywidualne i kontekst i nie potwierdzają uniwersalnego momentu pełnego biologicznego zakończenia zdrowienia po czterech latach.\n\nCztery lata mogą jednak pokazywać głęboką stabilność. Jeśli stary wzorzec nie kieruje już wyborami ani nie zakłóca relacji i funkcjonowania, jest to istotny wynik długoterminowy.';

  @override
  String get pornographyReferenceDay1825 =>
      'Pięć lat: wynikiem jest długoterminowa kontrola\n\nŹródło: Compulsive sexual behavior disorder and problematic pornography use: a comprehensive interdisciplinary expert-informed review (2026).\n\nWspółczesne przeglądy traktują CSBD i problematyczne korzystanie z pornografii jako złożone problemy obejmujące kontrolę, cierpienie, funkcjonowanie, kontekst i różnice indywidualne. Nie istnieje potwierdzony pięcioletni próg „resetu” mózgu i układu nerwowego.\n\nPięć lat nie jest jednak pustym kamieniem milowym. To 1 825 dni utrzymywania wybranego kierunku zachowania. Ponieważ problem kliniczny polega na trwałej utracie kontroli połączonej z cierpieniem lub pogorszeniem funkcjonowania, wieloletnia kontrola i odzyskane funkcjonowanie są znaczącymi wynikami same w sobie.\n\nNa tym etapie użyteczne pytanie nie brzmi już, czy mózg osiągnął wymyślony procent „przeprogramowania”. Ważne jest, czy dawny schemat nadal kontroluje Twoje wybory albo zakłóca życie, którego chcesz. Jeśli nie, to jest realny długoterminowy sukces.';

  @override
  String get smokingReferenceDay1 =>
      'Dzień pierwszy: korzyści zaczynają się od razu\n\nŹródło: NHS Better Health\n\nKorzyści zaczynają się w ciągu minut — nie dni. Gdy dym znika, organizm od razu zaczyna wracać do normy.\n\nCo dzieje się dziś\n• 20 minut: tętno zaczyna wracać do normy\n• 8 godzin: poziom tlenku węgla we krwi spada o połowę; poziom tlenu się odbudowuje\n• 48 godzin: poziom tlenku węgla spada do poziomu osoby niepalącej\n\nTlenek węgla wiąże się z krwinkami czerwonymi silniej niż tlen i wypiera go z krwi. Każdy narząd otrzymywał mniej tlenu, niż powinien. W ciągu dwóch dni ten proces się odwraca.\n\nObjawy odstawienia zaczynają się pierwszego dnia\n• Głód nikotynowy — pojedyncza fala zwykle trwa 3–5 minut\n• Drażliwość i trudności z koncentracją\n• Zwiększony apetyt\n\nTe objawy są przejściowe i można sobie z nimi radzić. Program NHS Better Health oferuje bezpłatne wsparcie, w tym aplikacje i porady farmaceuty.';

  @override
  String get smokingReferenceDay3 =>
      'Dzień trzeci: szczyt odstawienia\n\nŹródło: McLaughlin, Dani & De Biasi\n\nPo 72 godzinach nikotyny nie ma już w organizmie. W latach palenia mózg wytworzył dodatkowe receptory nikotynowe; teraz są słabiej pobudzane, co wywołuje zespół odstawienia.\n\nNajsilniejsze objawy\n• Głód nikotynowy — zwykle teraz jest najbardziej intensywny\n• Drażliwość, frustracja i niepokój\n• Trudności z koncentracją\n• Lęk\n• Bóle głowy\n• Zwiększony apetyt\n• Kaszel (drogi oddechowe się oczyszczają — to dobry znak)\n\nTo najtrudniejszy dzień. Potem objawy stopniowo słabną, gdy mózg ponownie się przystosowuje.\n\nNikotynowa terapia zastępcza (NRT), wareniklina i bupropion wyraźnie zmniejszają nasilenie objawów odstawienia na tym etapie.';

  @override
  String get smokingReferenceDay7 =>
      'Tydzień: smak i węch wracają\n\nŹródło: NHS Better Health\n\nTydzień bez papierosów jest silnym wskaźnikiem długoterminowego powodzenia — osoby, które przechodzą pierwszy tydzień, mają znacznie większą szansę rzucić palenie na stałe.\n\nCo się poprawiło\n• Jedzenie ma intensywniejszy smak\n• Zapachy są wyraźniejsze\n• Oddychanie jest łatwiejsze — drogi oddechowe się oczyszczają\n• Krążenie się poprawia\n• Skóra jest lepiej nawodniona\n\nPalenie bezpośrednio uszkadza receptory smaku i węchu; już kilka dni po odstawieniu zaczynają się one regenerować.\n\nOstre objawy odstawienia nikotyny słabną. Fizyczny głód trwa krócej i pojawia się rzadziej. Pragnienie wywołane konkretnymi sytuacjami może nadal występować, ale najsilniejsza fizyczna potrzeba jest już za Tobą.';

  @override
  String get smokingReferenceDay14 =>
      'Dwa tygodnie: krążenie się poprawia\n\nŹródło: NHS Better Health\n\nW ciągu 2–12 tygodni od rzucenia palenia poprawia się krążenie krwi. Nikotyna zwęża naczynia przy każdym papierosie; bez niej naczynia rozluźniają się, a krew płynie swobodniej.\n\nCo to oznacza\n• Poprawia się dopływ krwi do dłoni, stóp i tkanek obwodowych\n• Wiele osób zauważa cieplejsze dłonie i stopy\n• Chodzenie i wchodzenie po schodach zaczyna być łatwiejsze\n\nTlenek węgla został już usunięty z krwi, a krążenie się poprawia, więc tlen skuteczniej dociera do mięśni.\n\nRzęski wyściełające drogi oddechowe regenerują się i usuwają nagromadzony śluz. Jeśli kaszlesz częściej niż zwykle, może to być oznaka regeneracji, a nie pogorszenia.';

  @override
  String get smokingReferenceDay30 =>
      'Miesiąc: poprawia się funkcja płuc\n\nŹródło: NHS Better Health\n\nOddychanie staje się łatwiejsze, a funkcja płuc się poprawia — w okresie od 3 do 9 miesięcy może wzrosnąć nawet o 10%. Po miesiącu jesteś już na tej krzywej poprawy.\n\nCo dzieje się w płucach\n• Rzęski odrastają i skuteczniej usuwają śluz\n• Stan zapalny dróg oddechowych się zmniejsza\n• Uporczywy kaszel palacza zaczyna zanikać\n• Poprawia się tolerancja wysiłku\n\nKaszel, świszczący oddech i inne problemy z oddychaniem łagodnieją wraz z poprawą funkcji płuc. Miesiąc to ważny punkt na tej drodze.';

  @override
  String get smokingReferenceDay90 =>
      'Trzy miesiące: ryzyko zawału spada\n\nŹródło: PMC — Cardiovascular Effects of Smoking and Cessation (2024)\n\nPalenie uszkadza serce i tętnice na wiele sposobów: przyspiesza odkładanie blaszki miażdżycowej, sprzyja krzepnięciu krwi, podnosi ciśnienie i uszkadza wyściółkę tętnic. Działanie prozakrzepowe zaczyna się cofać w ciągu kilku dni od odstawienia, a przegląd opisuje wyraźny spadek liczby zawałów i udarów w pierwszym roku po rzuceniu palenia.\n\nCo już się poprawiło\n• Czynniki krzepnięcia krwi wracają do normy\n• Ciśnienie i tętno się stabilizują\n• Najszybszy wczesny spadek ryzyka ostrych zdarzeń sercowo-naczyniowych już trwa\n\nWolniejsze korzyści — takie jak cofanie skutków wieloletniego odkładania blaszki w tętnicach — wymagają więcej czasu i są opisane w kolejnych kamieniach milowych. Każdy miesiąc bez papierosów dokłada się do poprawy.';

  @override
  String get smokingReferenceDay180 =>
      'Sześć miesięcy: komórki odpornościowe płuc wracają do formy\n\nŹródło: Smoke-free period and recovery of alveolar immune-cell function (PubMed)\n\nPalenie może osłabiać makrofagi pęcherzykowe — komórki odpornościowe głęboko w płucach, które pochłaniają i zabijają bakterie.\n\nCo mierzono\nBadacze porównali 15 osób nigdy niepalących, 15 aktualnych palaczy i 41 byłych palaczy, którzy w czasie znieczulenia ogólnego nie palili od 2 miesięcy, 3–5 miesięcy lub 6–12 miesięcy.\n\nKonkretny sygnał regeneracji\nPodczas znieczulenia spadek fagocytozy i aktywności bakteriobójczej makrofagów pęcherzykowych był 1,5–3 razy większy u aktualnych palaczy i osób po dwóch miesiącach bez palenia niż u osób nigdy niepalących. Po 3–12 miesiącach bez palenia odpowiedzi przeciwdrobnoustrojowe były bliższe wzorcowi osób nigdy niepalących niż po dwóch miesiącach.\n\nSygnalizacja zapalna wracała do normy wolniej; różnice w odpowiedziach cytokin były widoczne do sześciu miesięcy. Sześć miesięcy to prawdziwy etap regeneracji odporności płuc, a poprawa trwa dalej.';

  @override
  String get smokingReferenceDay365 =>
      'Rok: ryzyko zawału gwałtownie spada\n\nŹródło: PMC — Smoking Cessation and Stroke Outcome; CDC, Benefits of Quitting Smoking\n\nPalenie mniej więcej podwaja ryzyko udaru, ponieważ sprzyja odkładaniu blaszki miażdżycowej, zwiększa krzepliwość krwi, podnosi ciśnienie i uszkadza naczynia mózgowe. W osi czasu CDC dotyczącej korzyści z rzucenia palenia gwałtowny spadek ryzyka zawału przypada na okres 1–2 lat — po roku jesteś na początku tego przedziału.\n\nPrzebieg regeneracji\nPełna normalizacja ryzyka udaru trwa dłużej: w cytowanym badaniu osoby, które rzuciły palenie, obserwowano przez medianę niemal pięciu lat i stwierdzono u nich wyraźnie niższy odsetek udarów niż u osób, które nadal paliły. Dane CDC umieszczają spadek dodatkowego ryzyka choroby wieńcowej o połowę w okresie 3–6 lat, a ryzyko udaru nadal maleje w okresie 5–10 lat.\n\nRok pozostaje prawdziwym medycznym kamieniem milowym — najbardziej stroma część wczesnego spadku ryzyka jest za Tobą, a długoterminowe korzyści dla serca, naczyń i ryzyka nowotworów nadal narastają przez kolejne lata.';

  @override
  String get smokingReferenceDay730 =>
      'Dwa lata: korzyści sercowo-naczyniowe trwają\n\nŹródło: CDC, korzyści z rzucenia palenia\n\nCDC podaje, że ryzyko zawału wyraźnie spada w ciągu 1–2 lat po rzuceniu palenia. Dwa lata oznaczają koniec tego przedziału opartego na dowodach, a nie nagłą zmianę w konkretnym dniu.\n\nDługoterminowy trend trwa: dodatkowe ryzyko choroby wieńcowej nadal spada i zmniejsza się o połowę w okresie 3–6 lat. Dwa lata bez palenia to powód do świętowania bez tworzenia sztucznej, dokładnej daty biologicznej.';

  @override
  String get smokingReferenceDay1095 =>
      'Trzy lata: zaczyna się okno korzyści dla serca\n\nŹródło: CDC, korzyści z rzucenia palenia\n\nCDC umieszcza spadek dodatkowego ryzyka choroby wieńcowej o połowę w okresie 3–6 lat po rzuceniu palenia. Trzy lata są początkiem tego zakresu.\n\nDowody opisują przedział czasu, a nie natychmiastowy próg. Po trzech latach długoterminowe zmniejszanie ryzyka sercowo-naczyniowego jest już wyraźnie zaawansowane i nadal postępuje.';

  @override
  String get smokingReferenceDay1460 =>
      'Cztery lata: korzyści dla serca rosną\n\nŹródło: CDC, korzyści z rzucenia palenia\n\nCztery lata bez palenia mieszczą się w okresie 3–6 lat wskazanym przez CDC, w którym dodatkowe ryzyko choroby wieńcowej spada o połowę w porównaniu z dalszym paleniem.\n\nTen zakres ma znaczenie: pozwala uniknąć twierdzenia o dokładnej biologicznej zmianie po czterech latach, a jednocześnie uznaje medycznie potwierdzony okres dużej poprawy sercowo-naczyniowej.';

  @override
  String get smokingReferenceDay1825 =>
      'Pięć lat: zaczynają się wielkie korzyści dotyczące ryzyka nowotworów\n\nŹródło: CDC, Benefits of Quitting Smoking\n\nPięć lat oznacza wejście w ważny okres wyraźnego spadku ryzyka.\n\nKamienie milowe 5–10 lat\n• Dodatkowe ryzyko nowotworów jamy ustnej, gardła i krtani: spada o połowę\n• Ryzyko udaru: maleje\n\nJeszcze przed Tobą\n• Około 10 lat: maleje ryzyko raka pęcherza, przełyku i nerki\n• 10–15 lat: dodatkowe ryzyko raka płuca spada o połowę\n• 15 lat: ryzyko choroby wieńcowej zbliża się do poziomu osoby niepalącej\n• 20 lat: ryzyko nowotworów jamy ustnej, gardła i krtani zbliża się do poziomu osoby niepalącej; dodatkowe ryzyko raka szyjki macicy spada mniej więcej o połowę\n\nPięć lat bez palenia to ogromny kamień milowy — docierasz do okresu, w którym zaczynają się duże spadki ryzyka nowotworów i udaru, a kolejne wielkie korzyści są jeszcze przed Tobą.';

  @override
  String get snriReferenceDay3 =>
      'Odstawianie SNRI: Pierwsze dni\n\nŹródło: Harvard Health Publishing\n\nWażna informacja dotycząca bezpieczeństwa\nSNRI powinny być odstawiane wyłącznie pod nadzorem medycznym i przez stopniowe zmniejszanie dawki. Wenlafaksyna (Effexor) ma szczególnie krótki okres półtrwania, około 5 godzin, dlatego szybko opuszcza organizm, a objawy odstawienne mogą być nagłe i silne.\n\nDlaczego SNRI mogą być trudniejsze do odstawienia niż SSRI\nSNRI wpływają na dwa układy neuroprzekaźników związane z nastrojem — serotoninę i noradrenalinę — dlatego po odstawieniu oba muszą się ponownie dostosować. Objawy odstawienne są często silniejsze niż przy SSRI:\n• Objawy grypopodobne (zmęczenie, pocenie się, bóle mięśni)\n• Bezsenność i zaburzenia snu\n• Nudności — często bardziej nasilone niż przy SSRI\n• Zaburzenia równowagi i zawroty głowy\n• Zaburzenia czucia — „brain zaps” mogą być szczególnie intensywne przy wenlafaksynie\n• Nadmierne pobudzenie, drażliwość i lęk\n\nPorównanie SNRI\nWenlafaksyna ma szczególnie trudny profil odstawiania z powodu krótkiego okresu półtrwania. Duloksetyna (Cymbalta) bywa nieco łatwiejsza do odstawienia dzięki dłuższemu okresowi półtrwania, około 12 godzin. Deswenlafaksyna znajduje się pomiędzy nimi.';

  @override
  String get snriReferenceDay7 =>
      'Tydzień po SNRI: Dwa układy się dostosowują\n\nŹródło: NHS — odstawianie leków przeciwdepresyjnych (ogólne zalecenia dotyczące antydepresantów; poniższe informacje o noradrenalinie wynikają z ogólnej farmakologii SNRI, a nie ze szczegółów dotyczących SNRI na stronie NHS)\n\nWyzwanie dwóch układów\nW odróżnieniu od wielu antydepresantów SNRI wpływają zarówno na serotoninę, jak i noradrenalinę. Po tygodniu oba układy są w trakcie adaptacji.\n\nWpływ układu noradrenergicznego\nNoradrenalina uczestniczy w reakcji „walcz albo uciekaj”, regulacji ciśnienia i poziomie energii. Podczas dostosowywania:\n• ciśnienie krwi może się wahać\n• lęk może być odczuwany bardziej fizycznie (kołatanie serca, pocenie)\n• poziom energii może być niestabilny\n\nWpływ układu serotoninowego\nJednocześnie dostosowuje się układ serotoninowy, co może wywoływać typowe objawy odstawienia leków przeciwdepresyjnych. Równoczesna adaptacja obu układów może szczególnie utrudniać pierwszy tydzień.\n\nFizycznie poprawa często oznacza stabilniejsze ciśnienie i mniej zawrotów głowy przy wstawaniu. Emocjonalnie nastrój jest jeszcze bardziej zmienny niż po 30 dniach, ale nie jest już w swobodnym spadku.';

  @override
  String get snriReferenceDay14 =>
      'Dwa tygodnie po SNRI: Objawy fizyczne słabną\n\nŹródło: Davies & Read (2019), Addictive Behaviors\n\nStan po dwóch tygodniach\nU większości osób po prawidłowym stopniowym zmniejszaniu dawki ostra faza fizyczna jest po dwóch tygodniach w dużej mierze za nimi:\n• brain zaps są znacznie rzadsze lub znikają\n• nudności i objawy grypopodobne ustępują\n• zawroty głowy i problemy z równowagą poprawiają się\n• ciśnienie i tętno stabilizują się wraz z adaptacją noradrenaliny\n\nCo może się utrzymywać\n• Wrażliwość emocjonalna i zmienność nastroju\n• Lęk — szczególnie związany z układem noradrenergicznym\n• Zmęczenie, ponieważ noradrenalina uczestniczy w czujności i energii\n\nKontekst badań\nPrzegląd systematyczny Davies & Read (2019) w Addictive Behaviors potwierdził, że objawy odstawienne SNRI należą do silniejszych wśród leków przeciwdepresyjnych, a wenlafaksyna jest szczególnie często związana z istotnymi objawami odstawienia.';

  @override
  String get snriReferenceDay30 =>
      'Miesiąc po SNRI: Stabilizacja dwóch układów\n\nŹródło: Davies & Read (2019), Addictive Behaviors — przegląd systematyczny częstości, nasilenia i czasu trwania objawów odstawienia antydepresantów\n\nFaza stabilizacji\nMiesiąc to ważny punkt w adaptacji serotoniny i noradrenaliny. Przegląd wykazał, że choć znaczna mniejszość osób ma objawy dłużej niż kilka tygodni, większość ma już za sobą ostrą i najcięższą fazę fizycznych objawów odstawienia.\n\nCo zwykle poprawia się do miesiąca\n• Fizyczne objawy odstawienia (brain zaps, nudności, zawroty głowy) ustępują u większości\n• Ciśnienie wraca w kierunku naturalnego poziomu\n• Jakość snu poprawia się, a rytm REM się stabilizuje\n• Poziom energii zaczyna się stabilizować wraz z regulacją noradrenaliny\n\nUstępowanie stępienia emocjonalnego\nJednym z częściej zgłaszanych doświadczeń na tym etapie jest zmniejszanie się stępienia emocjonalnego. Wiele osób podczas stosowania SNRI zauważa „spłaszczony” zakres emocji. Wraz z usuwaniem leku z organizmu i adaptacją mózgu zakres oraz wrażliwość emocjonalna zwykle wracają.';

  @override
  String get snriReferenceDay90 =>
      'Trzy miesiące po SNRI: typowy okres odstawienia za Tobą\n\nŹródło: Fava i wsp. (2018), \"Withdrawal Symptoms after Serotonin-Noradrenaline Reuptake Inhibitor Discontinuation: Systematic Review\", Psychotherapy and Psychosomatics\n\nTypowy przebieg odstawienia SNRI\nW 61 publikacjach — w tym 22 podwójnie zaślepionych randomizowanych badaniach kontrolowanych — opisywano objawy odstawienne po każdym badanym typie SNRI. Zwykle zaczynały się w ciągu kilku dni od odstawienia i trwały kilka tygodni, także przy stopniowym zmniejszaniu dawki. W publikacjach większą częstość objawów odstawiennych obserwowano przy wenlafaksynie.\n\nDlaczego 90. dzień ma znaczenie\nDziewięćdziesiąt dni to znacznie dłużej niż typowy kilkutygodniowy przebieg. Osiągnięcie trzech miesięcy oznacza, że typowy okres odstawienia SNRI jest już za Tobą.\n\nMożliwy jest dłuższy przebieg\nPrzegląd odnotował też objawy pojawiające się później lub utrzymujące się dłużej. Jeśli po trzech miesiącach nadal występują istotne objawy, omów je z osobą prowadzącą leczenie.';

  @override
  String get snriReferenceDay180 =>
      'Sześć miesięcy po SNRI: Regeneracja mózgu i nerwów\n\nSygnały poprawy po sześciu miesiącach\nSześć miesięcy po zakończeniu stopniowego odstawiania pod nadzorem medycznym ciężki, wczesny okres odstawienia SNRI jest daleko za Tobą. Nastrój, sen, funkcje seksualne i jasność myślenia miały miesiące na poprawę:\n• Szlaki serotoninowe: w dużej mierze przywrócone\n• Szlaki noradrenergiczne: znormalizowane; stabilizuje się też reakcja na stres\n• Architektura snu: oczekuje się pełnego przywrócenia\n• Funkcje seksualne: u większości w dużej mierze wracają (zaburzenia seksualne są częstym działaniem niepożądanym SNRI, ale u części osób mogą się utrzymywać i warto omówić je z lekarzem)\n\nOdporność na stres\nWiele osób po sześciu miesiącach zgłasza wyraźnie lepszą odporność na codzienne stresory, gdy rola noradrenaliny w pobudzeniu i reakcji stresowej — silnie modulowana przez SNRI — wraca w kierunku naturalnego poziomu.';

  @override
  String get snriReferenceDay365 =>
      'Rok po SNRI: Osiągnięta poprawa\n\nRok: Długotrwała adaptacja dwóch układów\nRok po zakończeniu stopniowego odstawiania SNRI układy serotoninowy i noradrenergiczny miały długi czas na adaptację i stabilizację.\n\nCo dowody rzeczywiście wspierają po roku\nPrzegląd Therapeutics Letter podaje, że udokumentowane objawy odstawienia „zwykle pojawiają się w ciągu kilku dni po odstawieniu”, a większość ustępuje w około dwa tygodnie. Nie ma kontrolowanego badania śledzącego ludzi dokładnie rok po odstawieniu SNRI. Szerszy obraz kliniczny w tym okresie wspiera następujące wnioski:\n• większość osób, które prawidłowo zmniejszały dawkę i otrzymały wsparcie psychologiczne, pozostaje w stabilnym stanie\n• stępienie emocjonalne i zaburzenia seksualne związane ze stosowaniem SNRI ustępują u większości osób\n• jasność myślenia, w tym zdolność koncentracji, jest utrzymywana przez naturalną pracę mózgu\n\nZnaczenie tego kamienia milowego\nSkuteczne odstawienie SNRI — szczególnie wenlafaksyny — jest ważnym osiągnięciem. Intensywność procesu odstawiania i wysiłek potrzebny do przejścia go pod nadzorem medycznym pokazują dużą odporność.';

  @override
  String get socialMediaReferenceDay1 =>
      'Pierwszy dzień z dala od mediów społecznościowych\n\nŹródło: Lambert i wsp., „Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial”, Cyberpsychology, Behavior, and Social Networking (2022), PubMed\n\nCo pokazują dane\nW tym kontrolowanym badaniu uczestników losowo przydzielono do tygodniowej przerwy od Facebooka, Instagrama, Twittera i TikToka albo do dalszego korzystania z nich jak zwykle. W grupie z przerwą odnotowano wyższe samopoczucie oraz mniej objawów depresji i lęku. To kontrolowany dowód, że ograniczenie mediów społecznościowych może pomóc.\n\nCo pokazują dane\nKompulsywne korzystanie z mediów społecznościowych wiąże się z gorszym nastrojem i większym lękiem, a badania z randomizacją pokazują, że celowe ograniczenie używania może poprawić samopoczucie oraz zmniejszyć objawy depresji i lęku w ciągu tygodnia.\n\nDzień pierwszy: czego można się spodziewać\n• Niepokoju i odruchu sprawdzania telefonu\n• „Fantómowych” powiadomień — wrażenia wibracji, której nie było\n• Nudy podczas przyzwyczajania się do mniejszej ilości bodźców\nTo normalne odczucia związane z nawykiem i zwykle są przejściowe. Samo rozpoznanie schematu jest pierwszym krokiem do jego zmiany.';

  @override
  String get socialMediaReferenceDay3 =>
      'Trzy dni bez mediów społecznościowych: lęk i nastrój\n\nŹródło: Lambert i wsp., „Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial”, Cyberpsychology, Behavior, and Social Networking (2022), PubMed\n\nDlaczego przerwa może poprawiać nastrój\nW tym kontrolowanym badaniu osoby losowo przydzielone do tygodniowej przerwy kończyły tydzień z mniejszym lękiem i objawami depresji oraz z wyższym samopoczuciem niż osoby nadal korzystające z mediów społecznościowych. Część codziennego obciążenia przy intensywnym używaniu bierze się z porównywania własnego życia z wyselekcjonowanymi obrazami życia innych oraz z FOMO.\n\nCo może dziać się około 72 godzin\nNa początku przerwy nawyk nadal mocno się odzywa:\n• Silny odruch sprawdzania, często wywoływany przez rutynowe chwile, np. pobudkę lub czekanie w kolejce\n• Pewna drażliwość i niepokój\n• U części osób pierwsze osłabienie lęku napędzanego porównywaniem\n• Zwyczaj przewijania przed snem zaczyna się rozluźniać\n\nPułapka porównań traci siłę\nBez stałego strumienia cudzych „najlepszych momentów” porównywanie ma mniej paliwa. Wyniki badania sugerują, że pod koniec pierwszego tygodnia te wczesne zmiany mogą składać się na mierzalną poprawę nastroju.';

  @override
  String get socialMediaReferenceDay7 =>
      'Tydzień bez mediów społecznościowych: zmierzony efekt\n\nŹródło: Lambert i wsp., „Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial”, Cyberpsychology, Behavior, and Social Networking (2022), PubMed\n\nDokładnie tydzień — i pojawił się efekt\nTo kamień milowy najlepiej odpowiadający badaniu, ponieważ sama interwencja trwała tydzień. W porównaniu z osobami, które nadal korzystały z mediów społecznościowych, grupa z przerwą miała po siedmiu dniach wyższe samopoczucie oraz mniej objawów depresji i lęku.\n\nCo ludzie często zauważają\nOprócz zmiany nastroju wiele osób zgłasza:\n• Więcej odzyskanego czasu\n• Łatwiejsze skupienie, gdy słabnie nawyk ciągłego przełączania uwagi\n• Spokojniejsze wieczory i łatwiejszy sen bez przewijania przed snem\nTe praktyczne zmiany są zgodne z poprawą samopoczucia zmierzoną w badaniu.\n\nIdź dalej\nTydzień to prawdziwy, poparty badaniem kamień milowy. Utrzymywanie zdrowszego wzorca daje coraz więcej przestrzeni na czas i uwagę poza strumieniem treści.';

  @override
  String get socialMediaReferenceDay14 =>
      'Dwa tygodnie z mocno ograniczonymi mediami społecznościowymi\n\nŹródło: Coyne i Woodruff, „Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults”, Behavioral Sciences (2023), PubMed Central\n\nO badaniu\nMłodzi dorośli ograniczyli media społecznościowe do około 30 minut dziennie przez dwa tygodnie, a użycie było obiektywnie śledzone na telefonach. Spadło o około 78%, dzięki czemu badanie bezpośrednio pokazuje, co może się dziać przy dużym ograniczeniu korzystania przez dwa tygodnie.\n\nCo się poprawiło\nW ciągu dwóch tygodni uczestnicy odnotowali poprawę w:\n• Czasie trwania i jakości snu\n• Zadowoleniu z życia\n• Stresie\n• Postrzeganym dobrostanie\n• Wynikach skal uzależnienia od smartfona i mediów społecznościowych\nMierzone zmiany obejmowały dłuższy i lepszy sen, mniejszy stres, wyższą satysfakcję z życia i dobrostan oraz niższe wyniki skal uzależnienia.\n\nUważaj na powrót starego schematu\nBadacze zauważyli też, że po interwencji użycie zaczynało wracać do wcześniejszego poziomu. Dwa tygodnie to realny postęp, ale trwałe korzyści wymagają celowego planu, nie tylko chwilowej przerwy.';

  @override
  String get socialMediaReferenceDay30 =>
      'Miesiąc z mocno ograniczonymi mediami społecznościowymi: więcej prawdziwego kontaktu\n\nŹródło: Coyne i Woodruff, „Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults”, Behavioral Sciences (2023), PubMed Central\n\nKontakt może się poprawić, gdy zrobisz krok w tył\nW tym badaniu ograniczenie mediów społecznościowych wiązało się z poprawą wspierających relacji, wyższą satysfakcją z życia i niższym stresem. Czas i uwaga, które wcześniej pochłaniał feed, mogły wrócić do ludzi obecnych w Twoim życiu.\n\nCo często przynosi miesiąc\nPo 30 dniach, gdy odruch sprawdzania jest słabszy, wiele osób zauważa:\n• Bardziej obecne i mniej przerywane rozmowy\n• Większe zainteresowanie aktywnościami i hobby w realnym świecie\n• Obraz siebie mniej zależny od polubień, komentarzy i liczby obserwujących\n\nSygnał zmiany\nPo miesiącu utrzymujesz zdrowszy schemat dwa razy dłużej niż trwała interwencja w badaniu. Wyniki zmierzone po dwóch tygodniach nie dowodzą nowego efektu dokładnie w dniu 30., ale nowe nawyki miały dodatkowy czas, by się utrwalić.\n\nWykorzystaj odzyskany czas\nWypełnij go aktywnościami budującymi prawdziwe relacje i satysfakcję, zamiast po prostu zamieniać jeden ekran na drugi.';

  @override
  String get socialMediaReferenceDay60 =>
      'Dwa miesiące z mocno ograniczonymi mediami społecznościowymi: co wspierają dane\n\nŹródło: Ramadhan i wsp., „Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed Central\n\nNajbardziej wiarygodny obraz\nBadacze połączyli wyniki 10 badań, w tym siedmiu badań kontrolowanych. Najwyraźniejszym wynikiem było zmniejszenie objawów depresyjnych po ograniczeniu lub przerwaniu korzystania z mediów społecznościowych.\n\nNajmocniejszy wynik\nAnaliza łączna wykazała spadek objawów depresyjnych. Dwa miesiące nie były odrębnym progiem klinicznym badanym w metaanalizie, ale oznaczają utrzymywanie mniejszej ekspozycji cyfrowej przez dłuższy czas.\n\nJak mogą wyglądać dwa miesiące\nMniej codziennych porównań i mniej bodźców z feedu daje więcej miejsca na obraz siebie niezależny od polubień, komentarzy czy liczby obserwujących. Najmocniejszy połączony wynik badań nadal dotyczy niższych objawów depresyjnych.\n\nPraktyczny wniosek\nDane wspierają celową, utrzymywaną zmianę. Wykorzystaj ten etap do utrzymania własnych granic i inwestowania w źródła sensu i kontaktu poza ekranem.';

  @override
  String get socialMediaReferenceDay90 =>
      'Trzy miesiące z mocno ograniczonymi mediami społecznościowymi: nowa norma\n\nŹródło: Coyne i Woodruff, „Taking a Break: The Effects of Partaking in a Two-Week Social Media Digital Detox… among Young Adults”, Behavioral Sciences (2023), PubMed Central\n\nSen był jednym z wyraźnych wyników\nUczestnicy ograniczający media społecznościowe odnotowali poprawę zarówno długości, jak i jakości snu. Badanie obejmowało dwa tygodnie, a nie konkretny próg trzech miesięcy, ale wieczorny nawyk bez przewijania miał dużo czasu, by się utrwalić.\n\nCo jeszcze się poprawiło\nW tym samym badaniu poprawiły się stres, satysfakcja z życia, postrzegany dobrostan i wspierające relacje. Te wyniki dotyczą okresu interwencji i nie ustanawiają osobnego efektu dokładnie w dniu 90.\n\nSygnał dotyczący mechanizmu\nDuże ograniczenie mediów społecznościowych poprawiło długość i jakość snu w badaniu interwencyjnym. Utrzymywanie tego schematu przez trzy miesiące może pomóc zamienić mniej nocnego przewijania w stabilniejszy zwyczaj.\n\nObecność i relacje\nGdy słabnie odruch zapełniania każdej spokojnej chwili telefonem, łatwiej być naprawdę obecnym w rozmowach, przy posiłkach i podczas odpoczynku.';

  @override
  String get socialMediaReferenceDay180 =>
      'Sześć miesięcy z mocno ograniczonymi mediami społecznościowymi: co faktycznie zmierzono\n\nŹródło: Ramadhan i wsp., „Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed Central\n\nCo wnosi metaanaliza\nŁącząc 10 badań, w tym siedem badań kontrolowanych, badacze stwierdzili spadek objawów depresyjnych po ograniczeniu lub przerwaniu korzystania z mediów społecznościowych.\n\nCo faktycznie wykazano\n• Depresja: statystycznie istotny spadek, najbardziej wyraźny i spójny wynik\n• Zadowolenie z życia: brak istotnego efektu\n• Stres: brak istotnego efektu\n• Ogólny dobrostan psychiczny: brak istotnego efektu\nNajmocniejszym wynikiem połączonych danych jest zmniejszenie objawów depresyjnych. Metaanaliza nie ustanawia osobnego progu zdrowotnego po sześciu miesiącach.\n\nDlaczego praktyczne korzyści nadal mogą być odczuwalne\nSześć miesięcy z mniejszą ekspozycją na feed to więcej czasu i mniej okazji do kompulsywnego sprawdzania. To praktyczny efekt utrzymywanego schematu, a nie twierdzenie o nowym klinicznym punkcie zwrotnym dokładnie w dniu 180.\n\nZachowaj kontrolę nad feedem\nNajwiększy sens ma przerwanie ciężkiego, biernego i kompulsywnego używania. Po sześciu miesiącach świadoma kontrola nad mediami społecznościowymi może stać się codziennym standardem.';

  @override
  String get socialMediaReferenceDay365 =>
      'Rok z mocno ograniczonymi mediami społecznościowymi: relacja ułożona na nowo\n\nŹródło: Ramadhan i wsp., „Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed Central\n\nRok utrzymywanej zmiany\nNajmocniejsze połączone dane pokazują, że ograniczenie mediów społecznościowych może zmniejszać objawy depresyjne. Badania nie definiują jednego roku jako osobnego progu zdrowotnego; ten etap świętuje długość utrzymywanej zmiany.\n\nCo buduje rok\nRok daje setki godzin na prawdziwe relacje, hobby, umiejętności, refleksję i kreatywność. Automatyczne sprawdzanie miało dużo czasu, by osłabnąć, a rutyny offline — by się wzmocnić.\n\nTrwałe korzyści\nNajwyraźniejszym zmierzonym wynikiem dotyczącym zdrowia psychicznego są niższe objawy depresyjne. Praktyczne korzyści, takie jak więcej czasu, mniej przerw i mniej kompulsywnego sprawdzania, mogą się kumulować, gdy nadal kontrolujesz swój feed.\n\nCo dalej\nRok świadomej zmiany przestawia Twoją relację z mediami społecznościowymi. Niezależnie od tego, czy pozostaniesz poza nimi, czy wrócisz do ograniczonego i celowego używania, ważne jest to, że decyzja należy do Ciebie.';

  @override
  String get ssriReferenceDay3 =>
      'Odstawienie SSRI: pierwsze dni\n\nŹródło: Harvard Health Publishing\n\nWażna informacja o bezpieczeństwie\nSSRI należy odstawiać wyłącznie pod nadzorem lekarza i po stopniowym zmniejszaniu dawki. Nagłe przerwanie leczenia — szczególnie po długotrwałym stosowaniu — wyraźnie zwiększa nasilenie objawów odstawiennych.\n\nCzym jest zespół odstawienny SSRI?\nTo dobrze udokumentowane zjawisko medyczne, które może wystąpić po odstawieniu SSRI lub znacznym zmniejszeniu dawki. Klinicyści używają skrótu FINISH, aby opisać typowe objawy:\n• Objawy grypopodobne (zmęczenie, potliwość, bóle mięśni)\n• Bezsenność i zaburzenia snu\n• Nudności\n• Zaburzenia równowagi i zawroty głowy\n• Zaburzenia czucia — szczególnie „brain zaps”\n• Nadmierne pobudzenie, drażliwość i lęk\n\nZnaczenie okresu półtrwania\nFluoksetyna (Prozac) ma bardzo długi okres półtrwania, 4–6 dni, dlatego jej stężenie spada naturalnie wolniej i objawy odstawienne są zwykle łagodniejsze. Paroksetyna (Paxil) ma jeden z najkrótszych okresów półtrwania wśród popularnych SSRI i częściej powoduje silniejsze objawy odstawienne. Sertralina, citalopram i escitalopram mieszczą się pomiędzy nimi.';

  @override
  String get ssriReferenceDay7 =>
      'Tydzień po odstawieniu SSRI: faza ostra\n\nŹródło: NHS — Stopping or coming off antidepressants\n\nOstra faza odstawienia\nNHS podaje, że większość objawów odstawienia leków przeciwdepresyjnych zaczyna się w ciągu pięciu dni od zaprzestania i u większości osób może trwać do sześciu tygodni. Po tygodniu ostre objawy fizyczne są często najbardziej wyraźne, a przy stopniowym odstawianiu zaczynają następnie słabnąć.\n\nCzego można się spodziewać po tygodniu\n• Objawy fizyczne, takie jak nudności, zawroty głowy i uczucie grypopodobne, mogą być silne, ale powinny zacząć ustępować\n• Częste są zaburzenia snu, żywe sny i bezsenność\n• Na tym etapie często występuje chwiejność emocjonalna i szybkie zmiany nastroju\n• Brain zaps mogą nadal się pojawiać, ale zwykle stopniowo występują rzadziej\n\nRola stopniowego zmniejszania dawki\nNHS zdecydowanie zaleca powolne zmniejszanie dawki — u osób długo przyjmujących lek czasem przez wiele miesięcy — aby ograniczyć objawy odstawienne. Royal College of Psychiatrists również zaleca bardzo stopniowe redukcje dawek, czasem z użyciem płynnych postaci leku, u osób długo stosujących SSRI.';

  @override
  String get ssriReferenceDay14 =>
      'Dwa tygodnie po odstawieniu SSRI: objawy fizyczne słabną\n\nŹródło: Davies & Read (2019), Addictive Behaviors — „A systematic review into the incidence, severity and duration of antidepressant withdrawal effects”\n\nCo wykazały badania\nTen przegląd systematyczny wykazał, że około 56% osób odstawiających leki przeciwdepresyjne doświadcza objawów odstawiennych, a 46% z nich opisuje je jako ciężkie. U wielu osób po prawidłowym, stopniowym zmniejszaniu dawki ostra faza po dwóch tygodniach jest w dużej mierze zakończona:\n• Brain zaps są znacznie rzadsze lub zanikają\n• Nudności i objawy grypopodobne ustępują\n• Zawroty głowy i zaburzenia równowagi się poprawiają\n• Sen zaczyna się normalizować\n\nOdróżnianie odstawienia od nawrotu\nObjawy pojawiające się w ciągu kilku dni od odstawienia i pasujące do profilu FINISH częściej wskazują na zespół odstawienny. Objawy, które pojawiają się po 2–4 tygodniach i przypominają pierwotnie leczoną chorobę, częściej wskazują na nawrót. Warto monitorować tę różnicę razem z lekarzem prowadzącym.';

  @override
  String get ssriReferenceDay30 =>
      'Miesiąc po odstawieniu SSRI: stabilizacja\n\nŹródło: Haddad PM (2001), Drug Safety — „Antidepressant Discontinuation Syndromes”\n\nFaza stabilizacji\nPrzegląd opisuje szybki początek objawów odstawiennych, zwykle w ciągu kilku dni od odstawienia lub zmniejszenia dawki antydepresantu. Większość reakcji jest łagodna i krótkotrwała oraz ustępuje bez specjalnego leczenia. Miesiąc oznacza przejście z ostrego okresu do stabilizacji; u wielu osób po stopniowym odstawianiu ostre objawy są już w dużej mierze wyciszone.\n\nZmiany emocjonalne po miesiącu\nZmiany emocjonalne są różne i warto je obserwować:\n• Niektórzy początkowo czują emocjonalne „spłaszczenie”, gdy mózg się dostosowuje — zwykle z czasem się poprawia\n• Inni odczuwają większą żywość emocji niż przez wiele wcześniejszych lat\n• Poziom lęku bardzo różni się zależnie od osoby i choroby podstawowej\n\nZnaczenie wsparcia bez leków\nPsychoterapia, w tym CBT, oraz inne oparte na dowodach formy terapii psychologicznej są skuteczne w wielu zaburzeniach leczonych SSRI. Miesiąc po odstawieniu to dobry moment, by upewnić się, że odpowiednie wsparcie jest dostępne.';

  @override
  String get ssriReferenceDay90 =>
      'Trzy miesiące: Przebieg odstawienia osiąga punkt zwrotny\n\nŹródło: Duffy i wsp., \"Antidepressant medication to prevent depression relapse in primary care: the ANTLER RCT,\" Health Technology Assessment (2021)\n\nPomiar po 12 tygodniach\nW badaniu ANTLER losowo przydzielono 478 pacjentów podstawowej opieki zdrowotnej, którzy przyjmowali leki przeciwdepresyjne przez co najmniej 9 miesięcy i czuli się na tyle dobrze, by rozważyć odstawienie. Przyjmowali citalopram, sertralinę, fluoksetynę lub mirtazapinę. Różnica w objawach odstawienia między grupą odstawiającą a grupą kontynuującą leczenie była największa po 12 tygodniach i mniejsza w późniejszych kontrolach.\n\nDlaczego to pasuje do kamienia milowego SSRI\nTrzy z czterech badanych leków — citalopram, sertralina i fluoksetyna — to SSRI. Proste podsumowanie badania wskazuje, że dodatkowe objawy odstawienia po przerwaniu leczenia koncentrowały się głównie w pierwszych 3–4 miesiącach.\n\nMocne trzy miesiące\nDzień 90 wypada dokładnie przy tym zmierzonym punkcie zwrotnym. Potem różnica w objawach odstawienia maleje, dzięki czemu trzy miesiące są konkretnym kamieniem milowym zdrowienia. Jeśli depresja lub lęk wyraźnie wracają, wcześnie skontaktuj się z osobą prowadzącą leczenie.';

  @override
  String get ssriReferenceDay180 =>
      'Sześć miesięcy po odstawieniu antydepresantów: 65% pozostało w dobrym stanie\n\nŹródło: Volkmann i wsp. (2026), European Archives of Psychiatry and Clinical Neuroscience\n\nKonkretny wynik po sześciu miesiącach\nBadanie obserwowało osoby, u których duża depresja była w remisji, podczas odstawiania leków przeciwdepresyjnych. Spośród 83 uczestników z danymi po sześciu miesiącach 54 — 65% — pozostało w dobrym stanie, a 29 miało nawrót.\n\nDlaczego ten kamień milowy ma znaczenie\nTen zmierzony wynik po sześciu miesiącach czyni ten moment realnym kamieniem milowym długoterminowej stabilności. Badanie oceniało również objawy odstawienne oddzielnie od nawrotu, pomagając rozróżnić oba zjawiska.\n\nJeśli objawy depresji wyraźnie wracają, skontaktuj się wcześnie z lekarzem prowadzącym.';

  @override
  String get ssriReferenceDay365 =>
      'Rok po długotrwałym stosowaniu leków przeciwdepresyjnych: co zmierzyło ANTLER\n\nŹródło: Duffy i wsp. (2021), Health Technology Assessment — badanie ANTLER\n\nCo naprawdę wykazało badanie\nANTLER objęło losowym przydziałem 478 dorosłych pacjentów podstawowej opieki zdrowotnej w Wielkiej Brytanii, którzy czuli się na tyle dobrze, by rozważyć odstawienie długotrwale stosowanych leków przeciwdepresyjnych. Do 52. tygodnia nawrót wystąpił u 56% osób w grupie odstawienia i u 39% w grupie leczenia podtrzymującego. Hazard nawrotu w czasie był około dwukrotnie wyższy (HR 2,06), ale obserwowane roczne odsetki nawrotów wynosiły 56% wobec 39% — nie dwa razy więcej.\n\nPełniejszy obraz\nOdstawienie nie było ślepą uliczką: 44% uczestników nie miało nawrotu w ciągu 52 tygodni badania. Średnio wyniki przemawiały jednak za leczeniem podtrzymującym: w grupie odstawienia było więcej objawów odstawiennych i mniej lat życia skorygowanych o jakość w ciągu 12 miesięcy. 39% osób przydzielonych do odstawienia wróciło do swojego pierwotnego leku przeciwdepresyjnego.\n\nTwój roczny kamień milowy\nJeśli masz za sobą rok bez leku i czujesz się dobrze, to ogromne osiągnięcie. ANTLER nie mówi, że każdy powinien pozostać na leku ani że każdy powinien go odstawić; pokazuje, dlaczego ryzyko nawrotu i decyzje o leczeniu wymagają indywidualnej kontroli. Powrót do leku, jeśli go potrzebujesz, jest decyzją kliniczną, a nie porażką.';

  @override
  String get steroidsReferenceDay1 =>
      'Odstawienie sterydów anabolicznych: pierwsze dni\n\nŹródło: \"Common symptoms associated with usage and cessation of anabolic androgenic steroids in men,\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nFaza ostra\nPrzegląd opisuje odstawienie AAS jako proces przebiegający w dwóch fazach. Pierwsza jest związana z aktywacją współczulnego układu nerwowego, a nie ze stężeniem hormonów, pojawia się w ciągu 1–2 dni od odstawienia i może obejmować:\n• Ból głowy\n• Drżenie\n• Kołatanie serca\n• Nudności\n\nDlaczego pojawiają się objawy\nSterydy anaboliczne hamują również naturalną produkcję testosteronu. Mózg wykrywa steroidy i wycisza sygnały hormonalne, które zwykle pobudzają jego wytwarzanie. To zahamowanie utrzymuje się po odstawieniu i prowadzi do drugiej, dłuższej fazy opisanej przy kolejnych kamieniach milowych.\n\nWażne dla bezpieczeństwa\nPodczas odstawiania sterydów może pojawić się depresja i może być ciężka. Warto skontaktować się z lekarzem, a przy myślach o samookaleczeniu pilnie szukać pomocy. Lekarze często wspierają przebieg regeneracji; czasem stosuje się w tym celu leki.';

  @override
  String get steroidsReferenceDay14 =>
      'Dwa tygodnie bez sterydów anabolicznych\n\nŹródło: \"Common symptoms associated with usage and cessation of anabolic androgenic steroids in men,\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\nZaczyna się dłuższa faza\nPo dwóch tygodniach krótkotrwałe objawy pobudzenia współczulnego z pierwszych dni zwykle już ustępują. Bardziej widoczna staje się druga faza, związana z utrzymującym się niedoborem testosteronu:\n• Zmęczenie i obniżony nastrój\n• Bóle mięśni (mialgia)\n• Spadek libido\n• Bezsenność i silna chęć ponownego użycia\n\nWciąż niski poziom hormonów\nNaturalna produkcja testosteronu potrzebuje znacznie więcej niż dwóch tygodni, by się odbudować. Ten etap jest więc spodziewaną częścią procesu, a nie sam w sobie oznaką, że coś jest nie tak.\n\nZnana pułapka\nNiektórzy mężczyźni wracają do sterydów właśnie po to, by uniknąć tego okresu. To uruchamia cykl od nowa zamiast go kończyć. Pomoc lekarza lub terapeuty może ułatwić przejście przez ten etap bez ponownego używania sterydów.';

  @override
  String get steroidsReferenceDay30 =>
      'Miesiąc bez sterydów anabolicznych\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" w PubMed\n\nRegeneracja się zaczyna\nPo odstawieniu ponownie uruchamiają się sygnały hormonalne, które pobudzają jądra do wytwarzania testosteronu. Badania wskazują, że duża część tej regeneracji zachodzi w ciągu trzech do sześciu miesięcy, więc po miesiącu proces jest już w toku.\n\nCzego się spodziewać\nObniżony nastrój, libido i poziom energii często utrzymują się, gdy hormony stopniowo rosną. Tempo regeneracji zależy między innymi od wieku oraz długości i intensywności wcześniejszego stosowania.';

  @override
  String get steroidsReferenceDay90 =>
      'Trzy miesiące bez sterydów anabolicznych\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" w PubMed\n\nDobry moment na badanie krwi\nPo trzech miesiącach układ hormonalny miał czas, by wykazać wyraźną regenerację. To dobry moment, by poprosić lekarza o sprawdzenie testosteronu i hormonów, które sterują jego produkcją.\n\nCzego się spodziewać\nU wielu mężczyzn po trzech miesiącach poziomy rosną, ale nie są jeszcze w pełni prawidłowe. Nastrój i libido często poprawiają się wcześniej niż testosteron całkowicie wróci do normy. Wielkość jąder i produkcja plemników regenerują się wolniej i mogą poprawiać się przez kolejny rok. Ginekomastia, jeśli się pojawiła, zwykle nie ustępuje bez ukierunkowanego leczenia.';

  @override
  String get steroidsReferenceDay180 =>
      'Sześć miesięcy bez sterydów anabolicznych\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" w PubMed\n\nCo pokazują dowody\nPrzegląd wskazuje, że LH i FSH, czyli hormony sygnalizujące jądrom produkcję testosteronu, zwykle odzyskują prawidłową aktywność w ciągu około trzech do sześciu miesięcy. Po sześciu miesiącach również regeneracja samego testosteronu jest zazwyczaj daleko posunięta.\n\nJeśli objawy nadal trwają\nJeżeli po sześciu miesiącach nadal występują objawy niskiego testosteronu, endokrynolog może sprawdzić ich przyczynę i omówić leczenie zamiast pozostawiać Cię tylko z dalszym czekaniem.';

  @override
  String get steroidsReferenceDay365 =>
      'Rok bez sterydów anabolicznych\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nRok bez sterydów\nRegeneracja po AAS jest bardzo zróżnicowana. Przegląd opisuje niemal pełny powrót testosteronu w ciągu miesięcy, powrót gonadotropin w około trzy do sześciu miesięcy oraz regenerację wielkości jąder i produkcji plemników przez miesiące lub lata. Regeneracja psychiczna jest mniej przewidywalna.\n\nRok naprawdę się liczy\nPełny rok bez sterydów to ogromny kamień milowy, ale nie uniwersalny termin, do którego wszystkie hormony muszą się unormować. Jeśli objawy niskiego testosteronu nadal występują, specjalistyczna ocena może pokazać, na jakim etapie jest regeneracja.';

  @override
  String get steroidsReferenceDay730 =>
      'Dwa lata bez sterydów anabolicznych\n\nŹródło: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\nDwa mocne lata\nDwa lata bez sterydów to długi okres bez ponownej ekspozycji. Regeneracja zależy między innymi od wieku i skali wcześniejszego używania androgenów; nie ma uniwersalnej granicy dwóch lat, po której hormony każdej osoby muszą być prawidłowe.\n\nDługi dystans\nPrzegląd opisuje regenerację testosteronu w ciągu miesięcy i gonadotropin w około trzy do sześciu miesięcy, a wielkość jąder i produkcja plemników mogą poprawiać się przez miesiące lub lata. Utrzymujące się objawy niskiego testosteronu wymagają oceny specjalisty, a nie kolejnego cyklu sterydów.';

  @override
  String get tcaReferenceDay3 =>
      'Odstawienie TCA: pierwsze dni — odbicie cholinergiczne\n\nŹródło: Dilsaver, Feinberg & Greden (1983), American Journal of Psychiatry — \'Antidepressant withdrawal symptoms treated with anticholinergic agents\' (opis 3 przypadków)\n\nDlaczego odstawienie TCA może być inne\nWiele TCA ma działanie antycholinergiczne obok wpływu na serotoninę i noradrenalinę. W trzech opublikowanych przypadkach objawy odstawienne po nagłym przerwaniu lub szybkim zmniejszeniu dawki ustąpiły po leczeniu antycholinergicznym, co skłoniło autorów do wskazania ośrodkowej nadaktywności cholinergicznej jako jednego z mechanizmów.\n\nOpisywane objawy odstawienia TCA\n• Nudności, wymioty, biegunka, ból brzucha i utrata apetytu\n• Bezsenność lub inne zaburzenia snu\n• Lęk, pobudzenie i drażliwość\n• Bóle głowy i inne objawy fizyczne\n\nTempo jest różne\nObjawy odstawienne mogą pojawić się wcześnie, zwłaszcza po nagłym przerwaniu lub szybkim zmniejszeniu dawki. Ten opis trzech przypadków wspiera odbicie cholinergiczne jako mechanizm. Badanie nie zostało zaprojektowane do ustalania stałego przebiegu dzień po dniu ani do porównywania poszczególnych TCA pod względem siły odbicia.';

  @override
  String get tcaReferenceDay7 =>
      'Tydzień po TCA: pierwszy etap za Tobą\n\nCo oznacza tydzień\nWedług NHS objawy odstawienia antydepresantów zwykle zaczynają się w ciągu kilku dni i trwają kilka tygodni. U części osób mogą być ciężkie albo utrzymywać się miesiącami lub dłużej.\n\nObjawy, które nadal mogą występować\n• Ból głowy i bóle mięśni\n• Nudności i pocenie się\n• Przyspieszone, trzepoczące, mocne lub nieregularne bicie serca\n• Zawroty głowy lub niestabilność\n• Problemy ze snem, dziwne sny i zmęczenie\n• Niepokój, drażliwość, lęk, obniżony nastrój lub trudności z myśleniem\n\nSiedem dni to postęp\nPełny tydzień bez TCA zasługuje na świętowanie. NHS opisuje odstawienie jako proces trwający od kilku dni do kilku tygodni, czasem dłużej, więc objawy związane z rytmem serca, trawieniem, snem i innymi funkcjami autonomicznymi mogą uspokajać się w różnym tempie.';

  @override
  String get tcaReferenceDay14 =>
      'Dwa tygodnie po TLPD: ostry etap odstawienia zwykle słabnie\n\nTypowe ostre okno\nPrzegląd kliniczny zespołu odstawienia leków przeciwdepresyjnych podaje, że typowe objawy — w tym objawy grypopodobne, bezsenność, nudności, zaburzenia równowagi, objawy czuciowe i nadmierne pobudzenie — zwykle trwają od jednego do dwóch tygodni.\n\nCo oznacza dzień 14\nPo dwóch tygodniach wiele osób dociera do końca klasycznej ostrej fazy odstawienia. Objawy pierwszej fali są często wyraźnie słabsze na tym etapie.\n\nCzternaście dni bez TLPD\nDzień 14 staje się więc realnym markerem zdrowienia: ostra fala odstawienia często zaczyna się załamywać, a najtrudniejszy początek zostaje z tyłu.';

  @override
  String get tcaReferenceDay30 =>
      'Miesiąc po odstawieniu TCA: ostry zespół odstawienny zwykle ustąpił\n\nTypowe ostre okno\nWarner i wsp. podają, że objawy odstawienia leków przeciwdepresyjnych są zwykle łagodne i trwają od jednego do dwóch tygodni. TCA są wyraźnie uwzględnione; po ich odstawieniu szczególnie charakterystyczne mogą być problemy z równowagą i ruchem.\n\nCo oznacza dzień 30\nPo miesiącu większość osób jest już daleko poza typową ostrą fazą. Objawy grypopodobne, nudności, zaburzenia równowagi, bezsenność, zaburzenia czucia i nadmierne pobudzenie zwykle wyraźnie słabną lub ustępują.\n\nTrzydzieści mocnych dni\nMiesiąc bez TCA to konkretny marker zdrowienia: klasyczne ostre okno odstawienia zwykle jest już za tobą.';

  @override
  String get tcaReferenceDay90 =>
      'Trzy miesiące po odstawieniu TCA: ostry zespół odstawienny daleko za tobą\n\nTypowe ostre okno\nWarner i wsp. podają, że objawy odstawienia leków przeciwdepresyjnych są zwykle łagodne i trwają od jednego do dwóch tygodni. TCA są wyraźnie uwzględnione; po ich odstawieniu szczególnie charakterystyczne mogą być problemy z równowagą i ruchem.\n\nCo oznacza 90. dzień\nPo 90 dniach jesteś ponad dziesięć tygodni za górną granicą tego typowego ostrego okna. Jeśli wystąpiły klasyczne objawy pierwszej fali—objawy grypopodobne, nudności, zaburzenia równowagi, bezsenność, zaburzenia czucia i nadmierne pobudzenie—zwykle dawno już osłabły lub ustąpiły.\n\nDziewięćdziesiąt mocnych dni\nTrzy miesiące bez TCA to konkretny marker zdrowienia: ostry zespół odstawienny zwykle jest już daleko za tobą. Jeśli wracają istotne objawy depresji, skontaktuj się wcześnie z lekarzem.';

  @override
  String get tcaReferenceDay180 =>
      'Sześć miesięcy po odstawieniu leków przeciwdepresyjnych: większość bez nawrotu\n\nSześciomiesięczny punkt kontrolny nawrotu\nMetaanaliza z 2024 roku połączyła 35 randomizowanych badań odstawiania leków przeciwdepresyjnych u osób leczonych z powodu dużej depresji. Łączny odsetek nawrotów po odstawieniu wyniósł 34,81% po sześciu miesiącach — czyli około 65% osób pozostawało wtedy bez nawrotu.\n\nRzeczywisty wynik długoterminowy\nTa sama analiza wykazała odsetek nawrotów 45,12% po 12 miesiącach. Sześć miesięcy to ważny punkt stabilności: większość uczestników połączonych badań nie doświadczyła do tego czasu nawrotu.\n\nChroń postęp\nJeśli objawy depresji zaczną wracać, wcześnie skontaktuj się z lekarzem. Sześć miesięcy to ogromny okres stabilności, który warto chronić.';

  @override
  String get tcaReferenceDay365 =>
      'Rok po odstawieniu leków przeciwdepresyjnych: większość pozostała bez nawrotu\n\nPunkt kontrolny po 12 miesiącach\nMetaanaliza z 2024 roku połączyła 35 randomizowanych badań dotyczących odstawiania leków przeciwdepresyjnych u osób leczonych z powodu dużej depresji. Łączny odsetek nawrotów po odstawieniu wyniósł 45,12% po 12 miesiącach — co odpowiada około 55% osób bez nawrotu w punkcie rocznym.\n\nPełny rok stabilności\nTa sama analiza wykazała odsetek nawrotów 34,81% po sześciu miesiącach. Po 12 miesiącach większość uczestników połączonych badań nadal nie miała nawrotu. Pełny rok bez nawrotu to ważny kamień milowy długoterminowej stabilności.\n\nChroń postęp\nJeśli objawy depresji zaczną wracać, skontaktuj się wcześnie ze swoim lekarzem lub terapeutą. Osiągnięcie pełnego roku to duży sukces, który warto chronić.';

