  @override
  String vapingStreakTitle(int days) {
    return 'Bez wapowania: dzień $days';
  }

  @override
  String get vapingDay1Description =>
      'Pierwszy dzień bez vape’a. Jeśli Twój vape zawierał nikotynę, głód, drażliwość, niepokój, gorszy nastrój, problemy ze snem albo skupieniem mogą być objawami odstawienia nikotyny — nie powodem, by znów ją podawać. Tak czy inaczej już przerywasz cykl wapowania.';

  @override
  String get vapingDay3Description =>
      'Trzy dni bez wapowania. W badaniu klinicznym byłych palaczy codziennie używających e-papierosów średni poziom objawów odstawienia osiągał szczyt 1. lub 2. dnia, a następnie spadał przez kolejne cztery dni abstynencji. Jesteś już poza wczesnym oknem szczytowym obserwowanym w tym badaniu; głód może wracać, ale nie on trzyma kierownicę.';

  @override
  String get vapingDay7Description =>
      'Pełne siedem dni bez wdychania aerozolu z vape’a. To tydzień bez nowej ekspozycji z wapowania na nikotynę, ultradrobne cząstki, metale ciężkie, lotne związki organiczne i inne szkodliwe substancje, które aerozol może zawierać. Czysta seria — jedź dalej.';

  @override
  String vapingLongStreakDescription(int days) {
    return '$days dni bez kolejnego zaciągnięcia się aerozolem z vape’a. To $days dni bez nowej ekspozycji z wapowania na szkodliwe substancje, które aerozol może zawierać. Jeśli Twój vape zawierał nikotynę, to także $days dni bez wzmacniania tej zależności. Ogromna seria — kontynuuj.';
  }

  @override
  String get vapingMilestone730Title => 'Dwa lata: moc bez wapowania';

  @override
  String get vapingMilestone730Description =>
      'Dwa lata bez wapowania. CDC podaje, że uzależnienie od nikotyny może utrudniać rzucenie, a długoterminowe skutki zdrowotne wapowania nadal są badane. Pewnym osiągnięciem jest sama ciągłość: 730 dni bez powrotu do e-papierosa.';

  @override
  String get vapingMilestone1095Title => 'Trzy lata: trwały rozpęd';

  @override
  String get vapingMilestone1095Description =>
      'Trzy lata bez wapowania. Trudna zmiana utrzymuje się już 1 095 dni. CDC nie wyznacza biologicznego progu po trzech latach, więc warto świętować to, co naprawdę wspierają dowody: trwałą wolność od wapowania.';

  @override
  String get vapingMilestone1460Title => 'Cztery lata: mocny grunt';

  @override
  String get vapingMilestone1460Description =>
      'Cztery lata bez wapowania. To 1 460 dni bez ponownego wzmacniania nawyku. Nauka nie wyznacza uniwersalnego harmonogramu długoterminowej regeneracji, ale ta trwała zmiana jest realna i zasługuje na świętowanie.';

  @override
  String get vapingMilestone1825Title => 'Pięć lat: pół dekady';

  @override
  String get vapingMilestone1825Description =>
      'Pięć lat bez wapowania. Pięć lat bez powrotu do e-papierosa to ogromne długoterminowe osiągnięcie. Dane CDC nie wyznaczają pięciu lat jako medycznego progu powrotu do zdrowia; kamieniem milowym jest utrzymana zmiana.';

  @override
  String get vapingLongTermReference =>
      'Wapowanie, rzucanie i dowody długoterminowe\n\nŹródło: CDC — Vaping and Quitting; CDC — Health Effects of Vaping\n\nCDC podaje, że osoby wapujące mogą uzależnić się od nikotyny, rzuceniu mogą towarzyszyć objawy odstawienia, a najlepsze sposoby pomagania w rzucaniu wapowania są nadal badane. Nadal badane są także długoterminowe skutki zdrowotne e-papierosów.\n\nŹródła te nie wyznaczają biologicznych progów regeneracji po dwóch, trzech, czterech ani pięciu latach. Dlatego Quitter traktuje te daty jako rocznice trwałego postępu bez wapowania, a nie medyczne punkty końcowe.';

  @override
  String get vapingWithdrawalReference =>
      'Abstynencja od e-papierosów i objawy odstawienia\n\nŹródło: Hughes i wsp., Nicotine & Tobacco Research (2020)\n\nU 109 byłych palaczy codziennie używających e-papierosów sześć dni biologicznie potwierdzonej abstynencji zwiększyło objawy odstawienia nikotyny i głód. Objawy miały typowy przebieg wzrostu i spadku, z wyraźnym nasileniem w pierwszych dwóch dniach abstynencji. Badanie potwierdza realne odstawienie e-papierosów, ale nie ustala uniwersalnego dziennego harmonogramu powrotu do zdrowia.';

  @override
  String get vapingHealthReference =>
      'Na co naraża wapowanie\n\nŹródło: CDC — Health Effects of Vaping\n\nCDC podaje, że większość e-papierosów zawiera uzależniającą nikotynę. Aerozol może zawierać nikotynę, substancje rakotwórcze, metale ciężkie takie jak nikiel, cyna i ołów, drobne cząstki docierające głęboko do płuc, lotne związki organiczne oraz niektóre szkodliwe substancje smakowe. Odstawienie nikotyny może powodować drażliwość, lęk lub niepokój, obniżony nastrój, problemy ze snem i koncentracją, głód oraz silną chęć użycia; objawy z czasem słabną. Długoterminowe skutki wapowania są nadal badane, więc Quitter celebruje realną abstynencję zamiast kopiować z papierosów terminy dotyczące tlenku węgla, smoły, raka czy ryzyka sercowego.';

  @override
  String get adderallMilestone730Title => 'Dwa lata: trwała zmiana';

  @override
  String get adderallMilestone730Description =>
      'Dwa lata bez nadużywania Adderallu to trwała zmiana, nie krótka passa. Masz już rutyny i wybory, które mogą dalej prowadzić Cię naprzód.';

  @override
  String get adderallReferenceDay730 =>
      'Dwa lata bez nadużywania Adderallu: trwały postęp\n\nŹródło: SAMHSA, Treatment of Stimulant Use Disorders\n\nPrzewodnik SAMHSA obejmuje stymulanty typu amfetaminowego, w tym nadużywanie leków stymulujących na receptę, i wspiera oparte na dowodach leczenie sprzyjające zdrowieniu. Nie wyznacza biologicznego „resetu” po dwóch latach.\n\nDwa lata to mimo wszystko wielkie osiągnięcie. Zmiana utrzymuje się od dawna; doceń zbudowaną stabilność i nadal korzystaj z tego, co Ci służy.';

  @override
  String get adderallMilestone1095Title => 'Trzy lata: mocny grunt';

  @override
  String get adderallMilestone1095Description =>
      'Trzy lata to długofalowy postęp wypracowany dzień po dniu. Nadal chroń życie, nawyki i wsparcie, które go umożliwiły.';

  @override
  String get adderallReferenceDay1095 =>
      'Trzy lata bez nadużywania Adderallu: zdrowienie z rozpędem\n\nŹródło: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA wspiera leczenie oparte na dowodach i długoterminowe zdrowienie z zaburzeń związanych z używaniem stymulantów, także leków na receptę. Przewodnik nie twierdzi, że konkretna zmiana w mózgu kończy się po trzech latach.\n\nTrzy lata oznaczają trwałą zmianę utrzymaną zarówno w zwykłe, jak i trudne dni. Zachowaj rutyny, relacje i wsparcie, które pomogły Ci dojść tak daleko.';

  @override
  String get adderallMilestone1460Title => 'Cztery lata: głębokie korzenie';

  @override
  String get adderallMilestone1460Description =>
      'Cztery lata pokazują niezwykłą konsekwencję. Ten kamień milowy celebruje trwałe odejście od nadużywania i stabilność zbudowaną wokół tej zmiany.';

  @override
  String get adderallReferenceDay1460 =>
      'Cztery lata bez nadużywania Adderallu: długoterminowa zmiana w praktyce\n\nŹródło: SAMHSA, Treatment of Stimulant Use Disorders\n\nPrzewodnik SAMHSA skupia się na leczeniu i wsparciu pomagającym osiągnąć długoterminowe zdrowienie. Nie wyznacza medycznej mety po czterech latach, więc ten kamień milowy dotyczy trwałego postępu, a nie wymyślonej obietnicy zdrowotnej.\n\nCztery lata pokazują konsekwencję w naprawdę długiej perspektywie. Dbaj o struktury i ludzi, którzy pomagają utrzymać ten postęp.';

  @override
  String get adderallMilestone1825Title => 'Pięć lat: wielki sukces';

  @override
  String get adderallMilestone1825Description =>
      'Pięć lat zasługuje na świętowanie. Przez 1 825 dni utrzymujesz inny kierunek i masz za sobą lata doświadczeń pokazujących, że zmiana może trwać.';

  @override
  String get adderallReferenceDay1825 =>
      'Pięć lat bez nadużywania Adderallu: pół dekady postępu\n\nŹródło: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA uznaje długoterminowe zdrowienie za ważny cel opieki nad osobami z zaburzeniami związanymi z używaniem stymulantów. Przewodnik nie obiecuje szczególnego wydarzenia biologicznego po pięciu latach i ten kamień milowy nie potrzebuje takiej obietnicy.\n\nPięć lat to 1 825 dni utrzymywania innego kierunku. To ogromna ilość życiowego doświadczenia pokazująca, że Twoja zmiana może trwać. Świętuj ją i nadal rób to, co ją umożliwiło.';

  @override
  String get alcoholMilestone730Title => 'Dwa lata: trwały postęp';

  @override
  String get alcoholMilestone730Description =>
      'Dwa lata bez alkoholu mieszczą się w przedziale od roku do pięciu lat, który NIAAA stosuje jako okres utrwalony w badaniach nad zdrowieniem. To duże osiągnięcie warte ochrony.';

  @override
  String get alcoholReferenceDay730 =>
      'Dwa lata bez alkoholu: trwały postęp\n\nŹródło: NIAAA, Recovery Research Definitions\n\nNIAAA używa okresu od jednego do pięciu lat jako kategorii utrwalonej dla remisji zaburzenia używania alkoholu oraz zaprzestania intensywnego picia utrzymanych w czasie. Abstynencja wykracza poza próg picia, ale sama nie potwierdza wszystkich klinicznych kryteriów remisji.\n\nDwa lata to 730 dni utrzymanej zmiany. Świętuj tę konsekwencję i dalej chroń rutyny, relacje i wsparcie, które pomagają jej trwać.';

  @override
  String get alcoholMilestone1095Title => 'Trzy lata: mocny grunt';

  @override
  String get alcoholMilestone1095Description =>
      'Trzy lata bez alkoholu to 1095 dni długotrwałej zmiany. NIAAA zalicza ten okres do utrwalonego przedziału używanego w badaniach nad zdrowieniem.';

  @override
  String get alcoholReferenceDay1095 =>
      'Trzy lata bez alkoholu: mocny grunt\n\nŹródło: NIAAA, Recovery Research Definitions\n\nNIAAA używa od jednego do pięciu lat jako utrwalonej kategorii czasu dla remisji zaburzenia używania alkoholu i zaprzestania intensywnego picia. Nie twierdzi, że w trzecim roku następuje szczególny biologiczny reset.\n\nTrzy lata to 1095 dni wzmacniania innego wzorca. Ta konsekwencja ma wartość sama w sobie, a wsparcie, które pozwoliło tu dotrzeć, warto chronić.';

  @override
  String get alcoholMilestone1460Title => 'Cztery lata: trwała zmiana';

  @override
  String get alcoholMilestone1460Description =>
      'Cztery lata bez alkoholu pokazują zmianę utrzymaną przez naprawdę długi czas. Kamieniem milowym jest sama trwałość, nie wymyślony termin medyczny.';

  @override
  String get alcoholReferenceDay1460 =>
      'Cztery lata bez alkoholu: trwała zmiana\n\nŹródło: NIAAA, Recovery Research Definitions\n\nCztery lata nadal mieszczą się w utrwalonym przedziale od jednego do pięciu lat używanym przez NIAAA w badaniach. Ramy dotyczą utrzymanej remisji i zaprzestania intensywnego picia, a nie twierdzenia, że ciało lub mózg każdej osoby osiąga tę samą metę tego samego dnia.\n\nCztery lata bez alkoholu pokazują zmianę utrzymaną przez codzienność, stres, pory roku i ważne chwile. Sama trwałość jest osiągnięciem.';

  @override
  String get alcoholMilestone1825Title => 'Pięć lat: wielki kamień milowy';

  @override
  String get alcoholMilestone1825Description =>
      'Pięć lat bez alkoholu dochodzi do górnej granicy przedziału od roku do pięciu lat NIAAA. Kategoria stabilna zaczyna się dopiero po ponad pięciu latach.';

  @override
  String get alcoholReferenceDay1825 =>
      'Pięć lat bez alkoholu: wielki kamień milowy\n\nŹródło: NIAAA, Recovery Research Definitions\n\nNIAAA nazywa okres od jednego do pięciu lat utrwalonym, a ponad pięć lat stabilnym. Dokładnie pięć lat nadal leży więc na skraju okresu utrwalonego. Ramy obejmują także remisję objawów AUD, dlatego sama abstynencja nie jest diagnozą kliniczną.\n\nPięć lat bez alkoholu to 1825 dni utrzymanej zmiany. Pół dekady zasługuje na prawdziwe uznanie bez wymyślania medycznej mety, której nie potwierdzają dowody.';

  @override
  String get ghbMilestone730Title => 'Dwa lata: Trwały postęp';

  @override
  String get ghbMilestone730Description =>
      'Dwa lata bez GHB to 730 dni utrwalanej zmiany. SAMHSA opisuje zdrowienie jako ciągły i indywidualny proces, więc ten kamień milowy celebruje konsekwencję, a nie uniwersalną granicę medyczną.';

  @override
  String get ghbReferenceDay730 =>
      'Dwa lata bez GHB: Trwały postęp\n\nŹródło: SAMHSA, Zdrowienie i wsparcie zdrowienia\n\nSAMHSA opisuje zdrowienie jako ciągły, indywidualny proces zmiany i nie wyznacza dla tych rocznic biologicznego punktu końcowego właściwego dla GHB.\n\nDwa lata to 730 dni utrzymywania innego kierunku. Ta konsekwencja oraz ludzie, nawyki i wsparcie, które ją podtrzymują, zasługują na uznanie.';

  @override
  String get ghbMilestone1095Title => 'Trzy lata: Mocniejszy grunt';

  @override
  String get ghbMilestone1095Description =>
      'Trzy lata bez GHB to 1 095 dni podtrzymywanej zmiany. Zdrowienie ma indywidualny przebieg; ten kamień milowy docenia zbudowaną stabilność, a nie wymyślony termin biologiczny.';

  @override
  String get ghbReferenceDay1095 =>
      'Trzy lata bez GHB: Mocniejszy grunt\n\nŹródło: SAMHSA, Zdrowienie i wsparcie zdrowienia\n\nSAMHSA opisuje zdrowienie jako ciągły, indywidualny proces zmiany i nie wyznacza dla tych rocznic biologicznego punktu końcowego właściwego dla GHB.\n\nTrzy lata to 1 095 dni podtrzymywanej zmiany. To znaczący zapis stabilności i dbania o to, co wspiera zdrowienie.';

  @override
  String get ghbMilestone1460Title => 'Cztery lata: Trwała zmiana';

  @override
  String get ghbMilestone1460Description =>
      'Cztery lata bez GHB to 1 460 dni trwałej zmiany. Osiągnięciem jest sama jej trwałość oraz nawyki, relacje i wsparcie, które pomagają ją podtrzymywać.';

  @override
  String get ghbReferenceDay1460 =>
      'Cztery lata bez GHB: Trwała zmiana\n\nŹródło: SAMHSA, Zdrowienie i wsparcie zdrowienia\n\nSAMHSA opisuje zdrowienie jako ciągły, indywidualny proces zmiany i nie wyznacza dla tych rocznic biologicznego punktu końcowego właściwego dla GHB.\n\nCztery lata to 1 460 dni przenoszenia zmiany przez codzienne życie. Sama trwałość jest osiągnięciem wartym świętowania.';

  @override
  String get ghbMilestone1825Title => 'Pięć lat: Wielki kamień milowy';

  @override
  String get ghbMilestone1825Description =>
      'Pięć lat bez GHB to pół dekady podtrzymywanej zmiany. SAMHSA traktuje zdrowienie jako proces ciągły, dlatego 1 825 dni samo w sobie jest warte świętowania.';

  @override
  String get ghbReferenceDay1825 =>
      'Pięć lat bez GHB: Wielki kamień milowy\n\nŹródło: SAMHSA, Zdrowienie i wsparcie zdrowienia\n\nSAMHSA opisuje zdrowienie jako ciągły, indywidualny proces zmiany i nie wyznacza dla tych rocznic biologicznego punktu końcowego właściwego dla GHB.\n\nPięć lat to 1 825 dni podtrzymywanej zmiany. Pół dekady konsekwentnych wyborów zasługuje na prawdziwe uznanie.';

  @override
  String get inhalantsMilestone1095Title => 'Trzy lata: trwały postęp';

  @override
  String get inhalantsMilestone1095Description =>
      'Trzy lata bez inhalantów to trwały postęp. Badania wspierają perspektywę długoterminowej poprawy, ale nie wyznaczają szczególnej granicy biologicznej po trzech latach.';

  @override
  String get inhalantsMilestone1460Title => 'Cztery lata: stały postęp';

  @override
  String get inhalantsMilestone1460Description =>
      'Cztery lata to kolejny znaczący okres zdrowienia. Dowody wspierają dalszą abstynencję, a nie uniwersalny koniec regeneracji mózgu dokładnie po czterech latach.';

  @override
  String get inhalantsMilestone1825Title => 'Pięć lat: mocne podstawy';

  @override
  String get inhalantsMilestone1825Description =>
      'Pięć lat to trwały postęp wart świętowania. Długotrwała abstynencja może wspierać poprawę, a wyniki nadal zależą od rodzaju i nasilenia wcześniejszych uszkodzeń.';

  @override
  String get inhalantsReferenceDay1095 =>
      'Trzy lata bez inhalantów\n\nŹródło: Cairney i wsp., „Prospektywne badanie zmian neurokognitywnych 15 lat po przewlekłym nadużywaniu inhalantów”, Addiction (2013), PubMed\n\nPoza drugim rokiem\nBadanie wykazało znaczną poprawę po dwóch latach abstynencji u osób bez encefalopatii ołowiowej i objęło tę samą kohortę obserwacją do 15 lat. Nie wskazano szczególnego progu biologicznego po trzech latach.\n\nTrzy lata postępu\nTrzy lata oznaczają utrzymaną abstynencję. Poprawa może trwać długoterminowo, a jej zakres zależy od wcześniejszej ekspozycji i uszkodzeń; encefalopatia ołowiowa może pozostawiać trwałe deficyty.';

  @override
  String get inhalantsReferenceDay1460 =>
      'Cztery lata bez inhalantów\n\nŹródło: Cairney i wsp., „Prospektywne badanie zmian neurokognitywnych 15 lat po przewlekłym nadużywaniu inhalantów”, Addiction (2013), PubMed\n\nDługoterminowa poprawa\nW grupie bez encefalopatii ołowiowej większość wyników była prawidłowa po dwóch latach, a kohortę ponownie oceniono po 15 latach. Publikacja nie przypisuje czwartej rocznicy odrębnego zdarzenia zdrowotnego.\n\nCztery lata dystansu\nCztery lata dodają kolejny pełny rok utrzymanej abstynencji i wzmacniają podstawy zdrowienia. Wyniki różnią się, zwłaszcza po ciężkich uszkodzeniach neurologicznych.';

  @override
  String get inhalantsReferenceDay1825 =>
      'Pięć lat bez inhalantów\n\nŹródło: Cairney i wsp., „Prospektywne badanie zmian neurokognitywnych 15 lat po przewlekłym nadużywaniu inhalantów”, Addiction (2013), PubMed\n\nDługoterminowy kamień milowy\nBadanie wspiera możliwość znacznej poprawy neurologicznej i poznawczej przy długotrwałej abstynencji bez encefalopatii ołowiowej. Punkty oceny przypadały po dwóch i 15 latach, więc pięć lat nie jest przedstawione jako uniwersalna granica biologiczna.\n\nPięć lat zbudowane\nPięć lat to trwały postęp i duży fragment życia bez inhalantów. Dowody wspierają długoterminową poprawę, uwzględniając możliwość utrzymywania się ciężkich uszkodzeń związanych z ołowiem.';

  @override
  String get maoiMilestone730Title => 'Dwa lata: Stabilny kierunek';

  @override
  String get maoiMilestone730Description =>
      'Dwa lata po odstawieniu inhibitora MAO to długi okres utrzymanej zmiany. Badania nad odstawieniem tranylcyprominy opisują ostre ryzyko zespołu odstawiennego, ale nie wyznaczają szczególnego biologicznego punktu końcowego po dwóch latach. Ten kamień milowy docenia konsekwencję, wsparcie i rutyny, które doprowadziły Państwa tutaj.';

  @override
  String get maoiMilestone1095Title => 'Trzy lata: Trwały postęp';

  @override
  String get maoiMilestone1095Description =>
      'Trzy lata oznaczają kolejny pełny rok utrzymywania wybranego kierunku. Badania nad odstawieniem inhibitorów MAO nie określają fizjologicznego progu zdrowienia po trzech latach; osiągnięciem jest trwały wzorzec wyborów i wsparcia budowany w codziennym życiu.';

  @override
  String get maoiMilestone1460Title => 'Cztery lata: Stała ciągłość';

  @override
  String get maoiMilestone1460Description =>
      'Cztery lata to konsekwencja utrzymana mimo zmian, stresu i codziennych rutyn. Literatura dotycząca inhibitorów MAO nie wskazuje uniwersalnej medycznej mety po czterech latach; ten kamień milowy honoruje zachowaną ciągłość.';

  @override
  String get maoiMilestone1825Title => 'Pięć lat: Trwała zmiana';

  @override
  String get maoiMilestone1825Description =>
      'Pięć lat to ważny długoterminowy kamień milowy. Dowody dotyczące odstawienia inhibitorów MAO skupiają się na ryzyku i bezpiecznym zakończeniu leczenia, a nie na dacie wyleczenia po pięciu latach. Osiągnięciem jest skala czasu, nawyków i wsparcia, które udało się utrzymać.';

  @override
  String get maoiReferenceDay730 =>
      'Dwa lata po inhibitorach MAO\n\nŹródło: Gahr i wsp. (2013), przegląd systematyczny odstawienia i objawów po przerwaniu tranylcyprominy.\n\nPrzegląd opisuje potencjalnie ciężkie zespoły po nagłym odstawieniu tranylcyprominy, lecz nie ustanawia szczególnego biologicznego progu zdrowienia po dwóch latach. Ta rocznica oznacza więc trwałą zmianę, wsparcie i rutyny, a nie medyczną metę.';

  @override
  String get maoiReferenceDay1095 =>
      'Trzy lata po inhibitorach MAO\n\nŹródło: Gahr i wsp. (2013), przegląd systematyczny odstawienia i objawów po przerwaniu tranylcyprominy.\n\nPrzegląd charakteryzuje ostre objawy odstawienne, lecz nie określa fizjologicznego punktu zdrowienia po trzech latach. Trzy lata to kolejny pełny rok utrzymywania wybranego kierunku i wsparcia, które pomogło uczynić go trwałym.';

  @override
  String get maoiReferenceDay1460 =>
      'Cztery lata po inhibitorach MAO\n\nŹródło: Gahr i wsp. (2013), przegląd systematyczny odstawienia i objawów po przerwaniu tranylcyprominy.\n\nOpublikowane dowody nie wskazują uniwersalnego biologicznego punktu końcowego po czterech latach. Ten kamień milowy odzwierciedla trwałą konsekwencję mimo zmian, stresu i rutyn, bez wymyślania klinicznego terminu.';

  @override
  String get maoiReferenceDay1825 =>
      'Pięć lat po inhibitorach MAO\n\nŹródło: Gahr i wsp. (2013), przegląd systematyczny odstawienia i objawów po przerwaniu tranylcyprominy.\n\nLiteratura omawia ryzyko odstawienia i bezpieczne zakończenie leczenia; nie określa pięciu lat jako daty wyleczenia ani uniwersalnej biologicznej mety. Pięć lat pozostaje ważnym kamieniem milowym ze względu na czas, nawyki i wsparcie utrzymane przez 1825 dni.';

  @override
  String get marijuanaMilestone730Title => 'Dwa lata: Mocne podstawy';

  @override
  String get marijuanaMilestone730Description =>
      'Dwa lata bez konopi to długi okres utrzymanej zmiany. SAMHSA zaleca opiekę dopasowaną do osoby i etapu życia, a nie jeden uniwersalny zegar zdrowienia. Ten kamień milowy docenia rutyny i wsparcie, które doprowadziły cię aż tutaj.';

  @override
  String get marijuanaReferenceDay730 =>
      'Dwa lata bez konopi\n\nŹródło: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nSAMHSA wskazuje, że zaburzenie związane z używaniem konopi różni się zależnie od osoby i etapu życia, oraz zaleca dopasowaną opiekę opartą na dowodach. Nie definiuje uniwersalnego biologicznego progu zdrowienia po dwóch latach.\n\nDwa lata oznaczają więc trwałą zmianę, rutyny i wsparcie, a nie medyczną linię mety.';

  @override
  String get marijuanaMilestone1095Title => 'Trzy lata: Trwały impet';

  @override
  String get marijuanaMilestone1095Description =>
      'Trzy lata oznaczają trwały impet. Zaburzenie związane z używaniem konopi nie przebiega identycznie u wszystkich, a SAMHSA nie wyznacza biologicznego punktu końcowego po trzech latach. Osiągnięciem jest kolejny pełny rok stabilnych wyborów i wsparcia.';

  @override
  String get marijuanaReferenceDay1095 =>
      'Trzy lata bez konopi\n\nŹródło: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nZalecenie podkreśla, że ryzyko, objawy i potrzeby leczenia związane z konopiami różnią się między osobami i etapami życia. Nie wskazuje uniwersalnego biologicznego punktu końcowego po trzech latach.\n\nTrzy lata celebrują trwałe wybory i wsparcie, które pomogło im się utrzymać.';

  @override
  String get marijuanaMilestone1460Title => 'Cztery lata: Ugruntowana zmiana';

  @override
  String get marijuanaMilestone1460Description =>
      'Cztery lata pokazują głęboko ugruntowaną zmianę. Zalecenia oparte na dowodach podkreślają indywidualne potrzeby, a nie uniwersalny próg czterech lat. Warto świętować konsekwencję utrzymaną mimo zmian rutyny, stresu i kolejnych etapów życia.';

  @override
  String get marijuanaReferenceDay1460 =>
      'Cztery lata bez konopi\n\nŹródło: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nSAMHSA zaleca zindywidualizowaną opiekę opartą na dowodach, ponieważ zaburzenie związane z używaniem konopi nie ma jednego przebiegu. Nie wyznacza uniwersalnego progu zdrowienia po czterech latach.\n\nCztery lata pokazują ciągłość mimo zmian rutyny, stresu i kolejnych etapów. To właśnie ta konsekwencja jest kamieniem milowym.';

  @override
  String get marijuanaMilestone1825Title => 'Pięć lat: Trwały postęp';

  @override
  String get marijuanaMilestone1825Description =>
      'Pięć lat to duże długoterminowe osiągnięcie. SAMHSA nie określa pięcioletniej daty wyleczenia z zaburzenia związanego z używaniem konopi. Kamieniem milowym jest pół dekady kierunku, wypracowanych rutyn i utrzymywanego wsparcia.';

  @override
  String get marijuanaReferenceDay1825 =>
      'Pięć lat bez konopi\n\nŹródło: SAMHSA (2026), Addressing Cannabis Use Disorder in Primary Care Settings—A Lifespan Approach.\n\nZalecenie SAMHSA wspiera dopasowaną opiekę na różnych etapach życia i nie określa pięcioletniej daty wyleczenia ani uniwersalnej biologicznej mety dla zaburzenia związanego z używaniem konopi.\n\nPięć lat to duże długoterminowe osiągnięcie: pół dekady kierunku, wypracowanych rutyn i wsparcia.';

  @override
  String get mdmaMilestone730Title => 'Dwa lata: mocne podstawy';

  @override
  String get mdmaMilestone730Description =>
      'Dwa lata bez MDMA oznaczają trwałą zmianę. Najlepszy obecny przegląd nie uznaje dwóch lat za biologiczny punkt odzyskania sprawności, więc ten kamień milowy celebruje konsekwencję, rutyny i wsparcie zamiast wymyślonej granicy medycznej.';

  @override
  String get mdmaReferenceDay730 =>
      'Dwa lata bez MDMA\n\nŹródło: Ung i in. (2026), przegląd systematyczny i metaanaliza długoterminowych wyników neurokognitywnych po utrzymanej abstynencji od MDMA.\n\nPrzegląd obejmował badania z co najmniej sześcioma miesiącami abstynencji, ocenił jakość dowodów jako niską i nie wykazał, by dłuższa abstynencja wiarygodnie przewidywała większą poprawę uczenia się lub pamięci. Nie ustala dwóch lat jako uniwersalnego biologicznego punktu powrotu do zdrowia.\n\nDwa lata to nadal ważny znak trwałej zmiany, zbudowany z powtarzanych wyborów, a nie z medycznej daty końcowej.';

  @override
  String get mdmaMilestone1095Title => 'Trzy lata: trwały impet';

  @override
  String get mdmaMilestone1095Description =>
      'Trzy lata to kolejny pełny rok trwałego impetu. Badania nie wyznaczają uniwersalnego neurokognitywnego punktu końcowego po trzech latach; osiągnięciem jest kierunek utrzymywany w codziennym życiu.';

  @override
  String get mdmaReferenceDay1095 =>
      'Trzy lata bez MDMA\n\nŹródło: Ung i in. (2026), przegląd systematyczny i metaanaliza utrzymanej abstynencji od MDMA.\n\nDostępne badania nie wyznaczają momentu po trzech latach, w którym skutki poznawcze powszechnie ustępują. Przegląd nie znalazł wiarygodnego związku między dłuższą abstynencją a większą poprawą uczenia się lub pamięci i ocenił dowody jako niskiej jakości.\n\nTrzy lata celebrują trwały impet i konsekwencję bez twierdzenia o nieudowodnionej biologicznej granicy.';

  @override
  String get mdmaMilestone1460Title => 'Cztery lata: głębokie korzenie';

  @override
  String get mdmaMilestone1460Description =>
      'Cztery lata odzwierciedlają głęboko utrwaloną zmianę. Dowody po długotrwałej abstynencji od MDMA pozostają ograniczone, więc warto celebrować samą ciągłość, a nie wymyślony termin powrotu do zdrowia.';

  @override
  String get mdmaReferenceDay1460 =>
      'Cztery lata bez MDMA\n\nŹródło: Ung i in. (2026), przegląd systematyczny i metaanaliza utrzymanej abstynencji od MDMA.\n\nBadania pozostają ograniczone i nie ustanawiają czterech lat jako uniwersalnego progu powrotu do zdrowia. Niektóre mierzone różnice mogą się utrzymywać, a przegląd podkreśla niską jakość dostępnych dowodów.\n\nCztery lata oznaczają głęboko utrwaloną zmianę mimo zmieniających się rutyn, napięć i etapów życia. Ta ciągłość jest osiągnięciem.';

  @override
  String get mdmaMilestone1825Title => 'Pięć lat: trwała zmiana';

  @override
  String get mdmaMilestone1825Description =>
      'Pięć lat to pół dekady utrzymanego kierunku. Obecne dowody nie uzasadniają nazywania tego uniwersalną datą wyleczenia, ale czas, nawyki i wsparcie utrzymane przez 1825 dni zasługują na uznanie.';

  @override
  String get mdmaReferenceDay1825 =>
      'Pięć lat bez MDMA\n\nŹródło: Ung i in. (2026), przegląd systematyczny i metaanaliza utrzymanej abstynencji od MDMA.\n\nObecne dowody nie uzasadniają traktowania pięciu lat jako daty wyleczenia ani uniwersalnego neurokognitywnego punktu końcowego. Przegląd znalazł ograniczone, niskiej jakości dowody i brak wiarygodnego wzorca większej poprawy uczenia się lub pamięci przy dłuższej abstynencji.\n\nPięć lat pozostaje dużym długoterminowym kamieniem milowym: pół dekady utrzymanego kierunku zasługuje na uznanie samo w sobie.';

  @override
  String get nitrousOxideMilestone730Title => 'Dwa lata - Postęp trwa';

  @override
  String get nitrousOxideMilestone730Description =>
      'Dwa lata bez podtlenku azotu to 730 dni bez ponownej ekspozycji. Wyniki neurologiczne są różne, a po zaprzestaniu używania i leczeniu często opisywana jest częściowa poprawa, dlatego ten kamień milowy świętuje trwałą ochronę, a nie sztywny medyczny termin.';

  @override
  String get nitrousOxideReferenceDay730 =>
      'Dwa lata - Postęp trwa\n\nŹródło: Marsden, Sharma i Rotella (2022), przegląd systematyczny przewlekłego używania podtlenku azotu.\n\nPrzegląd wskazał problemy neurologiczne jako charakterystyczne dla przewlekłego używania, uzupełnianie witaminy B12 jako główne leczenie oraz częściową poprawę jako najczęściej opisywany wynik. Nie określono uniwersalnego wieloletniego harmonogramu powrotu do zdrowia.\n\nDwa lata bez podtlenku azotu to 730 dni bez ponownej ekspozycji. Wyniki neurologiczne są różne, a po zaprzestaniu używania i leczeniu często opisywana jest częściowa poprawa, dlatego ten kamień milowy świętuje trwałą ochronę, a nie sztywny medyczny termin.';

  @override
  String get nitrousOxideMilestone1095Title =>
      'Trzy lata - Mocniejsza podstawa';

  @override
  String get nitrousOxideMilestone1095Description =>
      'Trzy lata to długi okres bez powrotu do ekspozycji, która tworzyła ryzyko. Badania nie przypisują regeneracji nerwów do tej rocznicy; osiągnięciem jest utrzymanie zmiany przez 1095 dni.';

  @override
  String get nitrousOxideReferenceDay1095 =>
      'Trzy lata - Mocniejsza podstawa\n\nŹródło: Marsden, Sharma i Rotella (2022), przegląd systematyczny przewlekłego używania podtlenku azotu.\n\nPrzegląd wskazał problemy neurologiczne jako charakterystyczne dla przewlekłego używania, uzupełnianie witaminy B12 jako główne leczenie oraz częściową poprawę jako najczęściej opisywany wynik. Nie określono uniwersalnego wieloletniego harmonogramu powrotu do zdrowia.\n\nTrzy lata to długi okres bez powrotu do ekspozycji, która tworzyła ryzyko. Badania nie przypisują regeneracji nerwów do tej rocznicy; osiągnięciem jest utrzymanie zmiany przez 1095 dni.';

  @override
  String get nitrousOxideMilestone1460Title => 'Cztery lata - Trwała zmiana';

  @override
  String get nitrousOxideMilestone1460Description =>
      'Cztery lata oznaczają kolejny pełny rok ochrony już osiągniętego postępu. Badania nad podtlenkiem azotu pokazują zróżnicowaną poprawę i czasem trwałe deficyty, a nie uniwersalną czteroletnią linię mety.';

  @override
  String get nitrousOxideReferenceDay1460 =>
      'Cztery lata - Trwała zmiana\n\nŹródło: Marsden, Sharma i Rotella (2022), przegląd systematyczny przewlekłego używania podtlenku azotu.\n\nPrzegląd wskazał problemy neurologiczne jako charakterystyczne dla przewlekłego używania, uzupełnianie witaminy B12 jako główne leczenie oraz częściową poprawę jako najczęściej opisywany wynik. Nie określono uniwersalnego wieloletniego harmonogramu powrotu do zdrowia.\n\nCztery lata oznaczają kolejny pełny rok ochrony już osiągniętego postępu. Badania nad podtlenkiem azotu pokazują zróżnicowaną poprawę i czasem trwałe deficyty, a nie uniwersalną czteroletnią linię mety.';

  @override
  String get nitrousOxideMilestone1825Title => 'Pięć lat - Zmiana, która trwa';

  @override
  String get nitrousOxideMilestone1825Description =>
      'Pięć lat bez podtlenku azotu to pół dekady trwałej zmiany. Nie ma opartej na dowodach daty neurologicznego „resetu” po pięciu latach; kamieniem milowym jest 1825 dni utrzymanego kierunku.';

  @override
  String get nitrousOxideReferenceDay1825 =>
      'Pięć lat - Zmiana, która trwa\n\nŹródło: Marsden, Sharma i Rotella (2022), przegląd systematyczny przewlekłego używania podtlenku azotu.\n\nPrzegląd wskazał problemy neurologiczne jako charakterystyczne dla przewlekłego używania, uzupełnianie witaminy B12 jako główne leczenie oraz częściową poprawę jako najczęściej opisywany wynik. Nie określono uniwersalnego wieloletniego harmonogramu powrotu do zdrowia.\n\nPięć lat bez podtlenku azotu to pół dekady trwałej zmiany. Nie ma opartej na dowodach daty neurologicznego „resetu” po pięciu latach; kamieniem milowym jest 1825 dni utrzymanego kierunku.';

  @override
  String get socialMediaMilestone730Title => '2 lata: Odzyskany czas';

  @override
  String get socialMediaMilestone730Description =>
      'Od dwóch lat to Ty decydujesz, gdzie kierujesz uwagę. To, co zaczęło się jako przerwa, stało się trwałym sposobem życia, w którym feed nie wyznacza rytmu dnia.';

  @override
  String get socialMediaReferenceDay730 =>
      'Dwa lata z mediami społecznościowymi na swoim miejscu\n\nŹródło: Ramadhan i in., “Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed PMID 39280291\n\nMetaanaliza objęła 10 badań interwencji typu digital detox. Ogólnie zmniejszyły się objawy depresyjne; łączne efekty dla satysfakcji z życia, stresu i ogólnego dobrostanu psychicznego nie były statystycznie istotne.\n\nBadane interwencje nie wyznaczają dwuletniego progu zdrowotnego. Dzień 730 świętuje dwa lata świadomych wyborów cyfrowych, a nie biologiczny termin „resetu”.';

  @override
  String get socialMediaMilestone1095Title => '3 lata: Uwaga pod kontrolą';

  @override
  String get socialMediaMilestone1095Description =>
      'Trzy lata to 1 095 dni trzymania mediów społecznościowych na właściwym miejscu. Rutyny, relacje i wolny czas miały lata, by rozwijać się wokół świadomych wyborów.';

  @override
  String get socialMediaReferenceDay1095 =>
      'Trzy lata: uwaga na Twoich zasadach\n\nŹródło: Ramadhan i in., “Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed PMID 39280291\n\nMetaanaliza objęła 10 badań interwencji typu digital detox. Ogólnie zmniejszyły się objawy depresyjne; łączne efekty dla satysfakcji z życia, stresu i ogólnego dobrostanu psychicznego nie były statystycznie istotne.\n\nBadania nie określają 1 095 dni jako punktu końcowego zdrowia psychicznego lub neurologicznego. To rocznica trzech lat świadomego zarządzania nawykami cyfrowymi.';

  @override
  String get socialMediaMilestone1460Title => '4 lata: Świadomy wybór na stałe';

  @override
  String get socialMediaMilestone1460Description =>
      'Cztery lata trwałej zmiany to już nie eksperyment. Ten nawyk przetrwał zmiany, stres, nudę i nowe rutyny. Właśnie ta konsekwencja jest osiągnięciem.';

  @override
  String get socialMediaReferenceDay1460 =>
      'Cztery lata: świadomy wybór stał się normą\n\nŹródło: Ramadhan i in., “Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed PMID 39280291\n\nMetaanaliza objęła 10 badań interwencji typu digital detox. Ogólnie zmniejszyły się objawy depresyjne; łączne efekty dla satysfakcji z życia, stresu i ogólnego dobrostanu psychicznego nie były statystycznie istotne.\n\nPrzegląd nie testuje czteroletniego kamienia milowego. Dzień 1 460 to rocznica zachowania: cztery lata utrzymywania zdrowszej granicy w codziennym życiu.';

  @override
  String get socialMediaMilestone1825Title => '5 lat: Życie poza feedem';

  @override
  String get socialMediaMilestone1825Description =>
      'Pięć lat to pół dekady świadomego życia cyfrowego. Ta granica istnieje już tak długo, że stała się częścią sposobu życia, a nie czymś, co wciąż trzeba udowadniać.';

  @override
  String get socialMediaReferenceDay1825 =>
      'Pięć lat: życie poza feedem\n\nŹródło: Ramadhan i in., “Impacts of digital social media detox for mental health: A systematic review and meta-analysis”, Narra J (2024), PubMed PMID 39280291\n\nMetaanaliza objęła 10 badań interwencji typu digital detox. Ogólnie zmniejszyły się objawy depresyjne; łączne efekty dla satysfakcji z życia, stresu i ogólnego dobrostanu psychicznego nie były statystycznie istotne.\n\nPrzegląd nie ustala wyników po pięciu latach. Dzień 1 825 świętuje pół dekady świadomych wyborów cyfrowych bez wymyślania terminu „resetu” mózgu.';

  @override
  String get ssriMilestone730Title => '2 lata: Stały postęp';

  @override
  String get ssriMilestone730Description =>
      'Dwa lata po odstawieniu SSRI to ważny osobisty kamień milowy. Objawy odstawienne bardzo się różnią, dlatego ta rocznica świętuje trwały postęp bez sugerowania uniwersalnego biologicznego terminu powrotu do zdrowia.';

  @override
  String get ssriReferenceDay730 =>
      'Dwa lata po SSRI: Stały postęp\n\nŹródło: Royal College of Psychiatrists — Stopping antidepressants\n\nWytyczne mówią, że leków przeciwdepresyjnych zwykle nie należy odstawiać nagle, a tempo zmniejszania dawki powinno być indywidualne. Objawy odstawienne są różne.\n\nNie wyznaczają biologicznego progu dwóch lat po SSRI. Dzień 730 świętuje dwa lata utrzymanego postępu.';

  @override
  String get ssriMilestone1095Title => '3 lata: Trwały postęp';

  @override
  String get ssriMilestone1095Description =>
      'Trzy lata po stopniowym odstawieniu SSRI to długa droga. Ta rocznica docenia stabilność, nawyki i wsparcie, które utrzymały postęp; wytyczne nie wyznaczają w tym dniu szczególnego progu zdrowienia.';

  @override
  String get ssriReferenceDay1095 =>
      'Trzy lata po SSRI: Trwały postęp\n\nŹródło: Royal College of Psychiatrists — Stopping antidepressants\n\nWytyczne podkreślają indywidualny przebieg odstawienia. Tempo redukcji zależy m.in. od długości leczenia i wcześniejszych objawów przy zmniejszaniu dawki.\n\nTrzy lata nie są uniwersalnym terminem zdrowienia po SSRI. Dzień 1095 oznacza trzy lata utrzymanego postępu.';

  @override
  String get ssriMilestone1460Title => '4 lata: Mocniejszy grunt';

  @override
  String get ssriMilestone1460Description =>
      'Cztery lata pokazują trwały postęp budowany z czasem. Odstawienie i zdrowienie są indywidualne; ten kamień milowy docenia konsekwencję bez wymyślania stałego neurologicznego harmonogramu.';

  @override
  String get ssriReferenceDay1460 =>
      'Cztery lata po SSRI: Mocniejszy grunt\n\nŹródło: Royal College of Psychiatrists — Stopping antidepressants\n\nWytyczne zalecają stopniowe, indywidualne zmniejszanie dawki, ponieważ nasilenie i czas objawów odstawiennych są różne. Niektóre osoby potrzebują miesięcy lub dłużej.\n\nNie tworzy to neurologicznego punktu końcowego po czterech latach. Dzień 1460 świętuje cztery lata trwałej zmiany.';

  @override
  String get ssriMilestone1825Title => '5 lat: Wielki kamień milowy';

  @override
  String get ssriMilestone1825Description =>
      'Pięć lat to ważny osobisty kamień milowy: pół dekady utrzymanego postępu po odstawieniu SSRI. Wytyczne nie definiują uniwersalnego pięcioletniego progu zdrowienia.';

  @override
  String get ssriReferenceDay1825 =>
      'Pięć lat po SSRI: Wielki kamień milowy\n\nŹródło: Royal College of Psychiatrists — Stopping antidepressants\n\nWytyczne skupiają się na bezpiecznym, indywidualnym odstawianiu i reagowaniu na objawy, a nie na jednym harmonogramie zdrowienia dla wszystkich.\n\nNie wyznaczają pięcioletniego progu zdrowienia po SSRI. Dzień 1825 nadal jest znaczącą rocznicą.';

  @override
  String get steroidsMilestone1095Title => 'Trzy lata — mocny fundament';

  @override
  String get steroidsMilestone1095Description =>
      'Trzy lata bez sterydów to dowód dużej konsekwencji. Powrót do zdrowia po AAS różni się między osobami; ta rocznica świętuje utrzymany czas bez ponownej ekspozycji, a nie wymyśloną biologiczną metę.';

  @override
  String get steroidsReferenceDay1095 =>
      'Trzy lata bez sterydów anabolicznych\n\nŹródło: Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review, Endocrine Connections (2023)\n\nTrzy lata dystansu\nPowrót do zdrowia po AAS jest bardzo zróżnicowany. Przegląd wskazuje, że testosteron i gonadotropiny wracają do normy w ciągu miesięcy, natomiast wielkość jąder i produkcja plemników mogą poprawiać się przez miesiące lub lata. Powrót do równowagi psychicznej jest mniej przewidywalny.\n\nZnaczenie tej rocznicy\nPrzegląd nie wyznacza biologicznej mety po trzech latach. Ten kamień milowy oznacza trzy lata bez ponownej ekspozycji. Utrzymujące się objawy hormonalne, problemy z płodnością, nastrojem lub funkcjami seksualnymi wymagają oceny medycznej.';

  @override
  String get steroidsMilestone1460Title => 'Cztery lata — trwały postęp';

  @override
  String get steroidsMilestone1460Description =>
      'Cztery lata bez kolejnego cyklu to trwały postęp. Dowody nie wyznaczają czteroletniego progu powrotu do zdrowia; ten kamień milowy świętuje utrzymany dystans od AAS i pracę, która za nim stoi.';

  @override
  String get steroidsReferenceDay1460 =>
      'Cztery lata bez sterydów anabolicznych\n\nŹródło: Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review, Endocrine Connections (2023)\n\nCztery lata konsekwencji\nPowrót do zdrowia po AAS nie przebiega według jednego zegara. Przegląd opisuje fizyczną, rozrodczą, psychiczną i biochemiczną poprawę w różnych ramach czasowych, a niektóre zmiany mogą trwać miesiące lub lata.\n\nBez wymyślonego terminu\nNie ma opartego na dowodach czteroletniego progu powrotu do zdrowia. Cztery lata bez kolejnego cyklu pozostają znaczącym osiągnięciem. Utrzymujące się objawy zasługują na osobną ocenę kliniczną.';

  @override
  String get steroidsMilestone1825Title => 'Pięć lat — trwały sukces';

  @override
  String get steroidsMilestone1825Description =>
      'Pięć lat bez sterydów to duży długoterminowy sukces. Powrót do zdrowia bywa nierówny i niektóre problemy mogą pozostać, ale pół dekady bez ponownej ekspozycji zasługuje na świętowanie.';

  @override
  String get steroidsReferenceDay1825 =>
      'Pięć lat bez sterydów anabolicznych\n\nŹródło: Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review, Endocrine Connections (2023)\n\nPięć lat to ważny kamień milowy\nDowody pokazują, że powrót do zdrowia po AAS jest bardzo zróżnicowany. Wiele zmian hormonalnych poprawia się znacznie wcześniej, natomiast skutki rozrodcze lub psychiczne mogą mieć dłuższy i mniej przewidywalny przebieg.\n\nPół dekady bez ponownej ekspozycji\nPrzegląd nie wyznacza biologicznej mety po pięciu latach. Pięć lat bez sterydów warto świętować za samą trwałość zmiany, a utrzymujące się objawy nadal powinny być oceniane medycznie.';
